"use client"

// The editor molecule's root, after frappe-ui's Editor.vue: it owns the
// tiptap instance and hands it to whatever is composed inside — a toolbar,
// the content, a counter — through context or a render prop.
import * as React from "react"
import type { Editor as TiptapEditor, Extensions } from "@tiptap/core"
import { useEditor } from "@tiptap/react"

const EditorContext = React.createContext<TiptapEditor | null>(null)

/** the editor the nearest EditorProvider holds */
export function useCurrentEditor() {
  return React.useContext(EditorContext)
}

export interface EditorProviderProps {
  extensions: Extensions
  /** what it opens with; swapped in later, it replaces the document */
  content?: string
  editable?: boolean
  onUpdate?: (html: string) => void
  onTransaction?: (editor: TiptapEditor) => void
  /** recreates the editor when these change */
  deps?: React.DependencyList
  children:
    | React.ReactNode
    | ((editor: TiptapEditor | null) => React.ReactNode)
}

export function EditorProvider({
  extensions,
  content = "",
  editable = true,
  onUpdate,
  onTransaction,
  deps = [],
  children,
}: EditorProviderProps) {
  const editor = useEditor(
    {
      immediatelyRender: false,
      editable,
      content,
      extensions,
      onTransaction: ({ editor: ed }) => onTransaction?.(ed),
      onUpdate: ({ editor: ed }) => onUpdate?.(ed.getHTML()),
    },
    deps
  )

  React.useEffect(() => {
    editor?.setEditable(editable)
  }, [editor, editable])

  // only when the caller swaps the content in later — the first run would
  // re-set what the editor opened with, and leave the caret at the end of
  // the document instead of its start
  const contentSettled = React.useRef(false)
  React.useEffect(() => {
    if (!editor) return
    if (!contentSettled.current) {
      contentSettled.current = true
      return
    }
    if (content !== editor.getHTML()) {
      editor.commands.setContent(content)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [content, editor])

  return (
    <EditorContext.Provider value={editor}>
      {typeof children === "function" ? children(editor) : children}
    </EditorContext.Provider>
  )
}

export { EditorContent } from "@tiptap/react"

"use client"

// RichTextKit, after frappe-ui's: one extension bundle for every editor in
// the project, configured per use. The field editor turns the document's
// blocks off; the document editor takes the lot. `false` drops a feature,
// an object configures it.
import { Extension, type AnyExtension } from "@tiptap/core"
import StarterKit from "@tiptap/starter-kit"
import { Details, DetailsContent, DetailsSummary } from "@tiptap/extension-details"
import Highlight from "@tiptap/extension-highlight"
import Image from "@tiptap/extension-image"
import { TaskItem, TaskList } from "@tiptap/extension-list"
import Mention from "@tiptap/extension-mention"
import Subscript from "@tiptap/extension-subscript"
import Superscript from "@tiptap/extension-superscript"
import {
  TableCell,
  TableHeader,
  TableKit,
  TableRow,
} from "@tiptap/extension-table"
import TextAlign from "@tiptap/extension-text-align"
import {
  Color,
  FontFamily,
  FontSize,
  LineHeight,
  TextStyle,
} from "@tiptap/extension-text-style"
import Youtube from "@tiptap/extension-youtube"
import { Placeholder } from "@tiptap/extensions"

import { ReactNodeViewRenderer } from "@tiptap/react"

import { BlockSelect } from "./block-select"
import { LinkEditor } from "./link-card"
import { EmbedView, ImageView } from "./media"
import {
  Attachment,
  LinkPaste,
  Audio,
  Callout,
  CommentMark,
  DetailsTweaks,
  detailsNodeView,
  Video,
  Column,
  Columns,
  Embed,
  embedFrameAttributes,
  AtomSelection,
  ListBackspace,
  EdgeKeys,
  MediaKeys,
  TabKeys,
  TabTrap,
  SmoothBlocks,
  EmbedSlot,
  ImageSlot,
  Limit,
  LinkOn,
  PEOPLE,
  SlashCommands,
  suggestionPopup,
  TableCellColor,
  TableSelectionOverlay,
} from "./extensions"

export interface RichTextKitOptions {
  /** heading levels, or false for none */
  heading?: { levels: (1 | 2 | 3 | 4 | 5 | 6)[] } | false
  placeholder?: { placeholder?: string; showOnlyWhenEditable?: boolean } | false
  textAlign?: false
  color?: false
  fontFamily?: false
  fontSize?: false
  lineHeight?: false
  highlight?: false
  image?: false
  table?: false
  taskList?: false
  details?: false
  columns?: false
  callout?: false
  attachment?: false
  audio?: false
  embed?: false
  /** the YouTube video node */
  video?: false
  mention?: false
  slashCommands?: false
  subscript?: false
  superscript?: false
  /** Tab kept on the page, Notion's way (off: Tab moves the focus on, as a
   * form's field should let it) */
  tabKeys?: false
  /** the most characters the document holds */
  limit?: number | false
}

export const RichTextKit = Extension.create<RichTextKitOptions>({
  name: "richTextKit",
  addOptions() {
    return {}
  },
  addExtensions() {
    const options = this.options
    const extensions: AnyExtension[] = [
      StarterKit.configure({
        heading:
          options.heading === false
            ? false
            : (options.heading ?? { levels: [1, 2, 3, 4, 5, 6] }),
        // the branch's own paste plugin links a selection in place of
        // tiptap's, which would swap the words for the pasted address
        link: { openOnClick: false, linkOnPaste: false },
      }),
      TextStyle,
    ]
    if (options.color !== false) extensions.push(Color)
    if (options.fontFamily !== false) extensions.push(FontFamily)
    if (options.fontSize !== false) extensions.push(FontSize)
    if (options.lineHeight !== false) extensions.push(LineHeight)
    if (options.highlight !== false)
      extensions.push(Highlight.configure({ multicolor: true }))
    if (options.image !== false)
      extensions.push(
        // the picture: its caption, size and alignment as attributes, and
        // the file's chrome drawn by the node view (media.tsx)
        Image.extend({
          addAttributes() {
            return {
              ...this.parent?.(),
              width: {
                default: null,
                parseHTML: (el: HTMLElement) => {
                  const raw = el.getAttribute("width")
                  const n = raw ? Number(raw) : NaN
                  return Number.isFinite(n) ? n : null
                },
              },
              height: {
                default: null,
                parseHTML: (el: HTMLElement) => {
                  const raw = el.getAttribute("height")
                  const n = raw ? Number(raw) : NaN
                  return Number.isFinite(n) ? n : null
                },
              },
              align: {
                default: null,
                parseHTML: (el: HTMLElement) => el.getAttribute("data-align"),
                renderHTML: (attrs: Record<string, unknown>) =>
                  attrs.align ? { "data-align": attrs.align } : {},
              },
              caption: {
                default: null,
                parseHTML: (el: HTMLElement) =>
                  el.getAttribute("data-caption"),
              },
              // a tall picture is clipped to a set height unless this is
              // turned off in its menu, when it shows whole
              clip: {
                default: true,
                parseHTML: (el: HTMLElement) =>
                  el.getAttribute("data-clip") !== "false",
                renderHTML: (attrs: Record<string, unknown>) =>
                  attrs.clip === false ? { "data-clip": "false" } : {},
              },
            }
          },
          renderHTML({ node, HTMLAttributes }) {
            const caption = node.attrs.caption as string | null
            const img = [
              "img",
              {
                ...HTMLAttributes,
                ...(caption ? { "data-caption": caption } : {}),
              },
            ] as const
            if (!caption) return img as never
            return [
              "div",
              { class: "rte-figure" },
              img,
              [
                "div",
                { class: "rte-media-caption", contenteditable: "false" },
                caption,
              ],
            ] as never
          },
          addNodeView() {
            return ReactNodeViewRenderer(ImageView)
          },
        })
      )
    if (options.textAlign !== false)
      extensions.push(TextAlign.configure({ types: ["paragraph", "heading"] }))
    if (options.table !== false) {
      // the cells carry the menu's colour as a named hue, which the
      // stylesheet tints for either theme
      const colouredCell = {
        backgroundColor: {
          default: null as string | null,
          parseHTML: (el: HTMLElement) => el.getAttribute("data-bg"),
          renderHTML: (attrs: Record<string, unknown>) =>
            attrs.backgroundColor ? { "data-bg": attrs.backgroundColor } : {},
        },
      }
      extensions.push(
        TableKit.configure({
          // the grip carries a table as one block, by selecting the table
          // node; without this the plugin turns that selection into its
          // every cell, and the grip would step aside mid-drag
          table: { resizable: true, allowTableNodeSelection: true },
          tableCell: false,
          tableHeader: false,
          tableRow: false,
        }),
        // the row carries the file's border option, drawn off `data-border`
        TableRow.extend({
          addAttributes() {
            return {
              ...this.parent?.(),
              border: {
                default: null as string | null,
                parseHTML: (el: HTMLElement) => el.getAttribute("data-border"),
                renderHTML: (attrs: Record<string, unknown>) =>
                  attrs.border ? { "data-border": attrs.border } : {},
              },
            }
          },
        }),
        TableCell.extend({
          addAttributes() {
            return { ...this.parent?.(), ...colouredCell }
          },
        }),
        TableHeader.extend({
          addAttributes() {
            return { ...this.parent?.(), ...colouredCell }
          },
        }),
        TableCellColor,
        TableSelectionOverlay
      )
    }
    if (options.taskList !== false)
      extensions.push(TaskList, TaskItem.configure({ nested: true }))
    if (options.details !== false)
      extensions.push(
        // the official details nodes, drawn to the file's markup and given
        // the branch's commands (Enter as Notion's, Toggle list, Alt-moves);
        // persist keeps `open` as a document attribute the chevron can set
        Details.extend({ addNodeView: detailsNodeView }).configure({
          persist: true,
        }),
        DetailsTweaks,
        DetailsSummary,
        // the source writes its content as div[data-type="details-content"];
        // the official node view keeps itself `hidden` until a native
        // <details> opens, which the file's markup never is — the fold is
        // the stylesheet's (styles.tsx), off the wrapper's is-open
        DetailsContent.extend({
          parseHTML() {
            return [
              { tag: 'div[data-type="details-content"]' },
              { tag: 'div[data-type="detailsContent"]' },
            ]
          },
          renderHTML({ HTMLAttributes }) {
            return [
              "div",
              { ...HTMLAttributes, "data-type": "details-content" },
              0,
            ]
          },
          addNodeView() {
            return () => {
              const dom = document.createElement("div")
              dom.setAttribute("data-type", "details-content")
              return { dom, contentDOM: dom }
            }
          },
        })
      )
    if (options.columns !== false) extensions.push(Columns, Column)
    if (options.image !== false) extensions.push(ImageSlot)
    if (options.embed !== false) extensions.push(EmbedSlot)
    extensions.push(
      LinkOn,
      LinkEditor,
      LinkPaste,
      CommentMark,
      AtomSelection,
      ListBackspace,
      EdgeKeys,
      MediaKeys,
      SmoothBlocks,
      BlockSelect
    )
    if (options.tabKeys !== false) extensions.push(TabKeys, TabTrap)
    if (options.callout !== false) extensions.push(Callout)
    if (options.attachment !== false) extensions.push(Attachment)
    if (options.audio !== false) extensions.push(Audio)
    if (options.embed !== false) extensions.push(Embed)
    if (options.video !== false)
      extensions.push(
        // the frame carries its caption, drawn centred beneath it
        Youtube.extend({
          addNodeView() {
            return ReactNodeViewRenderer(EmbedView)
          },
          addAttributes() {
            return {
              ...this.parent?.(),
              ...embedFrameAttributes,
              title: {
                default: null,
                parseHTML: (el: HTMLElement) =>
                  el.getAttribute("title") ??
                  el.querySelector("iframe")?.getAttribute("title") ??
                  null,
              },
            }
          },
          renderHTML(props) {
            const rendered = this.parent?.(props) as unknown as unknown[]
            const title = props.node.attrs.title as string | null
            if (!title || !Array.isArray(rendered)) return rendered as never
            return [
              ...rendered,
              ["div", { class: "rte-media-caption" }, title],
            ] as never
          },
        }).configure({ nocookie: true }),
        Video
      )
    // a run is raised or lowered, never both: setting one takes the other
    // off, or the lowered text would sit inside the raised one
    if (options.subscript !== false)
      extensions.push(Subscript.extend({ excludes: "subscript superscript" }))
    if (options.superscript !== false)
      extensions.push(Superscript.extend({ excludes: "superscript subscript" }))
    if (options.mention !== false)
      extensions.push(
        Mention.configure({
          HTMLAttributes: { class: "mention" },
          renderText: ({ node }) => `@${node.attrs.label ?? node.attrs.id}`,
          suggestion: {
            items: ({ query }) =>
              PEOPLE.filter((person) =>
                person.label.toLowerCase().startsWith(query.toLowerCase())
              ),
            command: ({ editor, range, props }) =>
              editor
                .chain()
                .focus()
                .insertContentAt(range, [
                  {
                    type: "mention",
                    attrs: { id: props.id, label: props.label },
                  },
                  { type: "text", text: " " },
                ])
                .run(),
            render: suggestionPopup,
          },
        })
      )
    if (options.slashCommands !== false) extensions.push(SlashCommands)
    if (options.placeholder !== false)
      extensions.push(
        Placeholder.configure({
          placeholder: "Type something...",
          showOnlyWhenEditable: false,
          ...options.placeholder,
        })
      )
    if (options.limit) extensions.push(Limit.configure({ limit: options.limit }))
    return extensions
  },
})

"use client"

// The editor molecule's extensions, after frappe-ui's src/molecules/editor:
// the palette, the document's own nodes (callout, audio, embed, columns,
// attachment), the "@" and "/" suggestion machinery, and the block/font
// tables the toolbars read. One source, so the field editor and the
// document editor never drift apart.
import * as React from "react"
import {
  Extension,
  Mark,
  mergeAttributes,
  Node,
  type ChainedCommands,
  type Editor as TiptapEditor,
} from "@tiptap/core"
import { Fragment, type Node as PMNode } from "@tiptap/pm/model"
import {
  NodeSelection,
  Plugin,
  PluginKey,
  TextSelection,
  type Transaction,
} from "@tiptap/pm/state"
import { CellSelection } from "@tiptap/pm/tables"
import {
  Decoration,
  DecorationSet,
  type EditorView as PMEditorView,
} from "@tiptap/pm/view"
import { ReactRenderer, ReactNodeViewRenderer } from "@tiptap/react"
import Suggestion, { type SuggestionProps } from "@tiptap/suggestion"

import {
  AttachmentView,
  AudioView,
  EMBED_TYPES,
  EmbedSlotView,
  EmbedView,
  ImageSlotView,
  VideoView,
  openEmbedSourcePopup,
  openImageSourcePopup,
  openRemoveEmbedModal,
} from "./media"
import { chosenBlocks } from "./block-select"

import { cn } from "@/lib/utils"
import {
  AudioWavesIcon,
  CodeIcon,
  FileUploadIcon,
  GroupIcon,
  ImageIcon,
  VideoIcon,
  DividerIcon,
  Grid2Icon,
  Grid3Icon,
  Grid4Icon,
  Grid5Icon,
  Heading1Icon,
  Heading2Icon,
  Heading3Icon,
  Heading4Icon,
  Heading5Icon,
  Heading6Icon,
  MultipleListIcon,
  NumberedListIcon,
  ParagraphIcon,
  QuoteIcon,
  SmallRightIcon,
  TableViewIcon,
  TodoIcon,
  LinkIcon,
} from "@/components/ui/rich-text-editor-icons"

export type View = TiptapEditor["view"]

/* ---------------------------------- limit -----------------------------------
 * A change that would carry the text past the limit is refused, and the
 * field's foot counts down what is left.
 */
export const Limit = Extension.create<{ limit: number }>({
  name: "editorLimit",
  addOptions: () => ({ limit: 450 }),
  addProseMirrorPlugins() {
    const { limit } = this.options
    return [
      new Plugin({
        filterTransaction: (tr, state) =>
          !tr.docChanged ||
          tr.doc.textContent.length <= limit ||
          tr.doc.textContent.length <= state.doc.textContent.length,
      }),
    ]
  },
})

/* --------------------------------- palette --------------------------------- */

export const PALETTE = [
  "red",
  "orange",
  "yellow",
  "green",
  "teal",
  "cyan",
  "blue",
  "indigo",
  "purple",
  "pink",
  "gray",
] as const
export const hue = (name: string) => (name === "indigo" ? "violet" : name)
export const textValue = (name: string) => `var(--color-${hue(name)}-600)`
export const highlightValue = (name: string) => `var(--color-${hue(name)}-100)`

/* ------------------------- table selection overlay --------------------------
 * Draws ONE rounded box around a multi-cell selection instead of ringing
 * each cell on its own: the editor takes `table-cell-range` (the per-cell
 * ring steps aside) and a `.table-selection-box` spans the union of the
 * selected cells, appended to the `.tableWrapper` so it tracks the card's
 * horizontal scroll for free. A port of the branch's extension.
 */
/** fired on window when a table's moved line starts to settle */
export const TABLE_SETTLE = "rte-table-settle"

class SelectionOverlay {
  private el: HTMLElement | null = null
  private resizeObserver: ResizeObserver | null = null
  private observed: HTMLElement | null = null
  private onResize = () => this.update(this.view)

  constructor(private view: PMEditorView) {
    window.addEventListener("resize", this.onResize)
    window.addEventListener(TABLE_SETTLE, this.onResize)
    if (typeof ResizeObserver !== "undefined")
      this.resizeObserver = new ResizeObserver(() => this.update(this.view))
    this.update(view)
  }

  update(view: PMEditorView): void {
    this.view = view
    const { selection } = view.state
    const isRange =
      selection instanceof CellSelection ||
      ("$anchorCell" in selection &&
        (selection as CellSelection).$anchorCell.pos !==
          (selection as CellSelection).$headCell.pos)
    const range =
      isRange &&
      "$anchorCell" in selection &&
      (selection as CellSelection).$anchorCell.pos !==
        (selection as CellSelection).$headCell.pos
    view.dom.classList.toggle("table-cell-range", !!range)
    if (!range) {
      this.remove()
      return
    }
    this.draw(view, selection as CellSelection)
  }

  private draw(view: PMEditorView, selection: CellSelection): void {
    let union: { left: number; top: number; right: number; bottom: number } | null =
      null
    selection.forEachCell((_cell, pos) => {
      const dom = view.nodeDOM(pos)
      if (!(dom instanceof HTMLElement)) return
      const r = dom.getBoundingClientRect()
      union = union
        ? {
            left: Math.min(union.left, r.left),
            top: Math.min(union.top, r.top),
            right: Math.max(union.right, r.right),
            bottom: Math.max(union.bottom, r.bottom),
          }
        : { left: r.left, top: r.top, right: r.right, bottom: r.bottom }
    })
    if (!union) {
      this.remove()
      return
    }
    const box: { left: number; top: number; right: number; bottom: number } =
      union
    const anchorDom = view.nodeDOM(selection.$anchorCell.pos)
    const host =
      (anchorDom instanceof HTMLElement
        ? (anchorDom.closest(".tableWrapper") as HTMLElement | null)
        : null) ?? (view.dom as HTMLElement)
    const hostRect = host.getBoundingClientRect()
    this.observe(host)
    const el = this.ensure(host)
    // the cells measure where they are drawn, mid-slide included: while a
    // moved line settles the ring waits, out of sight, and is drawn once
    // the cells have landed
    if (this.sliding(host).length) {
      el.style.visibility = "hidden"
      this.settleWith(host)
      return
    }
    el.style.left = `${box.left - hostRect.left - host.clientLeft + host.scrollLeft}px`
    el.style.top = `${box.top - hostRect.top - host.clientTop + host.scrollTop}px`
    el.style.width = `${box.right - box.left}px`
    el.style.height = `${box.bottom - box.top}px`
    this.fit(el, host, box)
    if (el.style.visibility === "hidden") {
      el.style.visibility = ""
      el.animate?.([{ opacity: 0 }, { opacity: 1 }], { duration: 120 })
    }
  }

  /**
   * The ring's corners and edges, from where the run stands in the table,
   * fitted in the same draw as its place so they never fall out of step
   * (a moved column ringed where it lands, with the corners of where it
   * landed). On the card's edge the ring keeps to the cell's own edge and
   * turns on the card's 11px inner radius; inside, it lies on the rule
   * around the run. A run reaching the foot of a scrolling card closes
   * above the card's bar.
   */
  private fit(
    el: HTMLElement,
    host: HTMLElement,
    box: { left: number; top: number; right: number; bottom: number }
  ): void {
    const table = host.querySelector("table")
    const t = table?.getBoundingClientRect()
    if (!table || !t) return
    const at = (a: number, b: number) => Math.abs(a - b) <= 1.5
    const top = at(box.top, t.top)
    const bottom = at(box.bottom, t.bottom)
    const left = at(box.left, t.left)
    const right = at(box.right, t.right)
    el.style.marginLeft = left ? "0px" : "-1px"
    el.style.paddingRight = left ? "0px" : "1px"
    el.style.marginTop = top ? "0px" : "-1px"
    el.style.paddingBottom = top ? "0px" : "1px"
    const bar = bottom
      ? Math.max(0, -parseFloat(getComputedStyle(table).marginBottom))
      : 0
    el.style.height = `${box.bottom - box.top - bar}px`
    const radius = (corner: boolean) => (corner ? "11px" : "0px")
    el.style.borderTopLeftRadius = radius(top && left)
    el.style.borderTopRightRadius = radius(top && right)
    el.style.borderBottomLeftRadius = radius(bottom && left)
    el.style.borderBottomRightRadius = radius(bottom && right)
  }

  // A row/column move settles with a WAAPI slide: for its duration the
  // cells measure at their OLD positions, and Safari fires a late update
  // mid-slide that would freeze the box there (the double-ring-after-drop
  // bug). When the table is animating, redraw once more after it lands.
  /** the table's cells still sliding into place (the ring's own fade aside) */
  private sliding(host: HTMLElement): Animation[] {
    if (typeof host.getAnimations !== "function") return []
    return host.getAnimations({ subtree: true }).filter((a) => {
      const target = (a.effect as KeyframeEffect | null)?.target
      return (
        a.playState === "running" &&
        a.effect?.getTiming().iterations !== Infinity &&
        target !== this.el
      )
    })
  }
  private settling = false
  private settleWith(host: HTMLElement): void {
    if (this.settling) return
    const anims = this.sliding(host)
    if (!anims.length) return
    this.settling = true
    Promise.allSettled(anims.map((a) => a.finished)).then(() => {
      this.settling = false
      this.update(this.view)
    })
  }

  private ensure(host: HTMLElement): HTMLElement {
    if (this.el && this.el.parentElement === host) return this.el
    this.remove()
    const el = document.createElement("div")
    el.className = "table-selection-box"
    el.setAttribute("aria-hidden", "true")
    host.appendChild(el)
    this.el = el
    return el
  }

  private observe(host: HTMLElement): void {
    if (!this.resizeObserver || this.observed === host) return
    this.resizeObserver.disconnect()
    this.resizeObserver.observe(host)
    this.observed = host
  }

  private remove(): void {
    this.el?.remove()
    this.el = null
    this.resizeObserver?.disconnect()
    this.observed = null
  }

  destroy(): void {
    this.view.dom.classList.remove("table-cell-range")
    this.remove()
    window.removeEventListener("resize", this.onResize)
    window.removeEventListener(TABLE_SETTLE, this.onResize)
    this.resizeObserver = null
  }
}

export const TableSelectionOverlay = Extension.create({
  name: "tableSelectionOverlay",
  addProseMirrorPlugins() {
    return [new Plugin({ view: (view) => new SelectionOverlay(view) })]
  },
})

/* ------------------------------ cell colours -------------------------------
 * The cells' named fills, as the branch's TableCellColor: the attribute
 * stores the hue and renders as `data-bg`, which the stylesheet tints for
 * either theme; `setCellBackground` fans out over the selected cells
 * through the table extension's own setCellAttribute.
 */
declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    tableCellColor: {
      /** Fill the selected cell(s) with a named background; `null` clears it. */
      setCellBackground: (name: string | null) => ReturnType
    }
  }
}

export const TableCellColor = Extension.create({
  name: "tableCellColor",
  addCommands() {
    return {
