export interface CommentReply {
  who: string
  image?: string
  when: string
  text: string
}
export interface CommentThread {
  id: string
  replies: CommentReply[]
}

export interface RichTextEditorProps {
  /** what it opens with */
  content?: string
  editable?: boolean
  placeholder?: string
  className?: string
  onChange?: (html: string) => void
  /** the threads the document opens with, one per amber comment run */
  initialComments?: CommentThread[]
  /** who a sent reply is from */
  commenter?: { who: string; image?: string }
}

export function RichTextEditor({
  content = "",
  editable = true,
  placeholder = "Type / for blocks, @ to mention...",
  className,
  onChange,
  initialComments,
  commenter,
}: RichTextEditorProps) {
  // ---- comments: a thread per amber run, shown beside the selection
  const [threads, setThreads] = React.useState<CommentThread[]>(
    () => initialComments ?? []
  )
  const [openThread, setOpenThread] = React.useState<string | null>(null)
  const [threadTop, setThreadTop] = React.useState(0)
  const [reply, setReply] = React.useState("")
  const stageRef = React.useRef<HTMLDivElement>(null)
  const editorRef = React.useRef<TiptapEditor | null>(null)

  const show = React.useCallback((id: string) => {
    setOpenThread(id)
    requestAnimationFrame(() => {
      const stage = stageRef.current
      const el = stage?.querySelector<HTMLElement>(`[data-comment="${id}"]`)
      const box = stage?.getBoundingClientRect()
      if (el && box)
        setThreadTop(el.getBoundingClientRect().top - box.top)
    })
  }, [])
  const comment = React.useCallback(() => {
    const ed = editorRef.current
    if (!ed) return
    const existing = ed.getAttributes("comment").id as string | undefined
    if (existing) {
      show(existing)
      return
    }
    if (ed.state.selection.empty) return
    const id = `c${Date.now()}`
    ed.chain().focus().setComment(id).run()
    setThreads((t) => [...t, { id, replies: [] }])
    show(id)
  }, [show])
  const onEditorClick = (e: React.MouseEvent) => {
    const run = (e.target as HTMLElement).closest<HTMLElement>(
      "[data-comment]"
    )
    if (run && run.dataset.comment) show(run.dataset.comment)
    else setOpenThread(null)
  }
  const current = threads.find((t) => t.id === openThread)
  const send = () => {
    const text = reply.trim()
    if (!current || !text) return
    setThreads((all) =>
      all.map((t) =>
        t.id === current.id
          ? {
              ...t,
              replies: [
                ...t.replies,
                {
                  who: commenter?.who ?? "You",
                  image: commenter?.image,
                  when: "now",
                  text,
                },
              ],
            }
          : t
      )
    )
    setReply("")
  }
  const resolve = () => {
    const ed = editorRef.current
    if (!current || !ed) return
    // the run goes with the thread
    ed.state.doc.descendants((node, pos) => {
      const mark = node.marks.find(
        (m) => m.type.name === "comment" && m.attrs.id === current.id
      )
      if (mark)
        ed.chain()
          .setTextSelection({ from: pos, to: pos + node.nodeSize })
          .unsetComment()
          .run()
    })
    setThreads((all) => all.filter((x) => x.id !== current.id))
    setOpenThread(null)
  }

  return (
    <EditorProvider
      extensions={[RichTextKit.configure({ placeholder: { placeholder } })]}
      content={content}
      editable={editable}
      onUpdate={onChange}
      deps={[placeholder]}
    >
      {(editor) => {
        editorRef.current = editor
        return (
          <div
            ref={stageRef}
            data-slot="rich-text-editor"
            {...(!editable && { "data-readonly": "" })}
            className={cn(
              "rte relative flex min-h-0 w-full max-w-[1300px] min-w-0 flex-col overflow-hidden rounded-2xl border border-border-soft bg-background",
              !editable && "is-readonly",
              className
            )}
          >
            <EditorStyles />
            {editor && editable && (
              <RichTextToolbar editor={editor} onComment={comment} />
            )}
            {editor && editable && <BlockHandle editor={editor} />}
            {editor && editable && <TableControls editor={editor} />}
            {editor && editable && <ColumnResizer editor={editor} />}
            {editor && editable && <BlockMarquee editor={editor} />}
            {editor && editable && <LinkClickCard editor={editor} />}
            {editor && editable && (
              <BubbleMenu
                editor={editor}
                options={{ placement: "top" }}
                getReferencedVirtualElement={() => selectionBox(editor)}
                shouldShow={({ editor: ed, state, from, to }) => {
                  const { selection } = state
                  if (selection.empty || "node" in selection || !ed.isEditable)
                    return false
                  // a selected row, column or run of cells has the table's
                  // own menus
                  if ("$anchorCell" in selection) return false
                  return state.doc.textBetween(from, to).length > 0
                }}
                className="z-60"
              >
                <SelectionBar editor={editor} />
              </BubbleMenu>
            )}
            <div
              data-slot="rich-text-editor-scroll"
              className="min-h-0 flex-1 overflow-y-auto"
            >
              <div className="px-4 py-8 sm:px-8" onClick={onEditorClick}>
                <EditorContent
                  editor={editor}
                  className={cn(
                    "rte-doc mx-auto w-full max-w-[700px]",
                    docClassName
                  )}
                />
              </div>
            </div>

            {/* the thread beside the run: the file's comment card —
                300px on a 12px radius under the xl shadow, a 32px header
                ruled beneath, a reply per 24px avatar, the reply field */}
            {current && (
              <div
                className="rte-thread absolute right-6 z-20 flex w-[300px] flex-col gap-3.5 rounded-xl bg-card pb-2.5 shadow-elevation-xl dark:[--background:var(--card)]"
                style={{ top: Math.max(48, threadTop - 8) }}
                role="dialog"
                aria-label="Comment thread"
              >
                {/* 32px: 10 in, the title, three 24px controls, 4 out */}
                <div className="rte-thread-head flex h-8 items-center py-1 pr-1 pl-2.5">
                  <span className="flex-1 text-sm leading-4 font-medium text-accent-foreground">
                    Comment
                  </span>
                  <button
                    type="button"
                    className="rte-thread-btn"
                    aria-label="More"
                    title="More"
                  >
                    <DotHorizontalIcon className="size-3.5" />
                  </button>
                  <button
                    type="button"
                    className="rte-thread-btn"
                    aria-label="Resolve"
                    title="Resolve"
                    onClick={resolve}
                  >
                    <CheckCircleIcon className="size-3.5" />
                  </button>
                  <button
                    type="button"
                    className="rte-thread-btn"
                    aria-label="Close"
                    title="Close"
                    onClick={() => setOpenThread(null)}
                  >
                    <CloseIcon className="size-3.5" />
                  </button>
                </div>

                <div className="flex flex-col gap-2.5 px-2.5">
                  <div className="flex flex-col gap-3.5">
                    {/* a reply: the avatar, 8, name · when over the text */}
                    {current.replies.map((r, i) => (
                      <div key={i} className="flex items-start gap-2">
                        {r.image ? (
                          // eslint-disable-next-line @next/next/no-img-element
                          <img
                            src={r.image}
                            alt=""
                            className="size-6 shrink-0 rounded-full object-cover"
                          />
                        ) : (
                          <span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-secondary text-[10px] font-medium text-secondary-foreground">
                            {r.who.charAt(0)}
                          </span>
                        )}
                        <div className="flex min-w-0 flex-1 flex-col gap-1">
                          <p className="flex items-baseline gap-1">
                            <span className="truncate text-sm leading-4 font-medium text-secondary-foreground">
                              {r.who}
                            </span>
                            <span className="shrink-0 text-sm leading-[15px] text-accent-foreground">
                              · {r.when}
                            </span>
                          </p>
                          <p className="text-base text-muted-foreground">
                            {r.text}
                          </p>
                        </div>
                        <button
                          type="button"
                          className="flex size-4 shrink-0 items-center justify-center text-accent-foreground"
                          aria-label="More"
                          title="More"
                        >
                          <DotHorizontalIcon className="size-4" />
                        </button>
                      </div>
                    ))}
                    {!current.replies.length && (
                      <p className="text-base text-accent-foreground">
                        Start the thread.
                      </p>
                    )}
                  </div>

                  {/* the reply field: 24px avatar, 8, the subtle input */}
                  <form
                    className="flex items-center gap-2"
                    onSubmit={(e) => {
                      e.preventDefault()
                      send()
                    }}
                  >
                    {commenter?.image ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img
                        src={commenter.image}
                        alt=""
                        className="size-6 shrink-0 rounded-full object-cover"
                      />
                    ) : (
                      <span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-secondary text-[10px] font-medium text-secondary-foreground">
                        {(commenter?.who ?? "You").charAt(0)}
                      </span>
                    )}
                    <div className="relative min-w-0 flex-1">
                      <Input
                        size="sm"
                        variant="subtle"
                        className="w-full pr-7"
                        placeholder="Reply"
                        aria-label="Reply"
                        value={reply}
                        onChange={(e) => setReply(e.target.value)}
                      />
                      <button
                        type="submit"
                        className="absolute top-1/2 right-1.5 flex size-4 -translate-y-1/2 items-center justify-center text-secondary-foreground"
                        aria-label="Send"
                      >
                        <ArrowUpIcon className="size-4" />
                      </button>
                    </div>
                  </form>
                </div>
              </div>
            )}
          </div>
        )
      }}
    </EditorProvider>
  )
}

"use client"

// A block's grip, ported from the branch's RteBlockHandle, as Notion draws
// it: six dots in the margin beside the block under the pointer, "Drag to
// move" beneath, that carry the block to wherever it is dropped. The drag
// is drawn here — the browser's snapshot is replaced by a translucent copy
// that follows the pointer, a line marks the edge of the block the pointer
// is over, and the drop puts the block at that edge. Just inside a block's
// left edge, or near its right one, the line stands upright and the block
// lands beside it as a row of columns. A picture carried from one cell of
// a media row onto another cell's picture changes places with it. A
// selection that runs over several blocks is carried whole. A click
// selects the block.
import * as React from "react"
import { createPortal } from "react-dom"
import type { Editor as TiptapEditor } from "@tiptap/core"
import { Fragment, type Node as PMNode } from "@tiptap/pm/model"
import { NodeSelection, TextSelection } from "@tiptap/pm/state"

import { cn } from "@/lib/utils"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { DragIcon } from "@/components/ui/rich-text-editor-icons"
import { pressHandlers } from "./press"
import { blockSelectKey, chosenBlocks, eachChosen } from "./block-select"
import { BLOCKS_SETTLED, type View } from "./extensions"

/** how far left of the document the grip still answers the pointer */
const GUTTER = 72
const SIZE = 24
/** the grip is narrower than it is tall: the dots 4px from either side */
const WIDTH = 16
/** the gap between the grip and the block */
const GAP = 6
/** how far past a block's edge, into the gap around it, its grip still answers */
const REACH = 16
/** how far in from a cell's corner the grip sits on the picture */
const CELL_INSET = 6
const FIRST_LINE = "p, h1, h2, h3, h4, h5, h6, summary, pre"
const SKIP =
  ".ProseMirror-gapcursor, .ProseMirror-widget, .ProseMirror-separator, br"
const ROW = '[data-type="columns"]'
const TOGGLE = '[data-type="details"]'
const CALLOUT = '[data-type="callout"]'
const LIST_TYPES = new Set(["bulletList", "orderedList", "taskList"])
const ITEM_TYPES = new Set(["listItem", "taskItem"])
const MEDIA_ROW = '[data-type="columns"][data-media="true"]'
/** a picture, a video, an embed or the audio bar, as its node view draws it */
const MEDIA_BLOCK = ".rte-media, .rte-player"
/** a text column's grip: smaller, centred in the half-gutter between the
 * hairline and the text (styles.tsx: a 56px gutter, the line mid-way) */
const TEXT_GRIP_WIDTH = 12
const TEXT_GRIP_HEIGHT = 20
const HALF_GUTTER = 28
/** how far left of a text column's edge its blocks still answer the
 * pointer: across the grip, so the way from the text to it keeps it */
const TEXT_GRIP_ROOM = HALF_GUTTER - 4
/** a first column's grip stands this far before its text, and the
 * layout's own grip this far before that one */
/** a textless block up to this tall is short enough to centre a grip on */
const SHORT_BLOCK = 64
const FIRST_GRIP_GAP = 4
const ROW_GRIP_GAP = 2
const MAX_COLUMNS = 5
/**
 * Beside a block, as Notion drops one: a pointer this far into a block
 * from its left edge, or near its right edge, lands the block beside it
 * rather than above or below, under a vertical line.
 */
const SIDE_ZONE = 48
const SIDE_INSET = 6

const inCell = (el: Element) =>
  el.parentElement?.matches('[data-type="column"]') === true &&
  el.closest(MEDIA_ROW) !== null
/**
 * The copy carried under the pointer holds no live player: a cloned video
 * would be decoded again from its source (an upload's data, megabytes of
 * it), a cloned frame would load its page again, and the copy, moved every
 * frame, would drag them along. A video becomes a still of its frame as it
 * stands, a frame a quiet box its size.
 */
function lightenPlayers(source: HTMLElement, copy: HTMLElement) {
  const live = [...source.querySelectorAll<HTMLVideoElement | HTMLIFrameElement>("video, iframe")]
  const cloned = [...copy.querySelectorAll<HTMLVideoElement | HTMLIFrameElement>("video, iframe")]
  cloned.forEach((el, i) => {
    const from = live[i]
    const box = from?.getBoundingClientRect()
    const still = document.createElement("canvas")
    still.width = Math.max(1, Math.round(box?.width ?? 1))
    still.height = Math.max(1, Math.round(box?.height ?? 1))
    still.className = el.className
    still.style.cssText = el.style.cssText
    still.style.display = "block"
    still.style.width = `${box?.width ?? 0}px`
    still.style.height = `${box?.height ?? 0}px`
    still.style.background = "#000"
    if (from instanceof HTMLVideoElement && from.readyState >= 2) {
      try {
        still.getContext("2d")?.drawImage(from, 0, 0, still.width, still.height)
      } catch {
        // a frame that cannot be read stays a black still
      }
    }
    el.replaceWith(still)
  })
}

/** the block's markup for a drop outside, without an upload's data in it */
const lightHTML = (el: HTMLElement) =>
  el.outerHTML.replace(/(src|poster|href)="data:[^"]*"/g, '$1=""')

/** an empty paragraph: a line with nothing on it */
const isEmptyLine = (el: Element) =>
  el.matches("p") &&
  (el.textContent ?? "").trim() === "" &&
  !el.querySelector("img, video, iframe, audio, [data-type]")

/** a block (or list item) anywhere inside a column of a row of prose */
const inTextColumn = (el: Element) =>
  el.closest('[data-type="column"]') !== null && el.closest(MEDIA_ROW) === null
/**
 * A picture carried from one cell of a row onto another cell's picture
 * changes places with it; onto an empty slot, or anywhere else, it lands
 * as any block does.
 */
const swapsWith = (from: Element, to: Element) =>
  inCell(from) &&
  inCell(to) &&
  from.parentElement !== to.parentElement &&
  to.querySelector("img") !== null
const spans = (el: Element, y: number) => {
  const r = el.getBoundingClientRect()
  return y >= r.top && y < r.bottom
}

/** a toggle's title and body, as drawn */
function toggleParts(el: Element) {
  const body = el.querySelector(":scope > .rte-details-body")
  return {
    summary: body?.querySelector<HTMLElement>(":scope > summary") ?? null,
    content:
      body?.querySelector<HTMLElement>(':scope > [data-type="details-content"]') ??
      null,
  }
}

/** the block of an open toggle's body the pointer is at — none on its
 * title, which is the toggle's own */
function toggleChild(el: HTMLElement, y: number) {
  if (!el.classList.contains("is-open")) return null
  const { content } = toggleParts(el)
  if (!content) return null
  const c = content.getBoundingClientRect()
  if (y < c.top || y >= c.bottom) return null
  let nearest: HTMLElement | null = null
  let gap = Infinity
  for (const child of content.children) {
    if (!(child instanceof HTMLElement) || child.matches(SKIP)) continue
    const r = child.getBoundingClientRect()
    const d = y < r.top ? r.top - y : y >= r.bottom ? y - r.bottom : 0
    if (d < gap) {
      gap = d
      nearest = child
    }
  }
  return nearest
}

/**
 * A callout's blocks, as Notion has them: its first line is the callout's
 * own (its grip carries the callout), the blocks under it each have their
 * own grip, set in the callout's left padding below the emoji. The block
 * of a callout the pointer is at — none on its first line.
 */
function calloutChild(el: HTMLElement, y: number) {
  let nearest: HTMLElement | null = null
  let gap = Infinity
  for (const child of el.children) {
    if (!(child instanceof HTMLElement) || child.matches(SKIP)) continue
    const r = child.getBoundingClientRect()
    const d = y < r.top ? r.top - y : y >= r.bottom ? y - r.bottom : 0
    if (d < gap) {
      gap = d
      nearest = child
    }
  }
  return nearest && nearest !== calloutTitle(el) ? nearest : null
}
const calloutTitle = (el: Element) =>
  [...el.children].find(
    (c): c is HTMLElement => c instanceof HTMLElement && !c.matches(SKIP)
  ) ?? null

/** an empty line, alone in a toggle's body: a block set by it takes its
 * place */
const loneToggleLine = (el: Element) =>
  el.parentElement?.matches('[data-type="details-content"]') === true &&
  el.parentElement.childElementCount === 1 &&
  isEmptyLine(el)

/**
 * In a row each cell's own block has the grip, so one block moves on its
 * own; the row itself answers from the gaps between its cells
 */
function rowChild(row: HTMLElement, x: number, y: number, loose: boolean) {
  // a text row's cell reaches into the gutter on its left, over its
  // blocks' grip
  const room = row.matches(MEDIA_ROW) ? 0 : TEXT_GRIP_ROOM
  const cell = [...row.children].find(
    (c): c is HTMLElement =>
      c instanceof HTMLElement &&
      x >= c.getBoundingClientRect().left - room &&
      x < c.getBoundingClientRect().right
  )
  const blocks = cell
    ? [...cell.children].filter(
        (c): c is HTMLElement => c instanceof HTMLElement && !c.matches(SKIP)
      )
    : []
  const inner = blocks.find((c) => spans(c, y))
  if (inner) return inner
  // a drop in a short column's empty space below its blocks lands by its
  // last block, not on the whole row (hovering there still offers the
  // row's own grip, the one that carries the row)
  if (loose && blocks.length) {
    const last = blocks[blocks.length - 1]
    if (y >= last.getBoundingClientRect().bottom) return last
  }
  return null
}

/** the block under the pointer: a top-level block, or a list's item */
function blockAt(
  view: View,
  x: number,
  y: number,
  loose = false
): HTMLElement | null {
  const dom = view.dom as HTMLElement
  const d = dom.getBoundingClientRect()
  // a drop answers from anywhere across the page's width
  const span = loose ? window.innerWidth : GUTTER
  if (x < d.left - span || x > d.right + span || y < d.top || y > d.bottom)
    return null
  // the block the pointer is on, or the nearest one when it is in the gap
  // between blocks — a rule is a pixel tall
  let el: HTMLElement | null = null
  let nearest = Infinity
  for (const child of dom.children) {
    if (!(child instanceof HTMLElement) || child.matches(SKIP)) continue
    const r = child.getBoundingClientRect()
    const distance = y < r.top ? r.top - y : y >= r.bottom ? y - r.bottom : 0
    if (distance < nearest) {
      nearest = distance
      el = child
    }
  }
  if (!el || nearest > REACH) return null
  let block: HTMLElement = el
  // into a row's cells, an open toggle's body, a callout's blocks, and a
  // list's items, as deep as they go
  for (;;) {
    if (block.matches(ROW)) {
      const inner = rowChild(block, x, y, loose)
      if (!inner) break
      block = inner
      continue
    }
    if (block.matches(TOGGLE) || block.matches(CALLOUT)) {
      const inner = block.matches(TOGGLE)
        ? toggleChild(block, y)
        : calloutChild(block, y)
      if (!inner) break
      block = inner
      continue
    }
    if (!block.matches("ul, ol")) break
    const item: HTMLElement | undefined = [...block.children].find(
      (c): c is HTMLElement => c instanceof HTMLElement && spans(c, y)
    )
    if (!item) break
    block = item
    const nested: HTMLElement | undefined = [...item.children].find(
      (c): c is HTMLElement =>
        c instanceof HTMLElement && c.matches("ul, ol") && spans(c, y)
    )
    if (!nested) break
    block = nested
  }
  return block
}

/** the document position of the node an element draws, if it is one */
function posOf(view: View, el: HTMLElement): number | null {
  let p: number
  try {
    p = view.posAtDOM(el, 0)
  } catch {
    return null
  }
  const $p = view.state.doc.resolve(p)
  const candidates = [p, p - 1]
  for (let d = $p.depth; d > 0; d--) candidates.push($p.before(d))
  for (const c of candidates) {
    if (c < 0) continue
    try {
      if (view.nodeDOM(c) === el) return c
    } catch {
      // not a node boundary
    }
  }
  return null
}

/**
 * The cell a block leaves empty behind it: its only block, in a row of
 * prose. (A row of pictures keeps the cell and offers it an Add Image
 * slot, extensions.tsx.)
 */
/**
 * The cell the block at `from` is the whole of: its column holds nothing
 * else but empty lines (a picture or a video set into a column keeps the
 * line it was set on). Carrying the block carries the column: beside
 * another column of its row the columns change places; anywhere else the
 * cell goes, its empty lines with it.
 */
function emptiedCell(state: View["state"], from: number) {
  const $from = state.doc.resolve(from)
  const column = state.schema.nodes.column
  if ($from.parent.type !== column) return null
  if ($from.node($from.depth - 1).attrs.media) return null
  const index = $from.index()
  let alone = true
  $from.parent.forEach((child, _offset, i) => {
    if (i === index) return
    if (!(child.isTextblock && child.content.size === 0)) alone = false
  })
  return alone ? { pos: $from.before(), row: $from.before($from.depth - 1) } : null
}

type Tr = View["state"]["tr"]
/**
 * Take the block at `from` (in the document `tr` started from) out of
 * `tr`, after whatever `tr` has already placed: the block, or the cell it
 * leaves empty — and a row left with one cell is a row no more.
 */
function leaveBehind(
  tr: Tr,
  from: number,
  size: number,
  cell: { pos: number; row: number } | null
) {
  const columns = tr.doc.type.schema.nodes.columns
  if (!cell) {
    const at = tr.mapping.map(from)
    tr.delete(at, at + size)
    return
  }
  // past whatever was set down right before the row: a block dropped on
  // the row's own top edge is inserted at the row's position, and mapping
  // back to that spot would find the block, not the row, and leave the
  // block's original standing (a copy instead of a move)
  const rowAt = tr.mapping.map(cell.row, 1)
  const row = tr.doc.nodeAt(rowAt)
  const cellPos = tr.mapping.map(cell.pos)
  const gone = tr.doc.nodeAt(cellPos)
  if (!row || row.type !== columns || !gone) return
  if (row.childCount === 1) {
    // the layout's last block has left it: the layout goes
    tr.delete(rowAt, rowAt + row.nodeSize)
    return
  }
  // otherwise the emptied cell goes and the rest stay a layout, one
  // column of them stacked if one is all that is left
  tr.delete(cellPos, cellPos + gone.nodeSize)
  const after = tr.doc.nodeAt(rowAt)
  if (after?.type === columns)
    tr.setNodeMarkup(rowAt, undefined, {
      ...after.attrs,
      count: after.childCount,
      widths: null,
    })
}

/**
 * The block at `from` stood beside the block at `to`, on `side` — as a new
 * cell of the row `to` is in, or, `to` standing alone, as a row of two
 * made of them both. Where it came from closes up behind it.
 */
function dropBeside(
  state: View["state"],
  from: number,
  to: number,
  side: "left" | "right"
) {
  const { schema } = state
  const columns = schema.nodes.columns
  const column = schema.nodes.column
  const node = state.doc.nodeAt(from)
  const beside = state.doc.nodeAt(to)
  if (!columns || !column || !node || !beside) return null
  const tr = state.tr

  const fromCell = emptiedCell(state, from)

  // where it goes
  const $to = state.doc.resolve(to)

  // a column's only block beside another column of its own layout: the
  // columns change places in one step (inserting first would make a sixth
  // column of a full row, which the layout does not hold); their shares
  // go with them
  if (
    fromCell &&
    $to.parent.type === column &&
    fromCell.row === $to.before($to.depth - 1)
  ) {
    const rowPos = fromCell.row
    const row = state.doc.nodeAt(rowPos)
    if (!row) return null
    const cells: PMNode[] = []
    row.forEach((c) => cells.push(c))
    const offsets: number[] = []
    row.forEach((_c, offset) => offsets.push(rowPos + 1 + offset))
    const fromIdx = offsets.indexOf(fromCell.pos)
    const toIdx = offsets.indexOf($to.before())
    if (fromIdx < 0 || toIdx < 0) return null
    const order = cells.map((_c, i) => i)
    order.splice(fromIdx, 1)
    const at = order.indexOf(toIdx) + (side === "left" ? 0 : 1)
    order.splice(at, 0, fromIdx)
    if (order.every((v, i) => v === i)) return null
    const widths = row.attrs.widths as number[] | null
    // the moved column alone is taken out and set back in: the row is not
    // drawn again, so the other columns' players (a video, an embed) keep
    // playing where they are rather than loading again
    const moving = cells[fromIdx]
    tr.delete(offsets[fromIdx], offsets[fromIdx] + moving.nodeSize)
    const kept = tr.doc.nodeAt(rowPos)
    if (!kept) return null
    let landed = rowPos + 1
    for (let i = 0; i < at; i++) landed += kept.child(i).nodeSize
    tr.insert(landed, moving)
    tr.setNodeMarkup(rowPos, undefined, {
      ...row.attrs,
      widths: widths ? order.map((i) => widths[i]) : null,
    })
    // the carried block, in its column's new place, stays selected
    try {
      tr.setSelection(NodeSelection.create(tr.doc, landed + 1))
    } catch {
      // a block that cannot hold a node selection keeps the caret's
    }
    return tr
  }
  let landed: number
  if ($to.parent.type === column) {
    const cellPos = $to.before()
    const cell = $to.parent
    const at = side === "left" ? cellPos : cellPos + cell.nodeSize
    tr.insert(at, column.create(null, node))
    landed = at + 1
    const rowPos = $to.before($to.depth - 1)
    const row = tr.doc.nodeAt(rowPos)!
    tr.setNodeMarkup(rowPos, undefined, {
      ...row.attrs,
      count: row.childCount,
      widths: null,
    })
  } else {
    const cells =
      side === "left"
        ? [column.create(null, node), column.create(null, beside)]
        : [column.create(null, beside), column.create(null, node)]
    tr.replaceWith(to, to + beside.nodeSize, columns.create({ count: 2 }, cells))
    landed = side === "left" ? to + 2 : to + 2 + cells[0].nodeSize
  }
  const placed = tr.steps.length

  // the block leaves where it was
  leaveBehind(tr, from, node.nodeSize, fromCell)

  // the carried block, where it now stands, stays selected
  const moved = tr.mapping.slice(placed).map(landed)
  try {
    tr.setSelection(NodeSelection.create(tr.doc, moved))
  } catch {
    // a block that cannot hold a node selection keeps the caret's
  }
  return tr
}

/**
 * A run of blocks fitted for where it lands. A list's items keep their
 * kind: where no list stands they go in a list of their own, into another
 * kind of list they take its items' kind. All of their list, they take
 * the list along. `into` is the node the run is set in (none: a new cell).
 */
function fitRun(
  state: View["state"],
  from: number,
  to: number,
  into: PMNode | null
) {
  const $from = state.doc.resolve(from)
  const list = $from.parent
  let content = state.doc.slice(from, to).content
  let wrapped = false
  let leave = { from, to }
  if (LIST_TYPES.has(list.type.name)) {
    if (!into || !LIST_TYPES.has(into.type.name)) {
      content = Fragment.from(list.type.create(list.attrs, content))
      wrapped = true
    } else if (into.type !== list.type) {
      const item = into.type.contentMatch.defaultType
      if (item) {
        const items: PMNode[] = []
        content.forEach((n) => items.push(item.create(null, n.content)))
        content = Fragment.from(items)
      }
    }
    if (from === $from.start() && to === $from.end())
      leave = { from: $from.before(), to: $from.after() }
  }
  return { content, wrapped, leave }
}

/** the cell a run from `from` to `to` is the whole of, in a row of prose:
 * carried off, it takes its cell along */
function wholeCell(state: View["state"], from: number, to: number) {
  const $from = state.doc.resolve(from)
  if ($from.parent.type !== state.schema.nodes.column) return null
  if (from !== $from.start() || to !== $from.end()) return null
  if ($from.node($from.depth - 1).attrs.media) return null
  return { pos: $from.before(), row: $from.before($from.depth - 1) }
}

/**
 * The run of blocks from `from` to `to` set beside the block at `to`, on
 * `side`, as one new cell: of the row `at` is in, or, `at` standing alone,
 * of a row of two made of them both. Where the run came from closes up
 * behind it. The range the run now fills is returned with the step.
 */
function dropRunBeside(
  state: View["state"],
  from: number,
  to: number,
  at: number,
  side: "left" | "right"
) {
  const { schema } = state
  const columns = schema.nodes.columns
  const column = schema.nodes.column
  const beside = state.doc.nodeAt(at)
  if (!columns || !column || !beside) return null
  const fit = fitRun(state, from, to, null)
  const { content } = fit
  const tr = state.tr
  const $at = state.doc.resolve(at)
  let start: number
  if ($at.parent.type === column) {
    const cellPos = $at.before()
    const spot = side === "left" ? cellPos : cellPos + $at.parent.nodeSize
    tr.insert(spot, column.create(null, content))
    start = spot + 1
    const rowPos = $at.before($at.depth - 1)
    const row = tr.doc.nodeAt(rowPos)!
    tr.setNodeMarkup(rowPos, undefined, {
      ...row.attrs,
      count: row.childCount,
      widths: null,
    })
  } else {
    const ours = column.create(null, content)
    const theirs = column.create(null, beside)
    const cells = side === "left" ? [ours, theirs] : [theirs, ours]
    tr.replaceWith(at, at + beside.nodeSize, columns.create({ count: 2 }, cells))
    start = side === "left" ? at + 2 : at + 2 + theirs.nodeSize
  }
  const placed = tr.steps.length
  // the items themselves, inside the list made for them
  const inset = fit.wrapped ? 1 : 0
  const landed = { from: start + inset, to: start + content.size - inset }

  // the run leaves where it was
  const { leave } = fit
  leaveBehind(
    tr,
    leave.from,
    leave.to - leave.from,
    wholeCell(state, leave.from, leave.to)
  )
  const after = tr.mapping.slice(placed)
  return {
    tr,
    landed: { from: after.map(landed.from, 1), to: after.map(landed.to, -1) },
  }
}

export function BlockHandle({ editor }: { editor: TiptapEditor }) {
  const [target, setTarget] = React.useState<HTMLElement | null>(null)
  const [point, setPoint] = React.useState({ left: 0, top: 0 })
  const [onMedia, setOnMedia] = React.useState(false)
  const [inGutter, setInGutter] = React.useState(false)
  const layerRef = React.useRef<HTMLDivElement>(null)
  const targetRef = React.useRef<HTMLElement | null>(null)
  // not state: a re-render of the grip while it is the source of a drag
  // makes the browser end the drag, so a drag leaves the grip's DOM alone;
  // pressed and not yet dragging, a move that reached the grip's tracking
  // first would carry it off to another block and the drag never starts
  const drag = React.useRef<{
    dragging: boolean
    pressed: boolean
    source: {
      el: HTMLElement
      pos: number
      run?: { to: number; doms: HTMLElement[]; chosen: boolean }
    } | null
    grab: { dx: number; dy: number }
    ghost: HTMLElement | null
    line: HTMLElement | null
    landing: {
      el: HTMLElement
      pos: number
      before: boolean
      side: "left" | "right" | null
      /** into the toggle, first in its body */
      into?: boolean
    } | null
  }>({
    dragging: false,
    pressed: false,
    source: null,
    grab: { dx: 0, dy: 0 },
    ghost: null,
    line: null,
    landing: null,
  })
  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => setMounted(true), [])

  /**
   * The run of sibling blocks a selection covers, when it covers more than
   * one: their positions and the elements that draw them
   */
  const selectedRun = React.useCallback(() => {
    if (editor.isDestroyed) return null
    // blocks chosen with the box are a run too, one block or many
    const chosen = chosenBlocks(editor.state)
    if (chosen) {
      const doms: HTMLElement[] = []
      eachChosen(editor.state.doc, chosen, (_node, pos) => {
        const dom = editor.view.nodeDOM(pos)
        if (dom instanceof HTMLElement) doms.push(dom)
      })
      return doms.length
        ? { from: chosen.from, to: chosen.to, doms, chosen: true }
        : null
    }
    const sel = editor.state.selection
    if (sel.empty || sel instanceof NodeSelection) return null
    const range = sel.$from.blockRange(sel.$to)
    if (!range || range.endIndex - range.startIndex < 2) return null
    const doms: HTMLElement[] = []
    let pos = range.start
    for (let i = range.startIndex; i < range.endIndex; i++) {
      const dom = editor.view.nodeDOM(pos)
      if (dom instanceof HTMLElement) doms.push(dom)
      pos += range.parent.child(i).nodeSize
    }
    return { from: range.start, to: range.end, doms, chosen: false }
  }, [editor])
  const inRun = (run: { doms: HTMLElement[] }, el: Element) =>
    run.doms.some((d) => d === el || d.contains(el))

  /** text is selected: the formatting bar is up, and the grip steps aside —
   * unless the selection runs over whole blocks, which the grip carries */
  const selectingText = React.useCallback(() => {
    const sel = editor.state.selection
    return (
      !sel.empty && !(sel instanceof NodeSelection) && !selectedRun()
    )
  }, [editor, selectedRun])

  const place = React.useCallback(() => {
    const d = drag.current
    if (d.dragging || d.pressed) return
    if (selectingText()) {
      targetRef.current = null
      setTarget(null)
      return
    }
    const el = targetRef.current
    if (!el || !el.isConnected) {
      setTarget(null)
      return
    }
    const r = el.getBoundingClientRect()
    if (r.width === 0 && r.height === 0) {
      targetRef.current = null
      setTarget(null)
      return
    }
    const media = inCell(el)
    setOnMedia(media)
    setInGutter(false)
    // a cell's block has no margin of its own to stand the grip in: it
    // sits on the picture, in its top-left corner, as the media's chrome
    if (media) {
      setPoint({ top: r.top + CELL_INSET, left: r.left + CELL_INSET })
      return
    }
    // centred on the block's first line of text, not on the block's box —
    // a picture, a video or an embed has none of its own (the words of a
    // frame that failed to load are its chrome): its grip is at its top
    const mediaBlock =
      el.matches(MEDIA_BLOCK) || !!el.querySelector(`:scope > ${MEDIA_BLOCK}`)
    const first = el.matches(FIRST_LINE)
      ? el
      : mediaBlock
        ? el
        : (el.querySelector(FIRST_LINE) ?? el)
    const box = first.getBoundingClientRect()
    const fcs = getComputedStyle(first)
    // the first line starts inside the block's padding (a code block's)
    const inset =
      first === el && el.matches("pre")
        ? parseFloat(fcs.paddingTop) + parseFloat(fcs.borderTopWidth)
        : 0
    const fr = { top: box.top + inset, height: box.height - inset }
    const lineHeight = parseFloat(fcs.lineHeight) || SIZE
    const line = Math.min(lineHeight, fr.height)
    // a short block with no line of text (an Add Image slot, a divider)
    // has its grip centred on it, as a single line's is
    const textless = first === el && !el.matches(FIRST_LINE)
    const top =
      textless && r.height <= SHORT_BLOCK
        ? r.top + (r.height - SIZE) / 2
        : fr.top + (line - SIZE) / 2
    // an item's grip sits before its marker, at its list's edge
    const edge = el.matches("li")
      ? (el.parentElement?.getBoundingClientRect().left ?? r.left)
      : r.left
    // a block in a text row's column carries its grip in the gutter just
    // before its text, on its first line, clear of the words
    if (inTextColumn(el)) {
      setInGutter(true)
      // the first column has the page's margin, not a gutter, before it:
      // its grip keeps close to the words, leaving the layout's grip room
      // to stand near the other blocks' grips
      const first = !el.closest('[data-type="column"]')?.previousElementSibling
      setPoint({
        top: top + (SIZE - TEXT_GRIP_HEIGHT) / 2,
        left: first
          ? edge - FIRST_GRIP_GAP - TEXT_GRIP_WIDTH
          : edge - (HALF_GUTTER + TEXT_GRIP_WIDTH) / 2,
      })
      return
    }
    // a text row's own grip stands out past its first column's block
    // grips (in the margin, where they reach): the two never share a spot
    if (el.matches(ROW) && !el.matches(MEDIA_ROW)) {
      setPoint({
        top,
        left: edge - FIRST_GRIP_GAP - TEXT_GRIP_WIDTH - ROW_GRIP_GAP - WIDTH,
      })
      return
    }
    // narrowed, it keeps its dots where the square grip had them
    setPoint({ top, left: edge - GAP - (SIZE + WIDTH) / 2 })
  }, [selectingText])

  React.useEffect(() => {
    const onMove = (event: MouseEvent) => {
      const d = drag.current
      // a held button keeps the grip where it is: the press may be on its
      // way to a drag, and Safari can skip the pointerdown that would
      // have marked it pressed (after a drop), so the pointer leaving the
      // grip as the drag sets out would otherwise hand it another block
      if (d.dragging || d.pressed || event.buttons !== 0) return
      if (editor.isDestroyed || !editor.isEditable || selectingText()) {
        targetRef.current = null
        setTarget(null)
        return
      }
      const t = event.target instanceof Element ? event.target : null
      if (t && layerRef.current?.contains(t)) return
      const el = blockAt(editor.view, event.clientX, event.clientY)
      if (!el) {
        targetRef.current = null
        setTarget(null)
        return
      }
      targetRef.current = el
      setTarget(el)
      place()
    }
    const onFrame = (event: MouseEvent) => {
      if (event.target instanceof HTMLIFrameElement) onMove(event)
    }
    const settle = () => place()
    const hide = () => {
      if (drag.current.dragging || drag.current.pressed) return
      targetRef.current = null
      setTarget(null)
    }
    editor.on("transaction", settle)
    const root = editor.view.dom
    root.addEventListener(BLOCKS_SETTLED, settle)
    document.addEventListener("mousemove", onMove, true)
    // the pointer gone onto an embedded page (a video, an embed) sends no
    // move here: its frame's mouseover still says which block it is on
    document.addEventListener("mouseover", onFrame, true)
    document.addEventListener("scroll", settle, true)
    document.addEventListener("mouseleave", hide)
    window.addEventListener("resize", settle)
    return () => {
      editor.off("transaction", settle)
      root.removeEventListener(BLOCKS_SETTLED, settle)
      document.removeEventListener("mousemove", onMove, true)
      document.removeEventListener("mouseover", onFrame, true)
      document.removeEventListener("scroll", settle, true)
      document.removeEventListener("mouseleave", hide)
      window.removeEventListener("resize", settle)
    }
  }, [editor, place, selectingText])

  const selectBlock = React.useCallback((): NodeSelection | null => {
    const el = targetRef.current
    if (editor.isDestroyed || !el) return null
    const pos = posOf(editor.view, el)
    if (pos === null) return null
    const sel = NodeSelection.create(editor.view.state.doc, pos)
    editor.view.dispatch(editor.view.state.tr.setSelection(sel))
    return sel
  }, [editor])

  /** whether a block can take another beside it */
  const sideable = React.useCallback(
    (el: HTMLElement) => {
      if (el.matches(ROW) || el.matches("li")) return false
      const cell = el.parentElement
      if (cell?.matches('[data-type="column"]'))
        return (
          (cell.parentElement?.childElementCount ?? MAX_COLUMNS) < MAX_COLUMNS
        )
      return el.parentElement === editor.view.dom
    },
    [editor]
  )

  /**
   * A column's only block set beside another column of the same layout:
   * the columns change places, their number stays, so even a full row
   * (five) takes it
   */
  const reorders = (source: HTMLElement, el: HTMLElement) => {
    const from = source.parentElement
    const to = el.parentElement
    if (!from?.matches('[data-type="column"]') || !to?.matches('[data-type="column"]'))
      return false
    if (from === to || from.parentElement !== to.parentElement) return false
    if (from.parentElement?.matches(MEDIA_ROW)) return false
    // the column's only block, its empty lines aside (see emptiedCell)
    const blocks = [...from.children].filter(
      (c) => c instanceof HTMLElement && !c.matches(SKIP) && !isEmptyLine(c)
    )
    return blocks.length === 1 && blocks[0] === source
  }

  /** the edge the pointer is over */
  const landingAt = React.useCallback(
    (x: number, y: number) => {
      const d = drag.current
      if (editor.isDestroyed || !d.source) return null
      const el = blockAt(editor.view, x, y, true)
      if (!el || el === d.source.el || d.source.el.contains(el)) return null
      // a block carried within its own layout and set on the layout's top
      // or bottom edge stays in the layout, first or last in it: leaving
      // the layout is a drop on a block outside it
      if (el.matches(ROW) && !el.matches(MEDIA_ROW) && el.contains(d.source.el)) {
        const r = el.getBoundingClientRect()
        const top = y < r.top + r.height / 2
        const cells = [...el.children].filter(
          (c): c is HTMLElement => c instanceof HTMLElement
        )
        const cell = top ? cells[0] : cells[cells.length - 1]
        const blocks = cell
          ? [...cell.children].filter(
              (c): c is HTMLElement =>
                c instanceof HTMLElement && !c.matches(SKIP)
            )
          : []
        const inner = top ? blocks[0] : blocks[blocks.length - 1]
        if (!inner || inner === d.source.el) return null
        const innerPos = posOf(editor.view, inner)
        if (innerPos === null) return null
        return {
          el: inner,
          pos: innerPos,
          before: top,
          side: null,
          box: inner.getBoundingClientRect(),
        }
      }
      // a run lands outside itself
      if (d.source.run && inRun(d.source.run, el)) return null
      const pos = posOf(editor.view, el)
      if (pos === null) return null
      const box = el.getBoundingClientRect()
      // the lower half of a toggle's title: into the toggle, first in its
      // body, its line set in under the title as Notion indents it
      if (el.matches(TOGGLE)) {
        const { summary } = toggleParts(el)
        const s = summary?.getBoundingClientRect()
        if (s && y >= s.top + s.height / 2 && y < s.bottom)
          return {
            el,
            pos,
            before: false,
            side: null,
            into: true,
            box: new DOMRect(s.left, s.top, s.width, s.height),
          }
      }
      // the lower half of a callout's first line: into the callout, first
      // of the blocks under it
      if (el.matches(CALLOUT)) {
        const s = calloutTitle(el)?.getBoundingClientRect()
        if (s && y >= s.top + s.height / 2 && y < s.bottom)
          return {
            el,
            pos,
            before: false,
            side: null,
            into: true,
            box: new DOMRect(s.left, s.top, s.width, s.height),
          }
      }
      const zone = Math.min(SIDE_ZONE, box.width / 4)
      let side: "left" | "right" | null = null
      const run = d.source.run
      // a run stands beside a block as a new cell — never one holding a row
      // itself, for a row is no column's block
      const runSideable =
        !!run &&
        sideable(el) &&
        !el.closest(MEDIA_ROW) &&
        !run.doms.some((x) => x.matches(ROW) || x.querySelector(ROW))
      if (
        run
          ? runSideable
          : (sideable(el) || reorders(d.source.el, el)) &&
            !swapsWith(d.source.el, el)
      ) {
        if (x >= box.left + SIDE_INSET && x < box.left + SIDE_INSET + zone)
          side = "left"
        else if (x > box.right - zone) side = "right"
      }
      return { el, pos, before: y < box.top + box.height / 2, side, box }
    },
    [editor, sideable]
  )

  /**
   * The run's blocks dimmed while carried, as a carried block is. The
   * class is set past ProseMirror's watch on its DOM, which would
   * otherwise read it as an edit.
   */
  const carried = React.useCallback(
    (doms: HTMLElement[], on: boolean) => {
      const observer = (
        editor.view as unknown as {
          domObserver?: { stop(): void; start(): void }
        }
      ).domObserver
      observer?.stop()
      doms.forEach((d) => d.classList.toggle("rte-bh-carried", on))
      observer?.start()
    },
    [editor]
  )

  /**
   * Where a landing sets the carried block: before or after its block, or
   * first in a toggle's body. A toggle's lone empty line gives its place
   * up, and a closed toggle taken into opens to show what came in.
   */
  const landingEdge = (
    state: View["state"],
    at: { el: Element; pos: number; before: boolean; into?: boolean }
  ) => {
    const node = state.doc.nodeAt(at.pos)
    if (!node) return null
    if (at.into && node.type.name === "callout")
      return {
        edge: at.pos + 1 + node.firstChild!.nodeSize,
        lone: null,
        open: null,
      }
    if (at.into && node.childCount === 2) {
      const body = node.lastChild!
      const edge = at.pos + 1 + node.firstChild!.nodeSize + 1
      const first = body.firstChild
      const lone =
        body.childCount === 1 && first?.isTextblock && first.content.size === 0
          ? edge
          : null
      return { edge, lone, open: node.attrs.open === false ? at.pos : null }
    }
    return {
      edge: at.before ? at.pos : at.pos + node.nodeSize,
      lone: loneToggleLine(at.el) ? at.pos : null,
      open: null,
    }
  }
  /** a toggle opened, and its lone empty line given up, in `tr` */
  const settleToggle = (
    tr: View["state"]["tr"],
    spot: { lone: number | null; open: number | null },
    phase: "before" | "after"
  ) => {
    if (phase === "before") {
      if (spot.open === null) return
      const t = tr.doc.nodeAt(spot.open)
      if (t) tr.setNodeMarkup(spot.open, undefined, { ...t.attrs, open: true })
      return
    }
    if (spot.lone === null) return
    const p = tr.mapping.map(spot.lone, 1)
    const line = tr.doc.nodeAt(p)
    if (line?.isTextblock && line.content.size === 0) tr.delete(p, p + line.nodeSize)
  }

  /** a run set down at `edge`, taken from where it was, still selected —
   * and blocks chosen with the box still chosen, where they land on the
   * page itself */
  const dropRun = React.useCallback(
    (
      from: number,
      to: number,
      edge: number,
      chosen: boolean,
      spot: { lone: number | null; open: number | null }
    ) => {
      const { state } = editor.view
      const fit = fitRun(state, from, to, state.doc.resolve(edge).parent)
      const { leave } = fit
      if (edge >= leave.from && edge <= leave.to) return
      const tr = state.tr
      settleToggle(tr, spot, "before")
      tr.insert(edge, fit.content)
      const placed = tr.steps.length
      const start = tr.mapping.map(edge, -1)
      const end = tr.mapping.map(edge, 1)
      leaveBehind(
        tr,
        leave.from,
        leave.to - leave.from,
        wholeCell(state, leave.from, leave.to)
      )
      settleToggle(tr, spot, "after")
      const after = tr.mapping.slice(placed)
      // the items themselves, inside the list made for them
      const inset = fit.wrapped ? 1 : 0
      const landed = {
        from: after.map(start, 1) + inset,
        to: after.map(end, -1) - inset,
      }
      if (chosen) {
        tr.setSelection(TextSelection.near(tr.doc.resolve(landed.from)))
        tr.setMeta(blockSelectKey, landed)
      } else
        tr.setSelection(
          TextSelection.between(
            tr.doc.resolve(landed.from),
            tr.doc.resolve(landed.to)
          )
        )
      editor.view.dispatch(tr.scrollIntoView())
      editor.view.focus()
    },
    [editor]
  )

  const finishDrag = React.useCallback(() => {
    const d = drag.current
    gripRef.current?.classList.remove("is-dragging")
    d.pressed = false
    if (d.source?.run) carried(d.source.run.doms, false)
    d.dragging = false
    d.source = null
    d.landing = null
    d.ghost?.remove()
    d.ghost = null
    d.line?.remove()
    d.line = null
    document.removeEventListener("dragover", onDragOverRef.current, true)
    document.removeEventListener("dragenter", onDragOverRef.current, true)
    document.removeEventListener("drop", onDropRef.current, true)
    document.body.classList.remove("rte-block-drag")
    if (!editor.isDestroyed) {
      editor.view.dom.classList.remove("rte-dragging")
      editor.view.dragging = null
    }
  }, [editor, carried])

  const gripRef = React.useRef<HTMLButtonElement | null>(null)
  const onDragOverRef = React.useRef<(e: DragEvent) => void>(() => {})
  const onDropRef = React.useRef<(e: DragEvent) => void>(() => {})

  onDragOverRef.current = (event: DragEvent) => {
    const d = drag.current
    if (!d.dragging) return
    // the drag is the grip's, wherever the pointer is: ProseMirror's own
    // drop cursor (a 1px rule) would otherwise draw where the grip has no
    // landing, and stay there, over the carried block
    event.stopPropagation()
    if (d.ghost)
      d.ghost.style.transform = `translate(${event.clientX - d.grab.dx}px, ${
        event.clientY - d.grab.dy
      }px)`
    const at = landingAt(event.clientX, event.clientY)
    if (!at) {
      d.landing = null
      if (d.line) d.line.hidden = true
      return
    }
    // the drop is ours, wherever the pointer is
    event.preventDefault()
    event.stopPropagation()
    if (event.dataTransfer) event.dataTransfer.dropEffect = "move"
    d.landing = {
      el: at.el,
      pos: at.pos,
      before: at.before,
      side: at.side,
      into: "into" in at ? at.into : false,
    }
    const line = d.line
    if (!line) return
    if (at.side) {
      // beside: a vertical line down the edge it would stand at
      line.hidden = false
      line.classList.remove("is-swap")
      line.classList.add("is-side")
      line.style.top = `${at.box.top}px`
      line.style.height = `${at.box.height}px`
      line.style.width = ""
      line.style.left = `${
        at.side === "left" ? at.box.left - 6 : at.box.right + 3
      }px`
    } else {
      line.classList.remove("is-side")
      line.hidden = false
      // a swap rings the picture it would change places with, not its line
      const swap = d.source !== null && swapsWith(d.source.el, at.el)
      const ring = swap
        ? (at.el.querySelector("img")?.getBoundingClientRect() ?? at.box)
        : at.box
      line.classList.toggle("is-swap", swap)
      line.style.left = `${ring.left}px`
      line.style.width = `${ring.width}px`
      line.style.height = swap ? `${ring.height}px` : ""
      line.style.top = swap
        ? `${ring.top}px`
        : `${at.before ? at.box.top - 3 : at.box.bottom}px`
    }
  }

  onDropRef.current = (event: DragEvent) => {
    const d = drag.current
    if (!d.dragging) return
    event.preventDefault()
    event.stopPropagation()
    const at = landingAt(event.clientX, event.clientY) ?? d.landing
    const from = d.source
    // a drop is the drag's end: Safari can drop and never send the
    // source its dragend, which would leave the grip hidden and stale
    finishDrag()
    targetRef.current = null
    setTarget(null)
    if (editor.isDestroyed || !at || !from) return
    const { state } = editor.view
    const node = state.doc.nodeAt(from.pos)
    const beside = state.doc.nodeAt(at.pos)
    if (!node || !beside) return
    if (from.run && at.side) {
      const out = dropRunBeside(state, from.pos, from.run.to, at.pos, at.side)
      if (!out) return
      const { tr, landed } = out
      if (from.run.chosen) {
        tr.setSelection(TextSelection.near(tr.doc.resolve(landed.from)))
        tr.setMeta(blockSelectKey, landed)
      } else
        tr.setSelection(
          TextSelection.between(
            tr.doc.resolve(landed.from),
            tr.doc.resolve(landed.to)
          )
        )
      editor.view.dispatch(tr.scrollIntoView())
      editor.view.focus()
      return
    }
    if (from.run) {
      const spot = landingEdge(state, at)
      if (spot) dropRun(from.pos, from.run.to, spot.edge, from.run.chosen, spot)
      return
    }
    if (at.side) {
      const tr = dropBeside(state, from.pos, at.pos, at.side)
      if (tr) {
        editor.view.dispatch(tr.scrollIntoView())
        editor.view.focus()
      }
      return
    }
    if (swapsWith(from.el, at.el)) {
      // the later one first, so the earlier position still holds
      const [first, second] =
        from.pos < at.pos
          ? [
              { pos: from.pos, node },
              { pos: at.pos, node: beside },
            ]
          : [
              { pos: at.pos, node: beside },
              { pos: from.pos, node },
            ]
      const tr = state.tr
        .replaceWith(second.pos, second.pos + second.node.nodeSize, first.node)
        .replaceWith(first.pos, first.pos + first.node.nodeSize, second.node)
      // the carried picture, where it now stands, stays selected
      const shift = second.node.nodeSize - first.node.nodeSize
      const landed = from.pos < at.pos ? at.pos + shift : at.pos
      tr.setSelection(NodeSelection.create(tr.doc, landed))
      editor.view.dispatch(tr.scrollIntoView())
      editor.view.focus()
      return
    }
    const spot = landingEdge(state, at)
    if (!spot) return
    const { edge } = spot
    // the block is already there
    if (edge === from.pos || edge === from.pos + node.nodeSize) return
    // a list's item keeps its kind: set down away from a list it goes in a
    // list of its own, and into another kind of list it takes that kind's
    // item; the only item of its list takes the list along
    let moving = node
    let source = { pos: from.pos, size: node.nodeSize }
    const $src = state.doc.resolve(from.pos)
    if (ITEM_TYPES.has(node.type.name)) {
      const list = $src.parent
      const $edge = state.doc.resolve(edge)
      if (!LIST_TYPES.has($edge.parent.type.name))
        moving = list.type.create(list.attrs, node)
      else if ($edge.parent.type !== list.type) {
        const item = $edge.parent.type.contentMatch.defaultType
        if (item) moving = item.create(null, node.content)
      }
      if (list.childCount === 1)
        source = { pos: $src.before(), size: list.nodeSize }
    }
    // placed first, then taken from where it was: the insert only ever
    // adds, so the source's position still maps
    const tr = state.tr
    const cell = emptiedCell(state, source.pos)
    settleToggle(tr, spot, "before")
    tr.insert(edge, moving)
    const placed = tr.steps.length
    leaveBehind(tr, source.pos, source.size, cell)
    settleToggle(tr, spot, "after")
    const to = tr.mapping.slice(placed).map(edge, at.before ? -1 : 1)
    // the block, wherever the fit put it, stays selected
    let moved: number | null = null
    tr.doc.nodesBetween(
      Math.max(0, to - 2),
      Math.min(tr.doc.content.size, to + node.nodeSize + 2),
      (n, pos) => {
        if (moved === null && n.type === moving.type && n.eq(moving)) moved = pos
        return moved === null
      }
    )
    if (moved !== null) tr.setSelection(NodeSelection.create(tr.doc, moved))
    editor.view.dispatch(tr.scrollIntoView())
    editor.view.focus()
  }

  // the browser's own snapshot is replaced by nothing: the copy is drawn
  // here. Safari cancels a drag outright (dragstart, then dragend at once)
  // when dragstart hands it an image still loading, so the blank loads
  // with the grip, and an unready one is never handed over
  const blankRef = React.useRef<HTMLImageElement | null>(null)
  React.useEffect(() => {
    const img = new window.Image()
    img.src =
      "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7"
    blankRef.current = img
  }, [])
  const hideSnapshot = (dt: DataTransfer) => {
    const img = blankRef.current
    if (img?.complete && img.naturalWidth > 0) dt.setDragImage(img, 0, 0)
  }

  const buildGhost = (doms: HTMLElement[], width: number) => {
    const ghost = document.createElement("div")
    ghost.className = "rte-bh-ghost"
    ghost.style.width = `${width}px`
    const docWrap = document.createElement("div")
    docWrap.className = editor.view.dom.parentElement?.className ?? ""
    const inner = document.createElement("div")
    inner.className = editor.view.dom.className
      .replace(/\bProseMirror-\S+/g, "")
      .replace("rte-dragging", "")
    for (const d of doms) {
      const copy = d.cloneNode(true) as HTMLElement
      copy.classList.remove("ProseMirror-selectednode", "rte-bh-carried")
      lightenPlayers(d, copy)
      inner.appendChild(copy)
    }
    docWrap.appendChild(inner)
    ghost.appendChild(docWrap)
    document.body.appendChild(ghost)
    return ghost
  }
  const startDragChrome = (
    event: React.DragEvent<HTMLButtonElement>,
    doms: HTMLElement[],
    width: number
  ) => {
    const d = drag.current
    d.dragging = true
    event.currentTarget.classList.add("is-dragging")
    editor.view.dom.classList.add("rte-dragging")
    document.body.classList.add("rte-block-drag")
    d.ghost = buildGhost(doms, width)
    d.ghost.style.transform = `translate(${event.clientX - d.grab.dx}px, ${
      event.clientY - d.grab.dy
    }px)`
    const line = document.createElement("div")
    line.className = "rte-bh-line"
    line.hidden = true
    document.body.appendChild(line)
    d.line = line
    document.addEventListener("dragover", onDragOverRef.current, true)
    document.addEventListener("dragenter", onDragOverRef.current, true)
    document.addEventListener("drop", onDropRef.current, true)
  }

  const onDragStart = (event: React.DragEvent<HTMLButtonElement>) => {
    const el = targetRef.current
    const run = selectedRun()
    const d = drag.current
    if (el && run && inRun(run, el) && event.dataTransfer) {
      // the drag of a run of blocks: the same copy and line, all of them
      const first = run.doms[0]
      const last = run.doms[run.doms.length - 1]
      const r0 = first.getBoundingClientRect()
      const r1 = last.getBoundingClientRect()
      d.source = {
        el: first,
        pos: run.from,
        run: { to: run.to, doms: run.doms, chosen: run.chosen },
      }
      d.grab = { dx: event.clientX - r0.left, dy: event.clientY - r0.top }
      const slice = editor.state.doc.slice(run.from, run.to)
      editor.view.dragging = { slice, move: true }
      const dt = event.dataTransfer
      dt.effectAllowed = "move"
      dt.clearData()
      dt.setData("text/html", run.doms.map((x) => lightHTML(x)).join(""))
      dt.setData("text/plain", run.doms.map((x) => x.textContent).join("\n"))
      hideSnapshot(dt)
      carried(run.doms, true)
      startDragChrome(event, run.doms, Math.max(r0.width, r1.width))
      return
    }
    if (!el || !event.dataTransfer) {
      event.preventDefault()
      return
    }
    // dragging is marked before the selection is dispatched: the
    // transaction would otherwise re-render the grip mid-dragstart
    d.dragging = true
    const sel = selectBlock()
    if (!sel) {
      d.dragging = false
      event.preventDefault()
      return
    }
    const r = el.getBoundingClientRect()
    d.source = { el, pos: sel.from }
    d.grab = { dx: event.clientX - r.left, dy: event.clientY - r.top }
    // what ProseMirror would read, should a drop ever reach it
    editor.view.dragging = { slice: sel.content(), move: true }
    event.dataTransfer.effectAllowed = "move"
    event.dataTransfer.clearData()
    event.dataTransfer.setData("text/html", lightHTML(el))
    event.dataTransfer.setData("text/plain", el.textContent ?? "")
    hideSnapshot(event.dataTransfer)
    startDragChrome(event, [el], r.width)
  }
  const onDragEnd = (event: React.DragEvent<HTMLButtonElement>) => {
    event.currentTarget.classList.remove("is-dragging")
    finishDrag()
    targetRef.current = null
    setTarget(null)
  }

  // pressed and not yet dragging: the grip holds still so the drag's
  // source stays under the press
  const release = React.useCallback(() => {
    drag.current.pressed = false
    window.removeEventListener("pointerup", release, true)
    window.removeEventListener("pointercancel", release, true)
  }, [])
  const onPress = () => {
    drag.current.pressed = true
    window.addEventListener("pointerup", release, true)
    window.addEventListener("pointercancel", release, true)
  }

  const onClick = () => {
    // on a run of selected blocks a click keeps the run
    const run = selectedRun()
    if (run && targetRef.current && inRun(run, targetRef.current)) {
      editor.view.focus()
      return
    }
    if (selectBlock()) editor.view.focus()
  }

  if (!mounted) return null
  return createPortal(
    <div
      ref={layerRef}
      className="pointer-events-none fixed inset-0 z-30"
      data-slot="rich-text-editor-block-handle"
    >
      {/* the grip stays mounted through a drag, hidden: the browser ends a
          drag whose source leaves the document */}
      {target && (
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger
              render={
                <button
                  ref={gripRef}
                  type="button"
                  draggable
                  aria-label="Drag to move"
                  {...pressHandlers(onPress)}
                  onDragStart={onDragStart}
                  onDragEnd={onDragEnd}
                  onClick={onClick}
                  style={{ left: point.left, top: point.top }}
                  className={cn(
                    "rte-bh-handle",
                    onMedia && "is-on-media",
                    inGutter && "is-in-gutter"
                  )}
                >
                  <DragIcon className="size-4" />
                </button>
              }
            />
            <TooltipContent side="bottom">Drag to move</TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )}
    </div>,
    document.body
  )
}

"use client"

// Figma: espresso-2.0 › table (32157:9144). The table's controls, ported
// from the branch's RteTableControls and drawn over the document on a
// fixed layer so nothing is clipped by the table's scrolling card:
//
// - handles on the row and column of the cell under the pointer, or of the
//   caret's cell: a dash on the table's own rule (drawn by .rte-tc-edge at
//   the rule's device pixels), growing into the file's grip — a 10×20 (or
//   20×10) gray-500 pill with white dots — under the pointer, which opens
//   its menu; a selected cell or run adds a handle at its right edge;
// - a grip pressed selects its row or column; released in place it opens
//   the menu, and carried 4px it drags the row or column instead — a 3px
//   line marks the edge it will land on, the cells settle into their new
//   order over 220ms, and the first rows stay header rows;
// - two 16px strips, 8px off the table's right and bottom edges, that add
//   a column or a row at the end;
// - a fresh table shares the card's width between its columns; once a
//   column is added or resized every column holds the width it has, so
//   the new or wider one grows the table past the card instead of
//   squeezing the others.
import * as React from "react"
import { createPortal } from "react-dom"
import type { Editor as TiptapEditor } from "@tiptap/core"
import { Fragment, type Node as PMNode, type ResolvedPos } from "@tiptap/pm/model"
import { TextSelection } from "@tiptap/pm/state"
import {
  CellSelection,
  TableMap,
  cellAround,
  columnResizingPluginKey,
  isInTable,
} from "@tiptap/pm/tables"

import { cn } from "@/lib/utils"

import { pressHandlers, pressPointerId, type PressEvent } from "./press"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Add12Icon,
  ArrowDownIcon,
  ArrowLeftIcon,
  ArrowRightIcon,
  ArrowUpIcon,
  CellColorIcon,
  CellMergeIcon,
  DeleteIcon,
  DuplicateIcon,
  HeaderRowIcon,
  SmallCloseIcon,
} from "@/components/ui/rich-text-editor-icons"
import { hue, PALETTE, SMOOTH_SKIP, TABLE_SETTLE } from "./extensions"

type Box = { left: number; top: number; width: number; height: number }
const box = (r: DOMRect): Box => ({
  left: r.left,
  top: r.top,
  width: r.width,
  height: r.height,
})
const px = (n: number) => `${n}px`

type Ctx = {
  ed: TiptapEditor
  table: PMNode
  start: number
  map: TableMap
}

function ctxAt(ed: TiptapEditor, $pos: ResolvedPos): Ctx | null {
  for (let d = $pos.depth; d >= 0; d--) {
    if ($pos.node(d).type.name === "table") {
      const table = $pos.node(d)
      return { ed, table, start: $pos.start(d), map: TableMap.get(table) }
    }
  }
  return null
}

// The editor's own cell selections may come from the table extension's
// bundled copy of prosemirror-tables, a different class from the one
// imported here, so they are told by shape.
function asCellSelection(selection: unknown): CellSelection | null {
  return selection && typeof selection === "object" && "$anchorCell" in selection
    ? (selection as CellSelection)
    : null
}

const DRAG_START = 4
const SCROLL_EDGE = 40
const SETTLE = { duration: 220, easing: "cubic-bezier(0.2, 0, 0, 1)" }

type SelKind = "caret" | "cells" | "row" | "col" | null
type DragKind = "row" | "col"
type PressKind = DragKind | "cell"

interface Geo {
  tableBox: Box | null
  rowBox: Box | null
  colBox: Box | null
  cellBox: Box | null
  cellKnobOn: boolean
  ringTop: boolean
  ringLeft: boolean
  rowIndex: number
  colIndex: number
  cellCount: number
  cellMerged: boolean
  selKind: SelKind
  isHeaderRow: boolean
}

const EMPTY: Geo = {
  tableBox: null,
  rowBox: null,
  colBox: null,
  cellBox: null,
  cellKnobOn: false,
  ringTop: false,
  ringLeft: false,
  rowIndex: -1,
  colIndex: -1,
  cellCount: 0,
  cellMerged: false,
  selKind: null,
  isHeaderRow: false,
}

export function TableControls({ editor }: { editor: TiptapEditor }) {
  const [geo, setGeo] = React.useState<Geo>(EMPTY)
  const [rowOpen, setRowOpen] = React.useState(false)
  const [colOpen, setColOpen] = React.useState(false)
  const [cellOpen, setCellOpen] = React.useState(false)
  const [dragKind, setDragKind] = React.useState<DragKind | null>(null)
  const [dropLine, setDropLine] = React.useState<Box | null>(null)
  const [dropOn, setDropOn] = React.useState(false)
  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => setMounted(true), [])

  const layerRef = React.useRef<HTMLDivElement>(null)
  const geoRef = React.useRef<Geo>(EMPTY)
  geoRef.current = geo
  const menuOpenRef = React.useRef(false)
  menuOpenRef.current = rowOpen || colOpen || cellOpen

  // what the controls follow, held as document positions
  const self = React.useRef({
    anchorPos: null as number | null,
    hoverPos: null as number | null,
    hovering: false,
    resizeHeld: false,
    wrapper: null as HTMLElement | null,
    press: null as null | {
      kind: PressKind
      index: number
      x: number
      y: number
      lastX: number
      lastY: number
      el: HTMLElement
      pointerId: number
      wasOpen: boolean
      active: boolean
      to: number | null
    },
    ghost: null as HTMLElement | null,
    ghostAt: { left: 0, top: 0, size: 0 },
    grab: 0,
    scrollRaf: 0,
    dropLine: null as Box | null,
  })

  const openFor = React.useMemo(
    () => ({
      row: setRowOpen,
      col: setColOpen,
      cell: setCellOpen,
    }),
    []
  )
  const rowAnchorRef = React.useRef<HTMLElement | null>(null)
  const colAnchorRef = React.useRef<HTMLElement | null>(null)
  const cellAnchorRef = React.useRef<HTMLElement | null>(null)
  const anchorRefs = React.useMemo(
    () => ({ row: rowAnchorRef, col: colAnchorRef, cell: cellAnchorRef }),
    []
  )
  const isOpenRef = React.useRef({ row: false, col: false, cell: false })
  isOpenRef.current = { row: rowOpen, col: colOpen, cell: cellOpen }

  /* ---- geometry from the document */
  const ctxOf = React.useCallback(
    (ed: TiptapEditor): Ctx | null => {
      const el = self.current.wrapper?.querySelector("table")
      if (!el || !el.isConnected) return null
      try {
        return ctxAt(ed, ed.state.doc.resolve(ed.view.posAtDOM(el, 0)))
      } catch {
        return null
      }
    },
    []
  )
  const cellPos = (c: Ctx, row: number, col: number) =>
    c.start + c.map.map[row * c.map.width + col]
  const cellsIn = (c: Ctx, axis: "row" | "col", index: number): number[] => {
    const out: number[] = []
    const n = axis === "row" ? c.map.width : c.map.height
    for (let i = 0; i < n; i++) {
      const pos = axis === "row" ? cellPos(c, index, i) : cellPos(c, i, index)
      if (!out.includes(pos)) out.push(pos)
    }
    return out
  }
  const rowNodeAt = (c: Ctx, row: number): { node: PMNode; pos: number } => {
    let pos = c.start
    for (let i = 0; i < row; i++) pos += c.table.child(i).nodeSize
    return { node: c.table.child(row), pos }
  }

  /* ---- measuring */
  const measure = React.useCallback(() => {
    const s = self.current
    const ed = editor
    let cellEl: HTMLElement | null = null
    if (s.anchorPos !== null && ed && !ed.isDestroyed) {
      try {
        const dom = ed.view.nodeDOM(s.anchorPos)
        cellEl = dom instanceof HTMLElement ? dom : null
      } catch {
        cellEl = null
      }
    }
    if (cellEl)
      s.wrapper =
        cellEl.closest<HTMLElement>(".tableWrapper") ?? cellEl.closest("table")
    const w = s.wrapper
    if (!w || !w.isConnected) {
      s.wrapper = null
      s.anchorPos = null
      setGeo(EMPTY)
      return
    }
    const tableBox = box(w.getBoundingClientRect())
    const inCard = (x: number) =>
      x >= tableBox.left && x <= tableBox.left + tableBox.width
    const r = cellEl?.closest("tr")
    const rowBox = r ? box(r.getBoundingClientRect()) : null
    // a column scrolled out of the card has no handle over the page
    let colBox: Box | null = null
    if (cellEl) {
      const cr = cellEl.getBoundingClientRect()
      const mid = cr.left + cr.width / 2
      colBox = inCard(mid)
        ? {
            left: cr.left,
            top: tableBox.top,
            width: cr.width,
            height: tableBox.height,
          }
        : null
    }
    const selected = w.querySelectorAll<HTMLElement>(".selectedCell")
    // on the table's own edge the ring keeps to the cell's edge, a pixel
    // inside the rule
    const colMid = colBox && colBox.left + colBox.width / 2
    const rowMid = rowBox && rowBox.top + rowBox.height / 2
    let ringTop = false
    let ringLeft = false
    selected.forEach((el) => {
      const b = el.getBoundingClientRect()
      const tr = el.parentElement
      if (
        colMid !== null &&
        colMid !== undefined &&
        tr === tr?.parentElement?.firstElementChild &&
        colMid >= b.left &&
        colMid <= b.right
      )
        ringTop = true
      if (
        rowMid !== null &&
        rowMid !== undefined &&
        el === tr?.firstElementChild &&
        rowMid >= b.top &&
        rowMid <= b.bottom
      )
        ringLeft = true
    })
    let cellBox: Box | null = null
    let cellKnobOn = false
    const kind = geoRef.current.selKind
    if (selected.length) {
      let left = Infinity
      let top = Infinity
      let right = -Infinity
      let bottom = -Infinity
      selected.forEach((el) => {
        const b = el.getBoundingClientRect()
        left = Math.min(left, b.left)
        top = Math.min(top, b.top)
        right = Math.max(right, b.right)
        bottom = Math.max(bottom, b.bottom)
      })
      cellBox = { left, top, width: right - left, height: bottom - top }
      cellKnobOn = inCard(right)
    } else if (cellEl && kind === "caret") {
      cellBox = box(cellEl.getBoundingClientRect())
      cellKnobOn = inCard(cellBox.left + cellBox.width)
    }
    // the menus read the row's header state fresh
    const c = ctxOf(ed)
    let isHeaderRow = false
    if (c && geoRef.current.rowIndex === 0) {
      const first = c.table.child(0)
      isHeaderRow = first.childCount > 0
      for (let i = 0; i < first.childCount; i++)
        if (first.child(i).type.name !== "tableHeader") isHeaderRow = false
    }
    setGeo((g) => ({
      ...g,
      tableBox,
      rowBox,
      colBox,
      cellBox,
      cellKnobOn,
      ringTop,
      ringLeft,
      isHeaderRow,
    }))
  }, [editor, ctxOf])

  // the run's selection box is drawn by the overlay on the cells' outer
  // edges; it moves out onto the rules, stops at the card's edge, and at a
  // corner of the card takes the card's inner 11px radius
  /* ---- the selection: a row, a column, a run of cells, or the caret's
     cell; the cell under the pointer takes over from a caret */
  const syncSelection = React.useCallback(() => {
    const s = self.current
    const ed = editor
    if (!ed || ed.isDestroyed || !ed.isEditable || menuOpenRef.current) return
    let view
    try {
      view = ed.view
    } catch {
      return
    }
    const { selection } = ed.state
    const $selCell = isInTable(ed.state) ? cellAround(selection.$from) : null
    let $cell = $selCell
    let kind: SelKind = null
    let count = 0
    if ($selCell) {
      const cells = asCellSelection(selection)
      if (cells) {
        cells.forEachCell(() => count++)
        kind = cells.isRowSelection()
          ? "row"
          : cells.isColSelection()
            ? "col"
            : "cells"
      } else {
        count = 1
        kind = "caret"
      }
    }
    if (s.hoverPos !== null && (kind === "caret" || kind === null)) {
      const $hover = cellAt(ed, s.hoverPos)
      if ($hover) $cell = $hover
    }
    if (!$cell) {
      // the caret left the table: the controls stay while the pointer hovers
      if (!s.hovering) {
        s.wrapper = null
        s.anchorPos = null
        setGeo(EMPTY)
        return
      }
      s.anchorPos = null
      setGeo((g) => ({ ...g, cellBox: null, cellCount: 0, selKind: null }))
      return
    }
    const c = ctxAt(ed, $cell)
    if (!c) return
    const dom = view.nodeDOM(c.start - 1)
    const tableDom =
      dom instanceof HTMLElement
        ? dom.tagName === "TABLE"
          ? dom
          : dom.querySelector("table")
        : null
    const wrapper = tableDom?.closest<HTMLElement>(".tableWrapper") ?? tableDom
    if (wrapper) s.wrapper = wrapper
    const rect = c.map.findCell($cell.pos - c.start)
    s.anchorPos = $cell.pos
    const cell = $selCell?.nodeAfter
    setGeo((g) => ({
      ...g,
      rowIndex: rect.top,
      colIndex: rect.left,
      cellCount: count,
      selKind: kind,
      cellMerged:
        !!cell && (cell.attrs.colspan > 1 || cell.attrs.rowspan > 1),
    }))
    // measured on the fresh indices
    geoRef.current = {
      ...geoRef.current,
      rowIndex: rect.top,
      colIndex: rect.left,
      selKind: kind,
    }
    measure()
  }, [editor, measure])

  const cellAt = (ed: TiptapEditor, pos: number): ResolvedPos | null => {
    try {
      const $pos = ed.state.doc.resolve(pos)
      const role = (
        $pos.nodeAfter?.type.spec as { tableRole?: string } | undefined
      )?.tableRole
      return role === "cell" || role === "header_cell" ? $pos : null
    } catch {
      return null
    }
  }

  /* ---- widths. tiptap's resize sets only the dragged column's width, so
     before a column is added or resized every column is told the width it
     has, and the table grows past the card instead of squeezing */
  const columnWidths = (c: Ctx): number[] => {
    const cols = [...(self.current.wrapper?.querySelectorAll("col") ?? [])]
    let raw: number[]
    // Safari rects a sizeless <col> at 0: only trust the colgroup when
    // every column measures, and fall back to the first row's cells
    const colWidths =
      cols.length === c.map.width
        ? cols.map((col) => col.getBoundingClientRect().width)
        : null
    if (colWidths && colWidths.every((w) => w > 0)) raw = colWidths
    else {
      raw = []
      for (let i = 0; i < c.map.width; i++) {
        const dom = c.ed.view.nodeDOM(c.start + c.map.map[i])
        raw.push(
          dom instanceof HTMLElement ? dom.getBoundingClientRect().width : 100
        )
      }
    }
    return wholePixels(raw)
  }
  const wholePixels = (raw: number[]): number[] => {
    const total = Math.round(raw.reduce((a, b) => a + b, 0))
    const floors = raw.map((w) => Math.floor(w))
    let left = total - floors.reduce((a, b) => a + b, 0)
    const order = raw
      .map((w, i) => ({ i, rest: w - Math.floor(w) }))
      .sort((a, b) => b.rest - a.rest)
    for (const { i } of order) {
      if (left <= 0) break
      floors[i] += 1
      left -= 1
    }
    return floors
  }
  const holdWidths = (c: Ctx, widths: number[]) => {
    const tr = c.ed.state.tr
    const seen = new Set<number>()
    c.map.map.forEach((rel) => {
      if (seen.has(rel)) return
      seen.add(rel)
      const pos = c.start + rel
      const cell = c.ed.state.doc.nodeAt(pos)
      if (!cell) return
      const r = c.map.findCell(rel)
      const colwidth = widths.slice(r.left, r.right)
      const had = cell.attrs.colwidth as number[] | null
      if (
        had &&
        had.length === colwidth.length &&
        had.every((w, k) => w === colwidth[k])
      )
        return
      tr.setNodeMarkup(pos, null, { ...cell.attrs, colwidth })
    })
    // the widths written as they already stand: nothing moves, nothing
    // slides
    tr.setMeta(SMOOTH_SKIP, true)
    if (tr.docChanged) c.ed.view.dispatch(tr)
  }
  const hasUnsizedColumn = (c: Ctx): boolean => {
    let unsized = false
    c.table.descendants((node) => {
      if (unsized) return false
      const name = node.type.name
      if (name !== "tableCell" && name !== "tableHeader") return true
      if (!node.attrs.colwidth) unsized = true
      return false
    })
    return unsized
  }
  /** `add` puts a column at `at`; it takes column `like`'s width */
  const withColumnAdded = (
    c: Ctx,
    at: number,
    like: number,
    add: () => void
  ) => {
    const widths = columnWidths(c)
    add()
    const fresh = ctxOf(c.ed)
    if (!fresh || fresh.map.width !== widths.length + 1) return
    const next = widths.slice()
    next.splice(at, 0, widths[Math.min(Math.max(like, 0), widths.length - 1)])
    holdWidths(fresh, next)
  }
  // a resize in the offing (tiptap's handle armed under the pointer) on a
  // table with columns still sharing the card: they hold their widths now
  const holdBeforeResize = React.useCallback(
    (ed: TiptapEditor) => {
      const armed =
        columnResizingPluginKey.getState(ed.state)?.activeHandle ?? -1
      if (armed < 0) return
      let c: Ctx | null = null
      try {
        c = ctxAt(ed, ed.state.doc.resolve(armed))
      } catch {
        c = null
      }
      if (!c) return
      // the context is keyed off the armed handle, not the hovered wrapper
      const el = ed.view.nodeDOM(c.start - 1)
      const wrapper =
        el instanceof HTMLElement
          ? (el.closest(".tableWrapper") as HTMLElement | null) ??
            (el.querySelector(".tableWrapper") as HTMLElement | null)
          : null
      if (wrapper) self.current.wrapper = wrapper
      if (!hasUnsizedColumn(c)) return
      holdWidths(c, columnWidths(c))
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [editor]
  )

  /* ---- actions */
  const focusCell = (c: Ctx, pos: number) => {
    c.ed.view.dispatch(
      c.ed.state.tr.setSelection(TextSelection.create(c.ed.state.doc, pos + 2))
    )
  }
  const selectRow = React.useCallback(
    (row: number) => {
      const c = ctxOf(editor)
      if (!c) return
      const { doc } = c.ed.state
      const sel = CellSelection.rowSelection(
        doc.resolve(cellPos(c, row, 0)),
        doc.resolve(cellPos(c, row, c.map.width - 1))
      )
      c.ed.view.dispatch(c.ed.state.tr.setSelection(sel))
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [editor, ctxOf]
  )
  const selectCol = React.useCallback(
    (col: number) => {
      const c = ctxOf(editor)
      if (!c) return
      const { doc } = c.ed.state
      const sel = CellSelection.colSelection(
        doc.resolve(cellPos(c, 0, col)),
        doc.resolve(cellPos(c, c.map.height - 1, col))
      )
      c.ed.view.dispatch(c.ed.state.tr.setSelection(sel))
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [editor, ctxOf]
  )
  const clearCells = (c: Ctx, positions: number[]) => {
    const tr = c.ed.state.tr
    const paragraph = c.ed.schema.nodes.paragraph
    ;[...positions]
      .sort((a, b) => b - a)
      .forEach((pos) => {
        const cell = tr.doc.nodeAt(pos)
        if (!cell) return
        tr.replaceWith(pos + 1, pos + cell.nodeSize - 1, paragraph.create())
      })
    c.ed.view.dispatch(tr)
  }
  const withCtx = (run: (c: Ctx) => void) => {
    const c = ctxOf(editor)
    if (!c) return
    run(c)
    editor.commands.focus(undefined, { scrollIntoView: false })
  }

  const g = geoRef
  const rowActions = {
    insertAbove: () =>
      withCtx((c) => {
        focusCell(c, cellPos(c, g.current.rowIndex, 0))
        c.ed.commands.addRowBefore()
      }),
    insertBelow: () =>
      withCtx((c) => {
        focusCell(c, cellPos(c, g.current.rowIndex, 0))
        c.ed.commands.addRowAfter()
      }),
    duplicate: () =>
      withCtx((c) => {
        const { node, pos } = rowNodeAt(c, g.current.rowIndex)
        c.ed.view.dispatch(
          c.ed.state.tr.insert(
            pos + node.nodeSize,
            node.type.create(node.attrs, node.content)
          )
        )
      }),
    clear: () =>
      withCtx((c) => clearCells(c, cellsIn(c, "row", g.current.rowIndex))),
    remove: () =>
      withCtx((c) => {
        if (c.map.height === 1) {
          c.ed.commands.deleteTable()
          return
        }
        selectRow(g.current.rowIndex)
        c.ed.commands.deleteRow()
      }),
    colour: (name: string | null) =>
      withCtx((c) => {
        selectRow(g.current.rowIndex)
        c.ed.commands.setCellBackground(name)
      }),
    toggleHeader: () =>
      withCtx((c) => {
        focusCell(c, cellPos(c, 0, 0))
        c.ed.commands.toggleHeaderRow()
      }),
  }
  const colActions = {
    insertLeft: () =>
      withCtx((c) =>
        withColumnAdded(c, g.current.colIndex, g.current.colIndex, () => {
          focusCell(c, cellPos(c, 0, g.current.colIndex))
          c.ed.commands.addColumnBefore()
        })
      ),
    insertRight: () =>
      withCtx((c) =>
        withColumnAdded(c, g.current.colIndex + 1, g.current.colIndex, () => {
          focusCell(c, cellPos(c, 0, g.current.colIndex))
          c.ed.commands.addColumnAfter()
        })
      ),
    duplicate: () =>
      withCtx((c) =>
        withColumnAdded(c, g.current.colIndex + 1, g.current.colIndex, () => {
          const tr = c.ed.state.tr
          cellsIn(c, "col", g.current.colIndex)
            .sort((a, b) => b - a)
            .forEach((pos) => {
              const cell = tr.doc.nodeAt(pos)
              if (!cell) return
              tr.insert(
                pos + cell.nodeSize,
                cell.type.create(cell.attrs, cell.content)
              )
            })
          c.ed.view.dispatch(tr)
        })
      ),
    clear: () =>
      withCtx((c) => clearCells(c, cellsIn(c, "col", g.current.colIndex))),
    remove: () =>
      withCtx((c) => {
        if (c.map.width === 1) {
          c.ed.commands.deleteTable()
          return
        }
        selectCol(g.current.colIndex)
        c.ed.commands.deleteColumn()
      }),
    colour: (name: string | null) =>
      withCtx((c) => {
        selectCol(g.current.colIndex)
        c.ed.commands.setCellBackground(name)
      }),
  }
  const cellActions = {
    colour: (name: string | null) =>
      withCtx((c) => c.ed.commands.setCellBackground(name)),
    merge: () => withCtx((c) => c.ed.commands.mergeCells()),
    split: () => withCtx((c) => c.ed.commands.splitCell()),
    clear: () =>
      withCtx((c) => {
        const { selection } = c.ed.state
        const positions: number[] = []
        const cells = asCellSelection(selection)
        if (cells) cells.forEachCell((_n, pos) => positions.push(pos))
        else {
          const $cell = cellAround(selection.$from)
          if ($cell) positions.push($cell.pos)
        }
        clearCells(c, positions)
      }),
  }
  const addColumnAtEnd = () =>
    withCtx((c) =>
      withColumnAdded(c, c.map.width, c.map.width - 1, () => {
        focusCell(c, cellPos(c, 0, c.map.width - 1))
        c.ed.commands.addColumnAfter()
      })
    )
  const addRowAtEnd = () =>
    withCtx((c) => {
      focusCell(c, cellPos(c, c.map.height - 1, 0))
      c.ed.commands.addRowAfter()
    })

  /* ---- hovering */
  React.useEffect(() => {
    const onMove = (e: MouseEvent) => {
      const s = self.current
      const ed = editor
      if (!ed || ed.isDestroyed || !ed.isEditable || menuOpenRef.current)
        return
      if (s.press?.active) return
      const target = e.target instanceof Element ? e.target : null
      if (!target) return
      if (layerRef.current?.contains(target)) return
      const cell = target.closest<HTMLElement>(".rte-doc td, .rte-doc th")
      if (cell) {
        s.hovering = true
        let pos: number | null = null
        try {
          const $cell = cellAround(
            ed.state.doc.resolve(ed.view.posAtDOM(cell, 0))
          )
          pos = $cell ? $cell.pos : null
        } catch {
          pos = null
        }
        if (pos === null || pos === s.hoverPos) return
        s.hoverPos = pos
        syncSelection()
        return
      }
      const t = geoRef.current.tableBox
      const near =
        t &&
        e.clientX >= t.left - 12 &&
        e.clientX <= t.left + t.width + 28 &&
        e.clientY >= t.top - 12 &&
        e.clientY <= t.top + t.height + 28
      if (near) return
      s.hovering = false
      if (s.hoverPos === null) {
        if (!isInTable(ed.state)) {
          s.wrapper = null
          s.anchorPos = null
          setGeo(EMPTY)
        }
        return
      }
      s.hoverPos = null
      syncSelection()
    }
    // the widths hold when a column's resize begins (the plugin's drag,
    // below), not when its border is only hovered: holding them is an edit
    // of the table, which a pointer passing over a border must not make
    document.addEventListener("mousemove", onMove, true)
    return () => document.removeEventListener("mousemove", onMove, true)
  }, [editor, syncSelection, holdBeforeResize])

  /* ---- subscriptions: batched on a microtask */
  React.useEffect(() => {
    let pending = false
    const schedule = () => {
      if (pending) return
      pending = true
      queueMicrotask(() => {
        pending = false
        if (!menuOpenRef.current) syncSelection()
        measure()
      })
    }
    const onTransaction = ({
      transaction,
    }: {
      transaction: { mapping: { map: (pos: number) => number } }
    }) => {
      const s = self.current
      if (s.hoverPos !== null) s.hoverPos = transaction.mapping.map(s.hoverPos)
      // a resize can begin before the hover hold has run (Safari delivers
      // the press before our move listener sees the armed handle): the
      // plugin's dragging flag is the sure signal, and the widths hold on
      // its first appearance
      const resizing = !!columnResizingPluginKey.getState(editor.state)
        ?.dragging
      if (resizing && !s.resizeHeld) {
        s.resizeHeld = true
        holdBeforeResize(editor)
      } else if (!resizing && s.resizeHeld) {
        s.resizeHeld = false
      }
      schedule()
    }
    editor.on("transaction", onTransaction)
    document.addEventListener("scroll", schedule, true)
    window.addEventListener("resize", schedule)
    return () => {
      editor.off("transaction", onTransaction)
      document.removeEventListener("scroll", schedule, true)
      window.removeEventListener("resize", schedule)
    }
  }, [editor, syncSelection, measure, holdBeforeResize])

  // a closed menu lets the pointer take over again
  const menuOpen = rowOpen || colOpen || cellOpen
  React.useEffect(() => {
    if (!menuOpen) {
      queueMicrotask(() => {
        syncSelection()
        measure()
      })
    }
  }, [menuOpen, syncSelection, measure])

  // the table's own changes of shape: resize writes widths straight into
  // the DOM with no transaction, so the handles re-measure on mutations
  const wrapper = self.current.wrapper
  React.useEffect(() => {
    const w = wrapper
    if (!w) return
    const mo = new MutationObserver((records) => {
      if (
        records.some(
          (r) =>
            !(r.target instanceof Element) ||
            !r.target.classList.contains("table-selection-box")
        )
      )
        measure()
    })
    mo.observe(w, { attributes: true, attributeFilter: ["style"], subtree: true })
    const ro = new ResizeObserver(() => measure())
    ro.observe(w)
    const table = w.querySelector("table")
    if (table) ro.observe(table)
    // the card scrolls its columns, never its rows
    const level = () => {
      if (w.scrollTop) w.scrollTop = 0
    }
    level()
    w.addEventListener("scroll", level)
    return () => {
      mo.disconnect()
      ro.disconnect()
      w.removeEventListener("scroll", level)
    }
  }, [wrapper, measure])

  /* ---- a press on a grip selects; carried 4px it drags */
  const stills = () =>
    window.matchMedia("(prefers-reduced-motion: reduce)").matches

  const canDrag = (kind: DragKind, index: number): boolean => {
    const c = ctxOf(editor)
    if (!c || index < 0) return false
    if ((kind === "row" ? c.map.height : c.map.width) < 2) return false
    let ok = true
    c.table.descendants((node) => {
      if (!ok) return false
      const name = node.type.name
      if (name !== "tableCell" && name !== "tableHeader") return true
      if (node.attrs.rowspan > 1 || (kind === "col" && node.attrs.colspan > 1))
        ok = false
      return false
    })
    return ok
  }
  const edgesOf = (w: HTMLElement, kind: DragKind): number[] => {
    if (kind === "row") {
      const rows = [...w.querySelectorAll<HTMLElement>("tr")].map((r) =>
        r.getBoundingClientRect()
      )
      if (!rows.length) return []
      return [...rows.map((r) => r.top), rows[rows.length - 1].bottom]
    }
    const cells = [...(w.querySelector("tr")?.children ?? [])].map((c) =>
      c.getBoundingClientRect()
    )
    if (!cells.length) return []
    return [...cells.map((r) => r.left), cells[cells.length - 1].right]
  }

  const aim = React.useCallback(() => {
    const s = self.current
    const p = s.press
    const w = s.wrapper
    const t = geoRef.current.tableBox
    if (!p || !p.active || p.kind === "cell" || !w || !t) return
    const edges = edgesOf(w, p.kind)
    if (!edges.length) return
    const at = p.kind === "row" ? p.lastY : p.lastX
    let to = 0
    let best = Infinity
    edges.forEach((edge, i) => {
      const d = Math.abs(edge - at)
      if (d < best) {
        best = d
        to = i
      }
    })
    const lineAt = (edge: number): Box =>
      p.kind === "row"
        ? { left: t.left + 1, top: edge - 1.5, width: t.width - 2, height: 3 }
        : { left: edge - 1.5, top: t.top + 1, width: 3, height: t.height - 2 }
    const inCard = (x: number) => x >= t.left && x <= t.left + t.width
    if (to === p.index || to === p.index + 1) {
      p.to = null
      setDropOn(false)
      if (!s.dropLine) {
        s.dropLine = lineAt(edges[to])
        setDropLine(s.dropLine)
      }
      return
    }
    p.to = to
    s.dropLine = lineAt(edges[to])
    setDropLine(s.dropLine)
    setDropOn(p.kind === "row" || inCard(edges[to]))
  }, [])

  const lift = React.useCallback(
    (p: NonNullable<(typeof self)["current"]["press"]>) => {
      const s = self.current
      const w = s.wrapper
      const table = w?.querySelector("table")
      if (!w || !table || p.kind === "cell") return
      dropGhost()
      const rows = [...w.querySelectorAll<HTMLElement>("tr")]
      const tb = table.getBoundingClientRect()
      const host = document.createElement("div")
      host.className = "rte-tc-ghost"
      const copy = document.createElement("table")
      const body = document.createElement("tbody")
      if (p.kind === "row") {
        const src = rows[p.index]
        if (!src) return
        const r = src.getBoundingClientRect()
        const cols = table.querySelector("colgroup")
        if (cols) copy.appendChild(cols.cloneNode(true))
        body.appendChild(src.cloneNode(true))
        copy.style.width = `${tb.width}px`
        s.ghostAt = { left: tb.left, top: r.top, size: r.height }
        s.grab = p.y - r.top
      } else {
        let width = 0
        rows.forEach((row) => {
          const cell = row.children[p.index] as HTMLElement | undefined
          if (!cell) return
          const r = cell.getBoundingClientRect()
          width = Math.max(width, r.width)
          const tr = document.createElement("tr")
          const td = cell.cloneNode(true) as HTMLElement
          td.style.height = `${r.height}px`
          tr.appendChild(td)
          body.appendChild(tr)
        })
        copy.style.width = `${width}px`
        const first = rows[0]?.children[p.index]?.getBoundingClientRect()
        s.ghostAt = { left: first?.left ?? tb.left, top: tb.top, size: width }
        s.grab = p.x - s.ghostAt.left
      }
      body
        .querySelectorAll(".selectedCell")
        .forEach((el) => el.classList.remove("selectedCell"))
      copy.appendChild(body)
      host.appendChild(copy)
      host.style.left = `${s.ghostAt.left}px`
      host.style.top = `${s.ghostAt.top}px`
      host.style.width = `${p.kind === "row" ? tb.width : s.ghostAt.size}px`
      document.body.appendChild(host)
      s.ghost = host
      carry(p)
      requestAnimationFrame(() => s.ghost?.classList.add("is-up"))
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  )
  const carry = (p: NonNullable<(typeof self)["current"]["press"]>) => {
    const s = self.current
    const t = geoRef.current.tableBox
    if (!s.ghost || !t || p.kind === "cell") return
    if (p.kind === "row") {
      const top = Math.min(
        Math.max(p.lastY - s.grab, t.top + 1),
        t.top + t.height - 1 - s.ghostAt.size
      )
      s.ghost.style.transform = `translate3d(0, ${top - s.ghostAt.top}px, 0)`
    } else {
      const left = Math.min(
        Math.max(p.lastX - s.grab, t.left + 1),
        t.left + t.width - 1 - s.ghostAt.size
      )
      s.ghost.style.transform = `translate3d(${left - s.ghostAt.left}px, 0, 0)`
    }
  }
  const dropGhost = () => {
    const s = self.current
    const ghost = s.ghost
    s.ghost = null
    if (!ghost) return
    ghost.classList.remove("is-up")
    const gone = () => ghost.remove()
    if (stills()) gone()
    else {
      ghost.addEventListener("transitionend", gone, { once: true })
      window.setTimeout(gone, 200)
    }
  }

  // near the scroller's edge the page scrolls on, and the line follows
  const autoScroll = React.useCallback(() => {
    const s = self.current
    s.scrollRaf = 0
    const p = s.press
    const w = s.wrapper
    if (!p || !p.active || !w) return
    let moved = false
    if (p.kind === "row") {
      const sp = scrollParentOf(w)
      if (sp) {
        const r =
          sp === document.scrollingElement
            ? { top: 0, bottom: window.innerHeight }
            : sp.getBoundingClientRect()
        let dy = 0
        if (p.lastY < r.top + SCROLL_EDGE)
          dy = -Math.ceil((r.top + SCROLL_EDGE - p.lastY) / 4)
        else if (p.lastY > r.bottom - SCROLL_EDGE)
          dy = Math.ceil((p.lastY - (r.bottom - SCROLL_EDGE)) / 4)
        if (dy) {
          const before = sp.scrollTop
          sp.scrollTop += dy
          moved = sp.scrollTop !== before
        }
      }
    } else {
      const r = w.getBoundingClientRect()
      let dx = 0
      if (p.lastX < r.left + SCROLL_EDGE)
        dx = -Math.ceil((r.left + SCROLL_EDGE - p.lastX) / 4)
      else if (p.lastX > r.right - SCROLL_EDGE)
        dx = Math.ceil((p.lastX - (r.right - SCROLL_EDGE)) / 4)
      if (dx) {
        const before = w.scrollLeft
        w.scrollLeft += dx
        moved = w.scrollLeft !== before
      }
    }
    if (moved) {
      measure()
      aim()
    }
    s.scrollRaf = requestAnimationFrame(autoScroll)
  }, [measure, aim])
  const scrollParentOf = (el: HTMLElement | null): HTMLElement | null => {
    for (let n = el?.parentElement; n; n = n.parentElement) {
      const o = getComputedStyle(n).overflowY
      if ((o === "auto" || o === "scroll") && n.scrollHeight > n.clientHeight)
        return n
    }
    return (document.scrollingElement as HTMLElement | null) ?? null
  }

  /** every cell's place, by row and column */
  const placesIn = (w: HTMLElement): DOMRect[][] =>
    [...w.querySelectorAll("tr")].map((row) =>
      [...row.children].map((cell) => cell.getBoundingClientRect())
    )
  // after the move every cell slides from where it was to where it is, the
  // moved line's ring arriving as they land. Web Animations, not styles.
  const settle = (
    w: HTMLElement,
    kind: DragKind,
    from: number,
    at: number,
    before: DOMRect[][]
  ) => {
    const n = kind === "row" ? before.length : (before[0]?.length ?? 0)
    const order = [...Array(n).keys()]
    const [moved] = order.splice(from, 1)
    order.splice(at, 0, moved)
    const rows = [...w.querySelectorAll<HTMLElement>("tr")]
    const moves: [HTMLElement, number][] = []
    rows.forEach((row, r) => {
      ;[...row.children].forEach((el, col) => {
        const was =
          kind === "row" ? before[order[r]]?.[col] : before[r]?.[order[col]]
        if (!was) return
        const now = el.getBoundingClientRect()
        const d = kind === "row" ? was.top - now.top : was.left - now.left
        if (Math.abs(d) > 0.5) moves.push([el as HTMLElement, d])
      })
    })
    if (!moves.length) return
    const axis = kind === "row" ? "translateY" : "translateX"
    moves.forEach(([el, d]) =>
      el.animate([{ transform: `${axis}(${d}px)` }, { transform: "none" }], SETTLE)
    )
    // the selection ring waits out the slide and arrives as the cells land
    window.dispatchEvent(new Event(TABLE_SETTLE))
  }

  /** the leading rows made of header cells */
  const headerRows = (c: Ctx): number => {
    let n = 0
    for (let i = 0; i < c.table.childCount; i++) {
      const row = c.table.child(i)
      let all = row.childCount > 0
      for (let j = 0; j < row.childCount; j++)
        if (row.child(j).type.name !== "tableHeader") all = false
      if (!all) break
      n++
    }
    return n
  }
  // the move: the table rebuilt with its rows (or every row's cells) in
  // the new order, and the moved line selected again
  const moveLine = (kind: DragKind, from: number, to: number) => {
    const c = ctxOf(editor)
    if (!c) return
    const at = to > from ? to - 1 : to
    if (at === from) return
    const w = self.current.wrapper
    const before = w && !stills() ? placesIn(w) : null
    const { tableCell, tableHeader } = c.ed.schema.nodes
    const header = headerRows(c)
    const rows: PMNode[] = []
    for (let i = 0; i < c.table.childCount; i++) rows.push(c.table.child(i))
    let next: PMNode[]
    if (kind === "row") {
      const order = rows.slice()
      const [row] = order.splice(from, 1)
      order.splice(at, 0, row)
      next = order.map((row, i) => {
        const type = i < header ? tableHeader : tableCell
        const cells: PMNode[] = []
        row.forEach((cell) =>
          cells.push(
            cell.type === type
              ? cell
              : type.create(cell.attrs, cell.content, cell.marks)
          )
        )
        return row.copy(Fragment.from(cells))
      })
    } else {
      next = rows.map((row) => {
        const cells: PMNode[] = []
        row.forEach((cell) => cells.push(cell))
        const [cell] = cells.splice(from, 1)
        cells.splice(at, 0, cell)
        return row.copy(Fragment.from(cells))
      })
    }
    const table = c.table.copy(Fragment.from(next))
    const tr = c.ed.state.tr.replaceWith(
      c.start - 1,
      c.start - 1 + c.table.nodeSize,
      table
    )
    const map = TableMap.get(table)
    const cell = (row: number, col: number) =>
      tr.doc.resolve(c.start + map.map[row * map.width + col])
    tr.setSelection(
      kind === "row"
        ? CellSelection.rowSelection(cell(at, 0), cell(at, map.width - 1))
        : CellSelection.colSelection(cell(0, at), cell(map.height - 1, at))
    )
    c.ed.view.dispatch(tr)
    if (w && before) settle(w, kind, from, at, before)
  }

  // The press is driven from window listeners, not pointer capture on the
  // grip: the grip is a React-rendered button in a layer that re-renders
  // as the selection and geometry move, and an unmount mid-drag would
  // take the captured pointer's events with it — the release never
  // arriving, the ghost and the drop line left standing (the stuck-drag
  // bug). Window listeners outlive any re-render.
  const pressDetach = React.useRef<(() => void) | null>(null)
  const endPress = React.useCallback(() => {
    const s = self.current
    const p = s.press
    s.press = null
    pressDetach.current?.()
    pressDetach.current = null
    if (!p) return
    setDragKind(null)
    setDropLine(null)
    setDropOn(false)
    s.dropLine = null
    dropGhost()
    document.body.classList.remove("rte-tc-dragging")
    document.removeEventListener("keydown", onDragKey, true)
    if (s.scrollRaf) cancelAnimationFrame(s.scrollRaf)
    s.scrollRaf = 0
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  const onDragKey = React.useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault()
        endPress()
      }
    },
    [endPress]
  )

  const onPressMove = (e: PointerEvent) => {
    const s = self.current
    const p = s.press
    if (!p || (p.pointerId !== -1 && p.pointerId !== e.pointerId)) return
    p.lastX = e.clientX
    p.lastY = e.clientY
    if (!p.active) {
      if (p.kind === "cell") return
      if (Math.hypot(e.clientX - p.x, e.clientY - p.y) < DRAG_START) return
      if (!canDrag(p.kind, p.index)) return
      p.active = true
      setDragKind(p.kind)
      openFor[p.kind](false)
      document.body.classList.add("rte-tc-dragging")
      document.addEventListener("keydown", onDragKey, true)
      lift(p)
      autoScroll()
    }
    aim()
    carry(p)
  }
  const onRelease = (e: PointerEvent) => {
    const p = self.current.press
    if (!p || (p.pointerId !== -1 && p.pointerId !== e.pointerId)) return
    endPress()
    if (p.active) {
      if (p.to !== null) moveLine(p.kind as DragKind, p.index, p.to)
    } else if (!p.wasOpen) {
      // after the press's trailing click has passed (opening into it reads
      // as an outside press), and through the real trigger: a bare
      // setState open carries no press reason, and Base UI's hover
      // interaction closes a reasonless menu the moment the pointer
      // brushes the popup it opened under (Chrome fires those synthetic
      // moves; the grip sits right where the popup lands)
      const kind = p.kind
      window.setTimeout(() => {
        const anchor = anchorRefs[kind].current
        if (anchor) {
          // down AND up: the up releases Base UI's press tracking, or the
          // next release over a menu item would run the item twice
          for (const type of ["mousedown", "mouseup"] as const) {
            anchor.dispatchEvent(
              new MouseEvent(type, {
                bubbles: true,
                cancelable: true,
                button: 0,
              })
            )
          }
        } else {
          openFor[kind](true)
        }
      }, 0)
    }
  }
  const onPressRef = React.useRef({ onPressMove, onRelease })
  onPressRef.current = { onPressMove, onRelease }

  const onPress = (kind: PressKind) => (e: PressEvent) => {
    const s = self.current
    if (e.button !== 0) return
    // a press that never saw its release (the pointer lost off-window)
    // yields to the new one rather than wedging every grip
    if (s.press) endPress()
    const index =
      kind === "row"
        ? geoRef.current.rowIndex
        : kind === "col"
          ? geoRef.current.colIndex
          : -1
    if (kind === "row") selectRow(index)
    else if (kind === "col") selectCol(index)
    const el = e.currentTarget as HTMLElement
    s.press = {
      kind,
      index,
      x: e.clientX,
      y: e.clientY,
      lastX: e.clientX,
      lastY: e.clientY,
      el,
      pointerId: pressPointerId(e),
      // an open menu closes on this press, and a release in place leaves
      // it closed
      wasOpen: isOpenRef.current[kind],
      active: false,
      to: null,
    }
    const move = (ev: PointerEvent) => onPressRef.current.onPressMove(ev)
    const up = (ev: PointerEvent) => onPressRef.current.onRelease(ev)
    const cancel = (ev: PointerEvent) => {
      const held = self.current.press
      if (held && (held.pointerId === -1 || held.pointerId === ev.pointerId))
        endPress()
    }
    window.addEventListener("pointermove", move)
    window.addEventListener("pointerup", up)
    window.addEventListener("pointercancel", cancel)
    pressDetach.current = () => {
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", up)
      window.removeEventListener("pointercancel", cancel)
    }
    e.preventDefault()
  }

  /* ---- the menus */
  const closeMenus = () => {
    setRowOpen(false)
    setColOpen(false)
    setCellOpen(false)
  }
  const colourMenu = (apply: (name: string | null) => void) => (
    <DropdownMenuSub>
      <DropdownMenuSubTrigger>
        <CellColorIcon className="size-4" />
        Colour
      </DropdownMenuSubTrigger>
      <DropdownMenuSubContent className="w-[220px] rounded-xl p-0">
        <div className="rte-tc-swatches" role="group" aria-label="Colour">
          <button
            type="button"
            className="rte-tc-swatch"
            title="Default"
            aria-label="Default"
            onClick={() => {
              apply(null)
              closeMenus()
            }}
          >
            A
          </button>
          {PALETTE.map((name) => (
            <button
              key={name}
              type="button"
              className="rte-tc-swatch"
              style={
                {
                  "--sw": `var(--color-${hue(name)}-50)`,
                  "--sw-dark": `var(--color-${hue(name)}-900)`,
                } as React.CSSProperties
              }
              title={name}
              aria-label={name}
              onClick={() => {
                apply(name)
                closeMenus()
              }}
            />
          ))}
        </div>
      </DropdownMenuSubContent>
    </DropdownMenuSub>
  )
  const item = (
    Icon: React.ComponentType<React.SVGProps<SVGSVGElement>>,
    label: string,
    run: () => void
  ) => (
    <DropdownMenuItem
      onClick={() => {
        run()
        closeMenus()
      }}
    >
      <Icon className="size-4" />
      {label}
    </DropdownMenuItem>
  )

  // the row menu opens 4px under its row, the column menu 4px under its grip
  const rowMenuOffset = (() => {
    const r = geo.rowBox
    if (!r) return 4
    const gripBottom = r.top + r.height / 2 + 10
    return Math.round(r.top + r.height - gripBottom + 4)
  })()

  if (!mounted) return null
  const { tableBox, rowBox, colBox, cellBox } = geo
  const menuCard = "w-[220px] rounded-xl shadow-elevation-xl"

  return createPortal(
    <div
      ref={layerRef}
      data-slot="rich-text-editor-table-controls"
      className="rte-tc pointer-events-none fixed inset-0 z-40"
      aria-hidden={false}
    >
      {/* the row handle, at the left edge of the caret's row */}
      {rowBox && tableBox && geo.selKind !== "col" && (
        <>
          <DropdownMenu open={rowOpen} onOpenChange={setRowOpen}>
            <DropdownMenuTrigger
              nativeButton={false}
              render={
                <span
                  ref={rowAnchorRef}
                  className="rte-tc-anchor"
                  style={{
                    left: px(tableBox.left - 4),
                    top: px(rowBox.top + rowBox.height / 2 - 10),
                    width: px(10),
                    height: px(20),
                  }}
                  aria-hidden="true"
                />
              }
            />
            <DropdownMenuContent
              side="bottom"
              align="start"
              sideOffset={rowMenuOffset}
              className={menuCard}
            >
              {geo.rowIndex === 0 && (
                <DropdownMenuItem
                  onClick={() => {
                    rowActions.toggleHeader()
                    closeMenus()
                  }}
                >
                  <HeaderRowIcon className="size-4" />
                  Table Header
                  <span
                    aria-hidden="true"
                    className={cn(
                      "ml-auto flex h-3.5 w-6 items-center rounded-full p-0.5 transition-colors",
                      geo.isHeaderRow ? "bg-primary" : "bg-muted"
                    )}
                  >
                    <span
                      className={cn(
                        "size-2.5 rounded-full bg-white transition-transform",
                        geo.isHeaderRow && "translate-x-2.5"
                      )}
                    />
                  </span>
                </DropdownMenuItem>
              )}
              {colourMenu(rowActions.colour)}
              {item(ArrowUpIcon, "Insert above", rowActions.insertAbove)}
              {item(ArrowDownIcon, "Insert below", rowActions.insertBelow)}
              {item(DuplicateIcon, "Duplicate", rowActions.duplicate)}
              {item(SmallCloseIcon, "Clear content", rowActions.clear)}
              {item(DeleteIcon, "Delete", rowActions.remove)}
            </DropdownMenuContent>
          </DropdownMenu>
          <button
            type="button"
            className={cn(
              "rte-tc-handle is-row",
              (rowOpen || dragKind === "row") && "is-open"
            )}
            style={{
              left: px(tableBox.left - 4),
              top: px(rowBox.top + rowBox.height / 2 - 10),
            }}
            aria-label="Row options"
            title="Row options"
            aria-haspopup="menu"
            aria-expanded={rowOpen}
            {...pressHandlers(onPress("row"))}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault()
                setRowOpen(true)
              }
            }}
          >
            <span className="rte-tc-pill" aria-hidden="true" />
            <span className="rte-tc-dots" aria-hidden="true" />
          </button>
          {/* the dash, drawn as a length of the table's own left rule: the
              same edge and the same 1px border, so the browser rounds it
              onto the same device pixels at any zoom */}
          <span
            className="rte-tc-edge is-row"
            style={{
              left: px(tableBox.left + (geo.ringLeft ? 1 : 0)),
              top: px(rowBox.top + rowBox.height / 2 - 7),
            }}
            aria-hidden="true"
          />
        </>
      )}

      {/* the column handle, at the top edge of the caret's column */}
      {colBox && geo.selKind !== "row" && (
        <>
          <DropdownMenu open={colOpen} onOpenChange={setColOpen}>
            <DropdownMenuTrigger
              nativeButton={false}
              render={
                <span
                  ref={colAnchorRef}
                  className="rte-tc-anchor"
                  style={{
                    left: px(colBox.left + colBox.width / 2 - 10),
                    top: px(colBox.top - 4),
                    width: px(20),
                    height: px(10),
                  }}
                  aria-hidden="true"
                />
              }
            />
            <DropdownMenuContent
              side="bottom"
              align="start"
              sideOffset={4}
              className={menuCard}
            >
              {colourMenu(colActions.colour)}
              {item(ArrowRightIcon, "Insert right", colActions.insertRight)}
              {item(ArrowLeftIcon, "Insert left", colActions.insertLeft)}
              {item(DuplicateIcon, "Duplicate", colActions.duplicate)}
              {item(SmallCloseIcon, "Clear content", colActions.clear)}
              {item(DeleteIcon, "Delete", colActions.remove)}
            </DropdownMenuContent>
          </DropdownMenu>
          <button
            type="button"
            className={cn(
              "rte-tc-handle is-col",
              (colOpen || dragKind === "col") && "is-open"
            )}
            style={{
              left: px(colBox.left + colBox.width / 2 - 10),
              top: px(colBox.top - 4),
            }}
            aria-label="Column options"
            title="Column options"
            aria-haspopup="menu"
            aria-expanded={colOpen}
            {...pressHandlers(onPress("col"))}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault()
                setColOpen(true)
              }
            }}
          >
            <span className="rte-tc-pill" aria-hidden="true" />
            <span className="rte-tc-dots" aria-hidden="true" />
          </button>
          {/* the dash, a length of the table's own top rule, as the row's */}
          {tableBox && (
            <span
              className="rte-tc-edge is-col"
              style={{
                left: px(colBox.left + colBox.width / 2 - 7),
                top: px(tableBox.top + (geo.ringTop ? 1 : 0)),
              }}
              aria-hidden="true"
            />
          )}
        </>
      )}

      {/* the cell handle, at the right edge of the selected run: its pill
          on the ring's right line */}
      {cellBox && geo.cellKnobOn && geo.selKind === "cells" && (
        <>
          <DropdownMenu open={cellOpen} onOpenChange={setCellOpen}>
            <DropdownMenuTrigger
              nativeButton={false}
              render={
                <span
                  ref={cellAnchorRef}
                  className="rte-tc-anchor"
                  style={{
                    left: px(cellBox.left + cellBox.width - 6),
                    top: px(cellBox.top + cellBox.height / 2 - 10),
                    width: px(10),
                    height: px(20),
                  }}
                  aria-hidden="true"
                />
              }
            />
            <DropdownMenuContent
              side="right"
              align="start"
              sideOffset={4}
              className={menuCard}
            >
              {colourMenu(cellActions.colour)}
              {geo.cellCount > 1 ? (
                <>
                  {item(CellMergeIcon, "Merge cells", cellActions.merge)}
                  {item(DeleteIcon, "Delete content", cellActions.clear)}
                </>
              ) : geo.cellMerged ? (
                item(CellMergeIcon, "Split cell", cellActions.split)
              ) : null}
            </DropdownMenuContent>
          </DropdownMenu>
          <button
            type="button"
            className={cn("rte-tc-handle is-row is-cell", cellOpen && "is-open")}
            style={{
              left: px(cellBox.left + cellBox.width - 6),
              top: px(cellBox.top + cellBox.height / 2 - 10),
            }}
            aria-label="Cell options"
            title="Cell options"
            aria-haspopup="menu"
            aria-expanded={cellOpen}
            {...pressHandlers(onPress("cell"))}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault()
                setCellOpen(true)
              }
            }}
          >
            <span className="rte-tc-pill" aria-hidden="true" />
            <span className="rte-tc-dots" aria-hidden="true" />
          </button>
        </>
      )}

      {/* the line a dragged row or column will land on */}
      {dragKind && dropLine && (
        <div
          className={cn("rte-tc-drop", dropOn && "is-on")}
          style={{
            left: px(dropLine.left),
            top: px(dropLine.top),
            width: px(dropLine.width),
            height: px(dropLine.height),
          }}
          aria-hidden="true"
        />
      )}

      {/* the add strips: a column at the right, a row beneath */}
      {tableBox && (
        <>
          <button
            type="button"
            className="rte-tc-strip"
            style={{
              left: px(tableBox.left + tableBox.width + 8),
              top: px(tableBox.top),
              width: px(16),
              height: px(tableBox.height),
            }}
            aria-label="Add column"
            title="Add column"
            onClick={addColumnAtEnd}
          >
            <Add12Icon className="size-3" />
          </button>
          <button
            type="button"
            className="rte-tc-strip"
            style={{
              left: px(tableBox.left),
              top: px(tableBox.top + tableBox.height + 8),
              width: px(tableBox.width),
              height: px(16),
            }}
            aria-label="Add row"
            title="Add row"
            onClick={addRowAtEnd}
          >
            <Add12Icon className="size-3" />
          </button>
        </>
      )}
    </div>,
    document.body
  )
}

"use client"

// The document's stylesheet, ported from the branch's RichTextEditor.vue
// <style> block and RteTableControls.vue, translated to this project's
// tokens (the theme file maps them: surface-gray-1 → --input, ink-gray-5 →
// --accent-foreground, outline-gray-1 → --border-soft, and so on). One
// injection, shared by every document editor on the page.
import * as React from "react"

const CELL_TINTS = [
  "red",
  "orange",
  "yellow",
  "green",
  "teal",
  "cyan",
  "blue",
  "violet",
  "purple",
  "pink",
  "gray",
]

const cellTintRules = CELL_TINTS.map(
  (hue) => `
.rte-doc td[data-bg='${hue}'], .rte-doc th[data-bg='${hue}'] { background-color: var(--color-${hue}-100); }
.dark .rte-doc td[data-bg='${hue}'], .dark .rte-doc th[data-bg='${hue}'] { background-color: var(--color-${hue}-900); }`
).join("\n")

const CSS = `
/* ---- bold runs: the prose scale's 600, in the headings' ink — the
   browser's 700 reads a step too heavy at the file's sizes ---- */
.rte-doc strong,
.rte-doc b {
  font-weight: 600;
  color: var(--foreground);
}

/* ---- mentions and links take the file's text grounds ---- */
/* a mention (32467:13501): a 22px gray-100 chip on 6px corners, the
   name in medium gray-600; under the pointer or picked, gray-700 */
.rte-doc .mention {
  background: var(--secondary);
  border-radius: 6px;
  padding: 0 3px;
  line-height: 22px;
  font-weight: 500;
  color: var(--muted-foreground);
}
.rte-doc .mention:hover,
.rte-doc .mention.ProseMirror-selectednode {
  background: var(--secondary);
  color: var(--secondary-foreground);
  box-shadow: none;
}
/* a link: medium gray-700 on its rule, gray-800 under the pointer; the one
   the caret is in, or its card is editing, sits on a 22px gray-100 ground
   on 4px corners */
.rte-doc a:not([data-attachment]) {
  color: var(--secondary-foreground);
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 2px;
  text-decoration-color: var(--border-normal);
}
.rte-doc a:not([data-attachment]):hover {
  color: var(--foreground);
}
.rte-doc .rte-link-on {
  color: var(--foreground);
  background: var(--secondary);
  border-radius: 4px;
  padding: 1.5px 0;
  box-shadow:
    -2px 0 0 var(--secondary),
    2px 0 0 var(--secondary);
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

/* ---- the audio player: a 42px bar, its slider the file's 2px track and
   14px knob on a soft shadow, the range in gray-900 ---- */
.rte-doc .rte-player {
  margin: 8px 0;
}
/* the player sizes itself to the room it is given (a narrow table cell, a
   column of a row): it never pushes its controls out past its edge, where
   the More button would stand over the next cell and its column's handle.
   Short of room, the track goes first, then the time, then the mute; the
   play and More buttons always stay. It asks for 160px at the least, so a
   column sized to its content keeps room for them */
.rte-doc .node-audio {
  container: rte-audio / inline-size;
  min-width: 160px;
}
@container rte-audio (max-width: 300px) {
  .rte-player .rte-player-slider {
    display: none;
  }
  .rte-player [data-player-end] {
    margin-left: auto;
  }
}
@container rte-audio (max-width: 210px) {
  .rte-player .rte-player-time {
    display: none;
  }
}
@container rte-audio (max-width: 150px) {
  .rte-player [data-player-mute] {
    display: none;
  }
}
.ProseMirror-selectednode > .rte-player {
  outline: 2px solid var(--border);
  outline-offset: 2px;
}
.rte-player-track {
  height: 2px;
  border-radius: 16px;
  background-color: var(--muted);
}
.rte-player-track > * {
  background-color: var(--foreground);
}
.rte-player-knob {
  width: 14px;
  height: 14px;
  box-shadow:
    0 2px 5px rgba(0, 0, 0, 0.14),
    0 0 1.5px rgba(0, 0, 0, 0.16),
    inset 0 0.25px 1.5px rgba(255, 255, 255, 0.16);
}
.rte-player-knob:hover {
  box-shadow:
    0 0 0 6px rgba(82, 82, 82, 0.12),
    0 2px 5px rgba(0, 0, 0, 0.14),
    0 0 1.5px rgba(0, 0, 0, 0.16);
}

/* ---- a callout: gray-50, 12px in, the emoji leading its first line ---- */
.rte-doc [data-type='callout'] {
  position: relative;
  margin: 8px 0;
  padding: 12px 12px 12px 36px;
  border-radius: 8px;
  background: var(--input);
}
.rte-doc [data-type='callout']::before {
  content: attr(data-emoji);
  position: absolute;
  left: 12px;
  top: 12px;
  font-size: 15px;
  line-height: 24px;
}
.rte-doc [data-type='callout'] > p:first-child {
  font-weight: 600;
  color: var(--foreground);
}
.rte-doc [data-type='callout'] > p + p {
  margin-top: 4px;
}

/* ---- columns: side by side on a 56px gutter, a hairline down its middle
   and, right of it, room for the next column's blocks' grip ---- */
.rte-doc [data-type='columns'] {
  display: grid;
  gap: 56px;
  margin: 8px 0;
}
.rte-doc [data-type='columns'][data-count='1'] {
  grid-template-columns: minmax(0, 1fr);
}
.rte-doc [data-type='columns'][data-count='2'] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.rte-doc [data-type='columns'][data-count='3'] {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.rte-doc [data-type='columns'][data-count='4'] {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.rte-doc [data-type='columns'][data-count='5'] {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}
.rte-doc [data-type='column'] {
  position: relative;
  min-width: 0;
}
/* the hairline stands in the gutter, as far from either column's text */
.rte-doc [data-type='column'] + [data-type='column']::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: -28.5px;
  width: 1px;
  background: var(--border);
  pointer-events: none;
}
.rte-doc [data-type='column'] > *:first-child {
  margin-top: 0;
}
.rte-doc [data-type='column'] > *:last-child {
  margin-bottom: 0;
}
@media (max-width: 640px) {
  .rte-doc [data-type='columns'] {
    grid-template-columns: 1fr !important;
  }
  .rte-doc [data-type='column'] + [data-type='column']::before {
    display: none;
  }
}

/* a row of pictures (32243:108985): cells 16 apart with no rule between
   them, and every picture fills the cell it is given without stretching */
.rte-doc [data-type='columns'][data-media='true'] {
  gap: 16px;
}
.rte-doc
  [data-type='columns'][data-media='true']
  [data-type='column']
  + [data-type='column']::before {
  display: none;
}
.rte-doc [data-type='columns'][data-media='true'] img {
  width: 100%;
  aspect-ratio: 342 / 170;
  object-fit: cover;
  border-radius: 6px;
  margin: 0;
}
.rte-doc [data-type='columns'][data-media='true'] [data-type='column'] > p {
  margin: 0;
}
/* two pictures in one cell (one duplicated, or dropped onto another) stand
   as far apart as the cells do (the row's 16px gap), so a grid of them is
   even both ways: each is its own block here, not a paragraph's picture */
.rte-doc [data-type='columns'][data-media='true'] [data-type='column'] > * + * {
  margin-top: 16px;
}
.rte-doc [data-type='columns'][data-media='true'] .ProseMirror-trailingBreak {
  display: none;
}

/* ---- expand / collapse: a 16px chevron before the summary, the content
   indented under it and folded away when closed ---- */
.rte-details {
  position: relative;
  padding-left: 22px;
  margin: 2px 0;
}
.rte-details-toggle {
  position: absolute;
  left: 0;
  top: 4px;
  display: flex;
  width: 16px;
  height: 16px;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  color: var(--muted-foreground);
  transition:
    transform 150ms ease-out,
    background-color 150ms;
}
.rte-details-toggle:hover {
  background: var(--secondary);
}
/* a toggle's own chevron and body only: a toggle closed inside an open one
   stays closed */
.rte-details.is-open > .rte-details-toggle {
  transform: rotate(90deg);
}
.rte-details.ProseMirror-selectednode {
  border-radius: 6px;
  box-shadow: 0 0 0 2px var(--border);
  background-color: transparent;
}
.rte-details summary {
  list-style: none;
  font-weight: 500;
  color: var(--foreground);
  cursor: text;
}
/* a checklist's tick, as the library checkbox (ui/checkbox) draws it: its
   glyph at 12px in the primary's ink, wiped in from the left over 200ms as
   the box is checked, gone at once as it is cleared. Drawn on the label,
   over the box: the input itself takes no pseudo-element everywhere */
.rte-doc ul[data-type='taskList'] > li > label::after {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 16px;
  height: 16px;
  margin-top: -8px;
  pointer-events: none;
  background-color: var(--primary-foreground);
  -webkit-mask: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 10 10'%3E%3Cpath fill='black' d='M8.03488 1.99125C8.2154 1.78244 8.53103 1.76003 8.73996 1.94047C8.94881 2.12099 8.97216 2.43661 8.79172 2.64555L4.15988 8.00785C4.0661 8.11645 3.9303 8.18018 3.78683 8.18168C3.64331 8.18315 3.50589 8.12235 3.40988 8.01567L1.21554 5.57817C1.03111 5.373 1.04775 5.05681 1.25265 4.87211C1.45791 4.68738 1.77496 4.70397 1.95968 4.90922L3.77316 6.92485L8.03488 1.99125Z'/%3E%3C/svg%3E") center / 12px 12px no-repeat;
  mask: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 10 10'%3E%3Cpath fill='black' d='M8.03488 1.99125C8.2154 1.78244 8.53103 1.76003 8.73996 1.94047C8.94881 2.12099 8.97216 2.43661 8.79172 2.64555L4.15988 8.00785C4.0661 8.11645 3.9303 8.18018 3.78683 8.18168C3.64331 8.18315 3.50589 8.12235 3.40988 8.01567L1.21554 5.57817C1.03111 5.373 1.04775 5.05681 1.25265 4.87211C1.45791 4.68738 1.77496 4.70397 1.95968 4.90922L3.77316 6.92485L8.03488 1.99125Z'/%3E%3C/svg%3E") center / 12px 12px no-repeat;
  clip-path: inset(0 100% 0 0);
}
.rte-doc ul[data-type='taskList'] > li > label:has(input:checked)::after {
  clip-path: inset(0 0 0 0);
  transition: clip-path 200ms ease-out;
}
/* a bullet list's dots stand back from the words they mark */
.rte-doc ul:not([data-type='taskList']) > li::marker {
  color: var(--muted-foreground);
}
.rte-details summary::-webkit-details-marker {
  display: none;
}
/* the fold opens and closes smoothly, in CSS alone: the body is a two-row
   grid (summary, content) whose content row eases between 0fr and 1fr, the
   one height a browser will animate to and from its content's own. Closed,
   the content is also made invisible once folded, so the caret and the
   keys pass it by as they did when it was not drawn at all */
.rte-details-body {
  display: grid;
  grid-template-rows: auto 0fr;
  transition: grid-template-rows 220ms cubic-bezier(0.2, 0, 0, 1);
}
.rte-details.is-open > .rte-details-body {
  grid-template-rows: auto 1fr;
}
.rte-details > .rte-details-body > [data-type='details-content'] {
  min-height: 0;
  overflow: hidden;
  /* room inside the clip for what draws past a block's edge (a chosen
     picture's ring, a list's numbers), given back by the margin */
  margin: -8px;
  padding: 8px;
  color: var(--secondary-foreground);
  opacity: 0;
  visibility: hidden;
  transition:
    padding-top 220ms cubic-bezier(0.2, 0, 0, 1),
    opacity 160ms ease-out,
    visibility 0s linear 220ms;
}
.rte-details.is-open > .rte-details-body > [data-type='details-content'] {
  padding-top: 12px;
  opacity: 1;
  visibility: visible;
  transition:
    padding-top 220ms cubic-bezier(0.2, 0, 0, 1),
    opacity 200ms ease-in 40ms,
    visibility 0s;
}
@media (prefers-reduced-motion: reduce) {
  .rte-details-body,
  .rte-details > .rte-details-body > [data-type='details-content'] {
    transition: none;
  }
}
/* an empty toggle says what it is, as Notion's does — in the editor's own
   placeholder gray, gone the moment there is text. Not in read mode. */
.rte:not(.is-readonly)
  .rte-details
  summary:has(> .ProseMirror-trailingBreak:only-child)::before {
  content: 'Toggle';
  font-weight: 400;
}
.rte:not(.is-readonly)
  .rte-details
  [data-type='details-content']
  > p:only-child:has(> .ProseMirror-trailingBreak:only-child)::before {
  content: 'Empty toggle. Click or drop blocks inside.';
}
/* both on one line over the empty one, cut short with an ellipsis where
   the toggle is narrow — laid over it, so the caret keeps its place */
.rte:not(.is-readonly)
  .rte-details
  summary:has(> .ProseMirror-trailingBreak:only-child),
.rte:not(.is-readonly)
  .rte-details
  [data-type='details-content']
  > p:only-child:has(> .ProseMirror-trailingBreak:only-child) {
  position: relative;
}
.rte:not(.is-readonly)
  .rte-details
  summary:has(> .ProseMirror-trailingBreak:only-child)::before,
.rte:not(.is-readonly)
  .rte-details
  [data-type='details-content']
  > p:only-child:has(> .ProseMirror-trailingBreak:only-child)::before {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  padding: inherit;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--card-foreground);
  pointer-events: none;
}

/* ---- the attachment row (31457:33634): the close shown while the pointer
   is on the row, and rows stacked close ---- */
.rte-doc .node-attachment {
  margin: 8px 0;
}
/* rows stacked close: the next row sits right on the last */
.rte-doc .node-attachment + .node-attachment {
  margin-top: -8px;
}
.rte-doc .rte-attachment > a {
  text-decoration: none;
  font-weight: 400;
}
.rte-attachment .rte-attachment-close {
  margin-left: auto;
  opacity: 0;
  transition: opacity 120ms ease-out;
}
.rte-attachment:hover .rte-attachment-close,
.rte-attachment:focus-within .rte-attachment-close {
  opacity: 1;
}
/* a selected row is its button on the same gray-100 ground as under the
   pointer — the same width and corners — not the block's wider halo */
.rte-doc .rte-attachment.ProseMirror-selectednode {
  background-color: transparent;
  box-shadow: none;
}
.rte-attachment.ProseMirror-selectednode > a {
  background-color: var(--secondary);
}

/* ---- sub- and superscript ---- */
.rte-doc sup,
.rte-doc sub {
  font-size: 0.75em;
  line-height: 0;
}

/* ---- tables (32157:9144): a 12px-radius card on a gray-100 hairline,
   cells ruled right and beneath — never on the outer edge — 6/8 in; the
   header row 32px of 13/15 gray-500, body rows 40px of 14/21 gray-600 that
   grow with their lines. The card is the table's viewport. ---- */
.rte-doc .tableWrapper {
  --rte-sbar: 9px;
  position: relative;
  border: 1px solid var(--border-soft);
  border-radius: 12px;
  margin: 16px 0;
  overflow-x: auto;
  /* the card never scrolls its rows: it is as tall as they are */
  overflow-y: hidden;
  container-type: scroll-state;
}
/* the card's scrollbar (32179:58872): a 4px gray-200 pill 5px up from the
   card's bottom edge, on no track, the card's inner width */
@supports not selector(::-webkit-scrollbar) {
  .rte-doc .tableWrapper {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }
}
.rte-doc .tableWrapper::-webkit-scrollbar {
  height: var(--rte-sbar);
}
.rte-doc .tableWrapper::-webkit-scrollbar-track {
  background: transparent;
}
.rte-doc .tableWrapper::-webkit-scrollbar-thumb {
  background: var(--border);
  background-clip: padding-box;
  border: 0 solid transparent;
  border-bottom-width: 5px;
  border-radius: 2px / 2px 2px 7px 7px;
}
.rte-doc table {
  margin: 0;
  width: 100%;
  min-width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 14px;
  line-height: 21px;
}
@container scroll-state(scrollable: x) {
  .rte-doc table {
    margin-bottom: calc(-1 * var(--rte-sbar));
  }
}
.rte-doc table td,
.rte-doc table th {
  position: relative;
  height: 40px;
  min-width: 48px;
  /* a 21px line stands where the centred one did in the 40px row, and a
     cell of many lines starts level with its neighbours, as Notion's do */
  padding: 9.5px 8px;
  border: 0;
  border-right: 1px solid var(--border-soft);
  border-bottom: 1px solid var(--border-soft);
  vertical-align: top;
  text-align: left;
  background: transparent;
}
.rte-doc table tr > :last-child {
  border-right: 0;
}
.rte-doc table tr:last-child > * {
  border-bottom: 0;
}
/* the header row stands as tall as any other row (40px): its smaller
   label keeps the body's 21px line */
.rte-doc table th {
  height: 40px;
  font-weight: 400;
}
.rte-doc table td p {
  font-size: 14px;
  line-height: 21px;
  margin: 0;
  color: var(--muted-foreground);
}
.rte-doc table th p {
  font-size: 13px;
  line-height: 21px;
  margin: 0;
  color: var(--accent-foreground);
}
/* a cell's first block starts at its top and its last ends at its bottom:
   a heading's, a list's, a quote's, a code block's or a picture's own
   margin (the picture's and the player's on the figure inside its block)
   is the page's, not the cell's */
.rte-doc .ProseMirror :is(td, th) > :first-child,
.rte-doc .ProseMirror :is(td, th) > :first-child > :is(.rte-figure, .rte-media, .rte-player) {
  margin-top: 0;
}
/* (the column's resize handle, set into a cell while its border is
   hovered, is never the cell's last block: counting it would hand the
   block before it its margin back, and the row would grow under the
   pointer) */
.rte-doc .ProseMirror :is(td, th) > :last-child:not(.column-resize-handle),
.rte-doc .ProseMirror :is(td, th) > :has(+ .column-resize-handle:last-child),
.rte-doc .ProseMirror :is(td, th) > :last-child > :is(.rte-figure, .rte-media, .rte-player),
.rte-doc
  .ProseMirror
  :is(td, th)
  > :has(+ .column-resize-handle:last-child)
  > :is(.rte-figure, .rte-media, .rte-player) {
  margin-bottom: 0;
}
/* a picture in a cell is a thumbnail: a table's columns grow to their
   content, so the picture's own width (its file's, 1000px and more) would
   widen its column past the page. Capped here, smaller sizes still hold */
.rte-doc .ProseMirror :is(td, th) .rte-media > [style*='width'],
.rte-doc .ProseMirror :is(td, th) .rte-media img {
  max-width: 280px !important;
}
.rte-doc .ProseMirror :is(td, th) .rte-media img {
  height: auto;
}
/* set as the cell's words are: from its left, a line's gap from them */
.rte-doc .ProseMirror :is(td, th) .rte-media {
  margin-top: 8px;
  margin-bottom: 8px;
  justify-content: flex-start;
}
.rte-doc .ProseMirror :is(td, th) .rte-media > [style*='width'] {
  margin-left: 0;
  margin-right: auto;
}
/* a to-do in a cell: the box on the cell's 21px line, level with its
   words (the cell takes the words' own margin away, so the box's goes
   too), and starting where a cell's text starts */
.rte-doc .ProseMirror :is(td, th) ul[data-type='taskList'] > li {
  padding-left: 0;
}
.rte-doc .ProseMirror :is(td, th) ul[data-type='taskList'] > li > label {
  margin-top: 0;
  height: 21px;
}
/* the row's border option: one rule, or none */
.rte-doc table tr[data-border] > * {
  border-right: 0;
  border-bottom: 0;
}
.rte-doc table tr[data-border='top'] > * {
  border-top: 1px solid var(--border-soft);
}
.rte-doc table tr[data-border='right'] > * {
  border-right: 1px solid var(--border-soft);
}
.rte-doc table tr[data-border='bottom'] > * {
  border-bottom: 1px solid var(--border-soft);
}
.rte-doc table tr[data-border='left'] > * {
  border-left: 1px solid var(--border-soft);
}
${cellTintRules}

/* ---- a block picked up by its grip, or selected by a click on it: a
   gray-100 ground 4px past its edges. A picture, the player and the
   attachment row keep their own chrome instead: the selected node there
   is the view's wrapper, full column wide, and the wash would slab far
   past the media's own box ---- */
.rte-doc
  .ProseMirror-selectednode:not(img):not(video):not(
    :has(> .rte-media),
    :has(> .rte-player),
    :has(> .rte-attachment)
  ) {
  background-color: var(--secondary);
  border-radius: 4px;
  box-shadow: 0 0 0 4px var(--secondary);
}
.rte-doc.rte-dragging .ProseMirror-selectednode:not(img):not(video) {
  opacity: 0.4;
}
/* a selected row is its button on the gray ground, not the block's halo */
.rte-doc .ProseMirror-selectednode > .rte-attachment > a {
  background-color: var(--secondary);
}

/* ---- the table selection: a 1px gray-500 line around the cell or the run
   of cells; at the card's corners it turns on the card's inner 11px radius ---- */
.rte-doc .selectedCell::after {
  content: '';
  position: absolute;
  pointer-events: none;
  z-index: 2;
  border-radius: 0;
  box-shadow: inset 0 0 0 1px var(--accent-foreground);
}
/* a run of cells is one ring (the overlay's box), not a ring per cell: the
   overlay marks the editor element itself, inside .rte-doc */
.rte-doc .ProseMirror.table-cell-range .selectedCell::after {
  box-shadow: none;
}
.rte-doc .table-selection-box {
  position: absolute;
  pointer-events: none;
  z-index: 3;
  border-radius: 0;
  box-sizing: content-box;
  box-shadow: inset 0 0 0 1px var(--accent-foreground);
}
/* the cell's ring lies on the rules around it; on the card's edge, where
   there is no rule and the card would clip it, it stays on the cell's own
   edge */
.rte-doc .selectedCell::after {
  inset: -1px;
}
.rte-doc table tr > :first-child.selectedCell::after {
  left: 0;
}
.rte-doc table tr:first-child > .selectedCell::after {
  top: 0;
}
.rte-doc table tr > :last-child.selectedCell::after {
  right: 0;
}
.rte-doc table tr:last-child > .selectedCell::after {
  bottom: 0;
}
@container scroll-state(scrollable: x) {
  .rte-doc table tr:last-child > .selectedCell::after {
    bottom: var(--rte-sbar);
  }
}
.rte-doc table tr:first-child > :first-child.selectedCell::after {
  border-top-left-radius: 11px;
}
.rte-doc table tr:first-child > :last-child.selectedCell::after {
  border-top-right-radius: 11px;
}
.rte-doc table tr:last-child > :first-child.selectedCell::after {
  border-bottom-left-radius: 11px;
}
.rte-doc table tr:last-child > :last-child.selectedCell::after {
  border-bottom-right-radius: 11px;
}
/* tiptap's column resize handle: a 1px gray-600 line on the edge under the
   pointer, the cell's height, taken 1px past so each segment reaches the
   next, and lifted over the cells' own grounds */
.rte-doc .column-resize-handle {
  position: absolute;
  top: 0;
  bottom: -1px;
  right: -1px;
  width: 1px;
  background-color: var(--muted-foreground);
  pointer-events: none;
  z-index: 2;
}
.rte-doc table tr:last-child > * > .column-resize-handle {
  bottom: 0;
}
.rte-doc table tr > :last-child > .column-resize-handle {
  right: 0;
}
.rte-doc .ProseMirror.resize-cursor {
  cursor: col-resize;
}

/* ---- a comment's run: amber beneath, as the file marks it ---- */
.rte-comment {
  background: var(--color-amber-100);
  border-bottom: 1px solid var(--color-amber-500);
  cursor: pointer;
}
.dark .rte-comment {
  background: var(--color-amber-900);
}

/* the document's pictures keep the prose scale's 2em rhythm */
.rte-doc > img,
.rte-doc .rte-figure,
.rte-doc .rte-media,
.rte-doc [data-type='columns'][data-media='true'] {
  margin-top: 2em;
  margin-bottom: 2em;
}
.rte-doc .rte-figure > img,
.rte-doc .rte-media img {
  margin: 0;
}
/* in a column a picture is the cell's own block: the first one stands at
   the column's top with its neighbours (a slot, a line of text), the last
   one ends it, as any first and last block in a column does */
.rte-doc [data-type='column'] > :first-child:is(.rte-figure, .rte-media, img),
.rte-doc [data-type='column'] > :first-child > :is(.rte-figure, .rte-media, .rte-player) {
  margin-top: 0;
}
.rte-doc [data-type='column'] > :last-child:is(.rte-figure, .rte-media, img),
.rte-doc [data-type='column'] > :last-child > :is(.rte-figure, .rte-media, .rte-player) {
  margin-bottom: 0;
}
/* a cell's picture fills its cell until it is resized; a resized one
   keeps its width (never wider than the cell) and the ring hugs it */
.rte-doc [data-type='columns'][data-media='true'] .rte-media {
  width: 100%;
  margin: 0;
}
.rte-doc [data-type='columns'][data-media='true'] .rte-media > div {
  /* top and bottom only: the sides are the picture's alignment in its cell */
  margin-top: 0;
  margin-bottom: 0;
  max-width: 100%;
}
.rte-doc [data-type='columns'][data-media='true'] .rte-media > div:not([data-sized]) {
  width: 100% !important;
}

/* in a column of a layout, a picture not resized fills the column's width,
   however narrow its file; one resized keeps the width it was given */
.rte-doc [data-type='column'] .rte-media > div:not([data-sized]),
.rte-doc [data-type='column'] .rte-media > div:not([data-sized]) img {
  width: 100% !important;
}

/* a picture or an embed being resized: the drag's cursor everywhere */
body.rte-media-resizing,
body.rte-media-resizing * {
  cursor: ew-resize !important;
}
/* a live player (an embed's frame is its own page) would take the drag's
   moves as they pass over it, and the size would stop following */
body.rte-media-resizing iframe,
body.rte-media-resizing video {
  pointer-events: none !important;
}

/* a caption under a frame: 14px gray-500, centred 8px below */
.rte-doc .rte-media-caption {
  margin-top: 8px;
  text-align: center;
  font-size: 14px;
  line-height: 21px;
  color: var(--accent-foreground);
}

/* an embed and the players keep the column */
.rte-doc iframe {
  max-width: 100%;
}

/* read only: the document as it is, no caret */
.rte.is-readonly .ProseMirror {
  caret-color: transparent;
}

/* ================= the table's controls (RteTableControls) ================ */
/* a handle: a 3×14 gray-500 pill on full corners under a 2px white stroke,
   straddling the edge's line. Hovered or open it is the file's grip: a
   10×20 (20×10) gray-500 pill on 4px corners with three 3px white dots */
.rte-tc-handle {
  position: fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  border-radius: 4px;
  border: 1px solid transparent;
  transition: background-color 150ms;
  overflow: visible;
  cursor: grab;
  touch-action: none;
}
.rte-tc-handle.is-cell {
  cursor: pointer;
}
.rte-tc-anchor {
  position: fixed;
  pointer-events: none;
}
body.rte-tc-dragging,
body.rte-tc-dragging .rte-tc-handle {
  cursor: grabbing;
  user-select: none;
}
.rte-tc-drop {
  position: fixed;
  z-index: 75;
  border-radius: 9999px;
  pointer-events: none;
  background-color: var(--border-stronger);
  opacity: 0;
  transition:
    top 120ms cubic-bezier(0.2, 0, 0, 1),
    left 120ms cubic-bezier(0.2, 0, 0, 1),
    opacity 120ms;
}
.rte-tc-drop.is-on {
  opacity: 1;
}
/* the ghost: the row or column lifted, on the card's surface under the lg
   shadow, fading up as it rises and down as it lands */
.rte-tc-ghost {
  position: fixed;
  z-index: 70;
  pointer-events: none;
  overflow: hidden;
  border-radius: 6px;
  background-color: var(--card);
  box-shadow: var(--shadow-elevation-lg, 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1));
  opacity: 0;
  transition: opacity 140ms;
  will-change: transform;
}
.rte-tc-ghost.is-up {
  opacity: 0.85;
}
.rte-tc-ghost table {
  margin: 0;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 14px;
  line-height: 21px;
}
.rte-tc-ghost td,
.rte-tc-ghost th {
  height: 40px;
  padding: 6px 8px;
  border: 0;
  border-right: 1px solid var(--border-soft);
  border-bottom: 1px solid var(--border-soft);
  vertical-align: middle;
  text-align: left;
  background: transparent;
}
.rte-tc-ghost th {
  height: 32px;
  font-weight: 400;
}
.rte-tc-ghost td p {
  font-size: 14px;
  line-height: 21px;
  margin: 0;
  color: var(--muted-foreground);
}
.rte-tc-ghost th p {
  font-size: 13px;
  line-height: 15px;
  margin: 0;
  color: var(--accent-foreground);
}
.rte-tc-ghost tr > :last-child {
  border-right: 0;
}
.rte-tc-ghost tr:last-child > * {
  border-bottom: 0;
}
@media (prefers-reduced-motion: reduce) {
  .rte-tc-drop,
  .rte-tc-ghost {
    transition: none;
  }
}
.rte-tc-handle.is-row {
  width: 10px;
  height: 20px;
}
.rte-tc-handle.is-col {
  width: 20px;
  height: 10px;
}
.rte-tc-pill {
  position: absolute;
  display: block;
  border-radius: 9999px;
  background-color: var(--accent-foreground);
  /* the gaps either side are the editor's own ground */
  box-shadow: 0 0 0 2px var(--background);
}
/* on the table's edge the dash is drawn by .rte-tc-edge, not the pill */
.rte-tc-handle.is-row:not(.is-cell) .rte-tc-pill,
.rte-tc-handle.is-col .rte-tc-pill {
  display: none;
}
/* the edge's dash: a 1px gray-500 length of the table's rule — the
   selection's own colour — laid on the wrapper's own edge with the
   wrapper's own 1px border, so it lands on the rule's device pixels at any
   zoom, or a pixel in, on the ring, where the ring runs along that edge */
.rte-tc-edge {
  position: fixed;
  pointer-events: none;
  box-shadow: 0 0 0 2px var(--background);
}
.rte-tc-edge.is-row {
  width: 0;
  height: 14px;
  border-left: 1px solid var(--accent-foreground);
}
.rte-tc-edge.is-col {
  width: 14px;
  height: 0;
  border-top: 1px solid var(--accent-foreground);
}
.rte-tc-handle:hover + .rte-tc-edge,
.rte-tc-handle.is-open + .rte-tc-edge {
  display: none;
}
.rte-tc-handle.is-row .rte-tc-pill {
  left: 3px;
  top: 2px;
  width: 1px;
  height: 14px;
}
/* the cell's handle on the selection's ring is, like the edge's, a 1px
   length of that ring */
.rte-tc-handle.is-row.is-cell .rte-tc-pill {
  left: 4px;
  width: 1px;
  background-color: var(--accent-foreground);
}
.rte-tc-dots {
  position: absolute;
  inset: -1px;
  display: none;
}
.rte-tc-handle.is-row .rte-tc-dots {
  background-image:
    radial-gradient(circle at 5px 5px, #fff 1.5px, transparent 1.75px),
    radial-gradient(circle at 5px 10px, #fff 1.5px, transparent 1.75px),
    radial-gradient(circle at 5px 15px, #fff 1.5px, transparent 1.75px);
}
.rte-tc-handle.is-col .rte-tc-dots {
  background-image:
    radial-gradient(circle at 5px 5px, #fff 1.5px, transparent 1.75px),
    radial-gradient(circle at 10px 5px, #fff 1.5px, transparent 1.75px),
    radial-gradient(circle at 15px 5px, #fff 1.5px, transparent 1.75px);
}
.rte-tc-handle:hover,
.rte-tc-handle.is-open {
  background-color: var(--accent-foreground);
}
.rte-tc-handle:hover .rte-tc-pill,
.rte-tc-handle.is-open .rte-tc-pill {
  display: none;
}
.rte-tc-handle:hover .rte-tc-dots,
.rte-tc-handle.is-open .rte-tc-dots {
  display: block;
}
/* a strip: the plus alone, gray-400 over the page, darkening under the
   pointer — the glyph is the whole control */
.rte-tc-strip {
  position: fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  color: var(--card-foreground);
  transition: color 150ms;
}
.rte-tc-strip:hover {
  color: var(--muted-foreground);
}
/* the Colour submenu: Default and the palette, 24px on 8px corners — six
   24px columns spread edge to edge */
.rte-tc-swatches {
  display: grid;
  gap: 6px;
  padding: 4px;
  grid-template-columns: repeat(6, 24px);
  justify-content: space-between;
}
.rte-tc-swatch {
  display: flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  border: 1px solid var(--border);
  font-size: 14px;
  line-height: 1;
  color: var(--secondary-foreground);
  transition: box-shadow 150ms;
  background-color: var(--sw, transparent);
}
.rte-tc-swatch:hover {
  box-shadow: 0 0 0 2px var(--border-normal);
}
.dark .rte-tc-swatch {
  background-color: var(--sw-dark, transparent);
}

/* ================= the comment thread card ================ */
/* the header's rule is drawn inside its 32px, as the file's inside stroke
   is, and its controls are 24px on an 8px radius */
.rte-thread-head {
  box-shadow: inset 0 -1px 0 var(--border-soft);
}
.rte-thread-btn {
  display: flex;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: var(--accent-foreground);
  transition: background-color 150ms, color 150ms;
}
.rte-thread-btn:hover {
  background-color: var(--secondary);
  color: var(--secondary-foreground);
}

/* ================= the toolbar (RichTextToolbar) ================ */
/* a plain control: 28px, the glyph centred; pressed or open on gray-100 */
.rte-btn {
  display: flex;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: var(--secondary-foreground);
  transition: background-color 150ms;
}
.rte-btn:hover {
  background-color: var(--secondary);
}
.rte-btn:disabled {
  opacity: 0.4;
}
.rte-btn:disabled:hover {
  background-color: transparent;
}
.rte-btn[aria-pressed='true'],
.rte-btn.is-open,
.rte-btn[data-popup-open] {
  background-color: var(--muted);
}
/* a select: its glyph or word, 4px, the chevron; 8px in either side */
.rte-select {
  display: flex;
  height: 28px;
  flex-shrink: 0;
  align-items: center;
  gap: 4px;
  border-radius: 8px;
  padding: 0 8px;
  color: var(--secondary-foreground);
  transition: background-color 150ms;
}
.rte-select:hover {
  background-color: var(--secondary);
}
.rte-select.is-open,
.rte-select[data-popup-open] {
  background-color: var(--muted);
}
/* the colour select is tighter: 2px around its 24px glyph box, which is
   the file's outline button — ruled in outline-gray-2, darker under the
   pointer — while the frame around it takes no fill of its own */
.rte-select-tight,
.rte-select-tight.is-open,
.rte-select-tight[data-popup-open] {
  gap: 2px;
  background-color: transparent;
  padding: 0 2px;
}
.rte-select-tight:hover {
  background-color: transparent;
}
.rte-select-tight > :first-child {
  display: flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  border: 1px solid var(--border);
  transition: border-color 150ms;
}
.rte-select-tight:hover > :first-child,
.rte-select-tight.is-open > :first-child,
.rte-select-tight[data-popup-open] > :first-child {
  border-color: var(--border-normal);
}
/* the size stepper's − and +: 24px on gray-100 */
.rte-step {
  display: flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background-color: var(--secondary);
  color: var(--secondary-foreground);
  transition: background-color 150ms;
}
.rte-step:hover {
  background-color: var(--muted);
}
.rte-tb-divider {
  margin: 0 4px;
  height: 20px;
  width: 1px;
  flex-shrink: 0;
  background-color: var(--muted);
}

/* ================= the floating bar (RteBubbleMenu) ================ */
.rte-bubble {
  display: flex;
  height: 28px;
  align-items: center;
  border-radius: 10px;
  background-color: var(--card);
  padding: 2px;
  box-shadow: var(--shadow-elevation-md, 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1));
}
/* the select: at least 100×24, 6/4 in, the label and chevron 4 apart on a
   6px radius; filled gray-100 under the pointer and while its menu is open */
.rte-bubble-select {
  display: flex;
  height: 24px;
  min-width: 100px;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  border-radius: 6px;
  padding: 4px 4px 4px 6px;
  color: var(--secondary-foreground);
  transition: background-color 150ms;
}
.rte-bubble-select:hover,
.rte-bubble-select.is-open,
.rte-bubble-select[data-popup-open] {
  background-color: var(--secondary);
}
.rte-bubble-btn {
  display: flex;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: var(--secondary-foreground);
  transition: background-color 150ms;
}
.rte-bubble-btn:hover,
.rte-bubble-btn[aria-pressed='true'],
.rte-bubble-btn.is-open,
.rte-bubble-btn[data-popup-open] {
  background-color: var(--secondary);
}
/* a 9px slot: 4, the hairline, 4 */
.rte-bubble-divider {
  margin: 0 4px;
  height: 16px;
  width: 1px;
  flex-shrink: 0;
  background-color: var(--border-soft);
}

/* ================= the block grip (RteBlockHandle) ================ */
/* the grip: 16×24 on 4px corners, gray-400 dots that darken on a gray-100
   ground under the pointer */
.rte-bh-handle {
  pointer-events: auto;
  position: fixed;
  display: flex;
  height: 24px;
  width: 16px;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  color: var(--card-foreground);
  transition: background-color 150ms, color 150ms;
  cursor: grab;
}
.rte-bh-handle:hover {
  background-color: var(--secondary);
  color: var(--muted-foreground);
}
.rte-bh-handle:active {
  cursor: grabbing;
}
/* on a picture it is the media's own chrome: white dots on the 36% black
   overlay, darker under the pointer, one look in either theme */
.rte-bh-handle.is-on-media {
  background-color: rgb(0 0 0 / 0.36);
  color: #fff;
}
.rte-bh-handle.is-on-media:hover {
  background-color: rgb(0 0 0 / 0.48);
  color: #fff;
}
.rte-bh-handle.is-on-media:active {
  background-color: rgb(0 0 0 / 0.6);
}
/* a column block's grip, in the gutter between the hairline and its text:
   a size down, so it stands clear of both */
.rte-bh-handle.is-in-gutter {
  width: 12px;
  height: 20px;
  border-radius: 3px;
}
.rte-bh-handle.is-in-gutter svg {
  width: 12px;
  height: 12px;
}
/* out of sight, not out of the way: the browser ends a drag whose source
   stops taking pointer events */
.rte-bh-handle.is-dragging {
  opacity: 0;
}
/* the copy that follows the pointer: the block at half strength, and the
   line at the edge it would land on, 3px of gray-900 across the block */
.rte-bh-ghost {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 70;
  pointer-events: none;
  opacity: 0.5;
  will-change: transform;
}
.rte-bh-line {
  position: fixed;
  z-index: 65;
  height: 3px;
  border-radius: 9999px;
  pointer-events: none;
  background-color: var(--border-stronger);
}
/* beside: the vertical line at the edge the block would stand at */
.rte-bh-line.is-side {
  width: 3px;
}
/* the picture a swap would trade with, ringed as a selected picture is */
.rte-bh-line.is-swap {
  border-radius: 6px;
  background-color: transparent;
  box-shadow: 0 0 0 2px var(--border-stronger);
}
/* the blocks of a run while they are carried, as a carried block is */
.rte-doc .rte-bh-carried {
  opacity: 0.4;
}

/* ================= the slots (RteImageSlot / RteEmbedSlot) ================ */
/* the file's 700×36 row: surface-gray-1 on a 6px radius, 10px in, the 16px
   glyph and the 14px ink-gray-5 word 10px apart */
.rte-slot {
  margin: 8px 0;
}
.rte-slot-face {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 10px;
  padding: 10px;
  height: 36px;
  border-radius: 6px;
  background: var(--input);
  color: var(--accent-foreground);
  font-size: 14px;
  line-height: 16px;
  text-align: start;
}
.rte-slot-face:hover:not(:disabled),
.rte-slot-face.is-open {
  background: var(--secondary);
}
.rte-slot-face:disabled {
  cursor: default;
}
/* in a column the slot is the file's cell: the dashed outline holds the
   342 × 170 shape and the panel sits 8px inside it */
[data-type='column'] .rte-slot {
  margin: 0;
  border: 1px dashed var(--border-normal);
  border-radius: 6px;
  padding: 8px;
  aspect-ratio: 342 / 170;
}
[data-type='column'] .rte-slot .rte-slot-face {
  height: 100%;
  justify-content: center;
  border-radius: 6px;
}

/* ================= the column bar (RteColumnResizer) ================ */
/* the hand's target is 12px across the gap; the bar in it is 3px on full
   corners, gray-400, gray-600 under the pointer and while it drags */
.rte-cr {
  position: fixed;
  /* under the block grip (30), the table controls (40) and every menu
     (50): a column's grip stands on its gap and must take its own press */
  z-index: 25;
  display: flex;
  width: 12px;
  margin-left: -6px;
  justify-content: center;
  cursor: col-resize;
  touch-action: none;
}
.rte-cr-bar {
  width: 3px;
  height: 100%;
  border-radius: 9999px;
  background: var(--border-strong);
  transition: background-color 120ms;
}
.rte-cr:hover .rte-cr-bar,
.rte-cr.is-dragging .rte-cr-bar {
  background: var(--muted-foreground);
}
/* resting on an even split: the bar darkens so the settle is seen */
.rte-cr.is-snapped .rte-cr-bar {
  background: var(--foreground);
}
body.rte-col-drag {
  cursor: col-resize;
  user-select: none;
}

/* ================= the box selection (BlockMarquee) ================ */
/* Notion's blue: the box drawn faint with a hairline, each chosen block
   tinted on top of its own fill (an inset shadow paints above a block's
   background and under its content) and reaching 3px past its sides —
   not above or below, where two chosen blocks would overlap darker */
.rte {
  --rte-chosen: rgb(35 131 226 / 0.14);
}
.dark .rte {
  --rte-chosen: rgb(35 131 226 / 0.24);
}
.rte-marquee-box {
  position: fixed;
  z-index: 40;
  pointer-events: none;
  background: rgb(35 131 226 / 0.1);
  border: 1px solid rgb(35 131 226 / 0.35);
  border-radius: 2px;
}
body.rte-marquee {
  user-select: none;
  cursor: default;
}
/* while a box, a column bar or a block is dragged, an embedded page (a
   video, an embed) takes no pointer: the moves stay with the editor */
body.rte-marquee iframe,
body.rte-col-drag iframe,
body.rte-block-drag iframe {
  pointer-events: none;
}
body.rte-marquee .rte-bh-handle,
body.rte-marquee .rte-cr {
  display: none;
}
.ProseMirror .rte-block-chosen {
  border-radius: 4px;
  box-shadow:
    -3px 0 0 0 var(--rte-chosen),
    3px 0 0 0 var(--rte-chosen),
    inset 0 0 0 9999px var(--rte-chosen);
}
/* a chosen list item takes its marker in: the tint reaches back over the
   list's 24px of room for its bullet, number or box */
.ProseMirror li.rte-block-chosen {
  box-shadow:
    -24px 0 0 0 var(--rte-chosen),
    3px 0 0 0 var(--rte-chosen),
    inset 0 0 0 9999px var(--rte-chosen);
}
/* the caret waits unseen while blocks are chosen, and no text shows chosen */
.ProseMirror.has-chosen-blocks {
  caret-color: transparent;
}
.ProseMirror.has-chosen-blocks ::selection {
  background: transparent;
}

/* ================= the link card (RteLinkPanel) ================ */
/* the file keeps the field on gray-100 with no rule while it is edited */
.rte-link input:focus,
.rte-link input:hover {
  background-color: var(--secondary) !important;
  box-shadow: none !important;
}
.rte-link-shake {
  animation: rte-link-shake 160ms ease-in-out;
}
@keyframes rte-link-shake {
  0%,
  100% {
    transform: translateX(0);
  }
  25% {
    transform: translateX(-3px);
  }
  75% {
    transform: translateX(3px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .rte-link-shake {
    animation: none;
  }
}

/* ================= the colour card (RteColorPanel) ================ */
/* a swatch: the file's 24px outline button — white, ruled in the colour's
   tint, an 8px radius — and, for a background, filled with its wash */
.rte-swatch {
  --sw-ink: var(--foreground);
  --sw-line: var(--border);
  --sw-fill: var(--card);
  display: flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  border: 1px solid;
  background-color: var(--card);
  font-size: 14px;
  line-height: 1;
  transition: box-shadow 150ms;
  color: var(--sw-ink);
  border-color: var(--sw-line);
}
.rte-swatch-fill {
  background-color: var(--sw-fill);
}
.rte-swatch:hover,
.rte-swatch:focus-visible {
  box-shadow: 0 0 0 1px var(--sw-line);
  outline: none;
}
.rte-swatch[aria-pressed='true'] {
  box-shadow: 0 0 0 2px var(--border-normal);
}
.dark .rte-swatch {
  color: var(--sw-ink-dark, var(--sw-ink));
  border-color: var(--sw-line-dark, var(--sw-line));
}
.dark .rte-swatch-fill {
  background-color: var(--sw-fill-dark, var(--sw-fill));
}
`

