"use client"

// The link card (31823:54797, 31823:54816) over a link, and the
// `openLinkEditor` command that raises it over the selection (the
// toolbar's and the floating bar's Link buttons and ⌘K). A 36px card on a
// 12px radius, 4px in, under the xl shadow: the subtle input at 28px (the
// globe, 8, the address) and a 28px ghost button beside it. The address is
// always the one to change: a click in it edits, Enter keeps it, Escape
// leaves it. Over a link the button unlinks; a new link has none. Hovering
// a link raises the same card over it; a click on a link goes to its page.
import * as React from "react"
import { createRoot } from "react-dom/client"
import { Extension, getMarkRange, type Editor as TiptapEditor } from "@tiptap/core"
import { Plugin, PluginKey } from "@tiptap/pm/state"

import { cn } from "@/lib/utils"
import { Input } from "@/components/ui/input"
import {
  GlobeIcon,
  LinkBrokenIcon,
} from "@/components/ui/rich-text-editor-icons"

import { LINK_ON_KEY } from "./extensions"

const ALLOWED = /^(https?|mailto|tel):/i

const normalize = (raw: string) => {
  const trimmed = raw.trim()
  if (!trimmed) return ""
  if (/^[a-z][a-z0-9+.-]*:/i.test(trimmed)) return trimmed
  return `https://${trimmed}`
}

const isValid = (href: string) => {
  if (!ALLOWED.test(href)) return false
  let url: URL
  try {
    url = new URL(href)
  } catch {
    return false
  }
  if (url.protocol === "http:" || url.protocol === "https:")
    return url.hostname === "localhost" || url.hostname.includes(".")
  return true
}

export function LinkCard({
  href,
  autoFocus,
  onUpdateHref,
  onClose,
  onEngage,
}: {
  href: string
  /** the address takes the focus as the card opens (a card asked for) */
  autoFocus?: boolean
  onUpdateHref: (href: string) => void
  onClose: () => void
  /** the address is being edited: a hover card stays while it is */
  onEngage?: () => void
}) {
  const [value, setValue] = React.useState(href)
  const [shake, setShake] = React.useState(false)
  const inputRef = React.useRef<HTMLInputElement>(null)

  const submit = () => {
    const next = normalize(value)
    if (next === href) return onClose()
    if (next === "" || isValid(next)) onUpdateHref(next)
    else {
      setShake(false)
      requestAnimationFrame(() => setShake(true))
    }
  }

  React.useEffect(() => {
    if (!autoFocus) return
    requestAnimationFrame(() => {
      const el = inputRef.current
      if (!el) return
      // the card is placed a frame later; a plain focus would scroll to
      // wherever it sits meanwhile
      el.focus({ preventScroll: true })
      el.select()
    })
  }, [autoFocus])

  // Escape is the card's: it goes, the address as it was
  React.useEffect(() => {
    const onKeydown = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return
      e.preventDefault()
      e.stopPropagation()
      onClose()
    }
    document.addEventListener("keydown", onKeydown, true)
    return () => document.removeEventListener("keydown", onKeydown, true)
  }, [onClose])

  const ghostBtn =
    "flex size-7 shrink-0 items-center justify-center rounded-md text-secondary-foreground transition-colors hover:bg-secondary [&>svg]:size-4"

  return (
    <div
      className="rte-link flex items-center gap-1 rounded-xl bg-card p-1 shadow-elevation-xl"
      role="dialog"
      aria-label="Link"
    >
      <div
        className={cn("relative w-[276px]", shake && "rte-link-shake")}
        onAnimationEnd={() => setShake(false)}
      >
        <GlobeIcon className="pointer-events-none absolute top-1/2 left-2 size-4 -translate-y-1/2 text-secondary-foreground" />
        <Input
          ref={inputRef}
          size="sm"
          variant="subtle"
          className="w-full pl-8"
          placeholder="Paste or type a link"
          aria-label="Link address"
          value={value}
          onFocus={onEngage}
          onChange={(e) => {
            setValue(e.target.value)
            onEngage?.()
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault()
              submit()
            }
          }}
        />
      </div>
      {href ? (
        <button
          type="button"
          aria-label="Remove link"
          title="Remove link"
          className={ghostBtn}
          onClick={() => onUpdateHref("")}
        >
          <LinkBrokenIcon />
        </button>
      ) : null}
    </div>
  )
}

type Range = { from: number; to: number }

/** the range carried through the live document */
function mapRange(editor: TiptapEditor, range: Range): Range {
  const size = editor.state.doc.content.size
  return {
    from: Math.min(range.from, size),
    to: Math.min(range.to, size),
  }
}

function selectionRect(editor: TiptapEditor, range: Range): DOMRect {
  const { from, to } = mapRange(editor, range)
  const start = editor.view.coordsAtPos(from)
  const end = editor.view.coordsAtPos(to)
  const top = Math.min(start.top, end.top)
  const bottom = Math.max(start.bottom, end.bottom)
  const left = Math.min(start.left, end.left)
  const right = Math.max(start.right, end.right)
  return new DOMRect(left, top, Math.max(right - left, 0), bottom - top)
}

type LinkPopup = {
  /** the address to set, `''` to unlink, or `null` when the card was left */
  done: Promise<string | null>
  close: () => void
  /** the card's box, for a hover's way across to it */
  host: HTMLElement
  /** the address has been taken up: a hover card no longer leaves by itself */
  engaged: () => boolean
}

/**
 * The card over `range`, placed above it (below when there is no room).
 * Asked for (the Link button, ⌘K) it takes the focus; raised by a hover it
 * waits to be clicked into. Never rejects.
 */
function openLinkPopup(args: {
  editor: TiptapEditor
  href: string | null
  autoFocus: boolean
  range: Range
}): LinkPopup {
  const { editor } = args
  let settled = false
  let engaged = args.autoFocus
  let resolve: (value: string | null) => void = () => {}
  const done = new Promise<string | null>((r) => (resolve = r))
  const host = document.createElement("div")
  host.className = "fixed z-70"
  document.body.appendChild(host)
  const root = createRoot(host)

  const ground = (on: boolean) => {
    if (editor.isDestroyed) return
    const range = on ? mapRange(editor, args.range) : null
    editor.view.dispatch(editor.state.tr.setMeta(LINK_ON_KEY, range))
  }
  const settle = (value: string | null) => {
    if (settled) return
    settled = true
    ground(false)
    document.removeEventListener("pointerdown", onDown, true)
    window.removeEventListener("scroll", position, true)
    window.removeEventListener("resize", position)
    root.unmount()
    host.remove()
    resolve(value)
  }
  const onDown = (e: PointerEvent) => {
    if (e.target instanceof Node && host.contains(e.target)) return
    settle(null)
  }
  const position = () => {
    if (settled || editor.isDestroyed) return
    try {
      const rect = selectionRect(editor, args.range)
      const box = host.firstElementChild?.getBoundingClientRect()
      const height = box?.height ?? 36
      const above = rect.top - 8 - height
      host.style.left = `${Math.max(8, rect.left)}px`
      host.style.top = `${above >= 8 ? above : rect.bottom + 8}px`
    } catch {
      // the document moved out from underneath; keep the last place
    }
  }
  document.addEventListener("pointerdown", onDown, true)
  window.addEventListener("scroll", position, true)
  window.addEventListener("resize", position)
  ground(true)

  root.render(
    <LinkCard
      href={args.href ?? ""}
      autoFocus={args.autoFocus}
      onEngage={() => (engaged = true)}
      onUpdateHref={(href) => settle(href)}
      onClose={() => {
        const asked = args.autoFocus
        settle(null)
        if (asked && !editor.isDestroyed)
          editor.commands.focus(undefined, { scrollIntoView: false })
      }}
    />
  )
  position()
  requestAnimationFrame(position)
  return { done, close: () => settle(null), host, engaged: () => engaged }
}

/** `''` unlinks; an address sets it. Stored marks go, so typing on is plain. */
function applyLink(editor: TiptapEditor, stored: Range, href: string): void {
  const { from, to } = mapRange(editor, stored)
  const chain = editor.chain().focus(undefined, { scrollIntoView: false })
  if (href === "") {
    chain
      .setTextSelection({ from, to })
      .unsetLink()
      .command(({ tr }) => {
        tr.setStoredMarks([])
        return true
      })
      .run()
    return
  }
  chain
    .setTextSelection({ from, to })
    .setLink({ href })
    .setTextSelection(to)
    .command(({ tr }) => {
      tr.setStoredMarks([])
      return true
    })
    .run()
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    rteLinkEditor: {
      /** raise the link card over the selection, or the link the caret is in */
      openLinkEditor: () => ReturnType
    }
  }
}

export const LinkEditor = Extension.create({
  name: "rteLinkEditor",
  addCommands() {
    return {
      openLinkEditor:
        () =>
        ({ editor }) => {
          const { state } = editor
          const markType = state.schema.marks.link
          if (!markType) return false
          const { from, to } = state.selection

          let range: Range
          let delay = false
          if (from === to) {
            // a caret in a link: the whole link, and the card once its
            // selection has painted
            const markRange = getMarkRange(state.selection.$from, markType)
            if (!markRange) return false
            range = { from: markRange.from, to: markRange.to }
            editor.chain().setTextSelection(range).run()
            delay = true
          } else {
            range = { from, to }
          }

          const existing =
            (editor.getAttributes("link").href as string | undefined) || null

          const show = () => {
            void openLinkPopup({ editor, href: existing, autoFocus: true, range })
              .done.then((href) => {
                if (href === null || editor.isDestroyed) return
                applyLink(editor, range, href)
              })
          }
          if (delay) requestAnimationFrame(show)
          else show()
          return true
        },
    }
  },
  addKeyboardShortcuts() {
    return {
      "Mod-k": () => this.editor.commands.openLinkEditor(),
    }
  },
})

/** how long the pointer rests on a link before its card comes */
const HOVER_OPEN = 350
/** how long the card waits once the pointer has left link and card both */
const HOVER_CLOSE = 250

/**
 * A link in the document, edited in place.
 *
 * A click goes to its page, in a new tab, through the editor's own click
 * handling (ProseMirror calls it on a real click, no drag), not the raw
 * DOM click a contenteditable can swallow. Read-only, the browser follows
 * the link itself.
 *
 * A hover raises the link card over the link: the address to change and
 * the button that unlinks. It leaves as the pointer leaves link and card
 * both, unless the address has been taken up. With text selected the
 * selection's own bar is the one up, and no card comes over it.
 */
export function LinkClickCard({ editor }: { editor: TiptapEditor }) {
  React.useEffect(() => {
    if (editor.isDestroyed) return
    const view = editor.view
    let card: (LinkPopup & { link: Element }) | null = null
    let openTimer: ReturnType<typeof setTimeout> | undefined
    let closeTimer: ReturnType<typeof setTimeout> | undefined
    let pending: Element | null = null

    const closeCard = () => {
      clearTimeout(closeTimer)
      card?.close()
      card = null
    }
    const scheduleClose = () => {
      clearTimeout(closeTimer)
      closeTimer = setTimeout(() => {
        if (card && !card.engaged()) closeCard()
      }, HOVER_CLOSE)
    }
    const linkOf = (target: EventTarget | null) => {
      const el = target instanceof Element ? target : null
      const link = el?.closest("a[href]:not([data-attachment])") ?? null
      return link && view.dom.contains(link) ? link : null
    }
    const rangeOf = (link: Element) => {
      let pos: number
      try {
        pos = view.posAtDOM(link, 0)
      } catch {
        return null
      }
      const type = editor.state.schema.marks.link
      if (!type) return null
      const $pos = editor.state.doc.resolve(Math.min(pos + 1, editor.state.doc.content.size))
      return getMarkRange($pos, type) ?? null
    }
    const raise = (link: Element) => {
      const range = rangeOf(link)
      const href = link.getAttribute("href")
      if (!range || !href) return
      closeCard()
      const popup = openLinkPopup({ editor, href, autoFocus: false, range })
      card = { ...popup, link }
      popup.host.addEventListener("mouseenter", () => clearTimeout(closeTimer))
      popup.host.addEventListener("mouseleave", scheduleClose)
      void popup.done.then((next) => {
        if (card?.host === popup.host) card = null
        if (next === null || editor.isDestroyed) return
        applyLink(editor, range, next)
      })
    }

    const onOver = (event: MouseEvent) => {
      if (!view.editable || event.buttons !== 0) return
      const link = linkOf(event.target)
      if (!link) return
      // a selection has its own bar; the card does not come over it
      if (!editor.state.selection.empty) return
      if (card?.link === link) {
        clearTimeout(closeTimer)
        return
      }
      if (pending === link) return
      pending = link
      clearTimeout(openTimer)
      openTimer = setTimeout(() => {
        pending = null
        if (!editor.state.selection.empty || editor.isDestroyed) return
        if (!link.isConnected) return
        raise(link)
      }, HOVER_OPEN)
    }
    const onOut = (event: MouseEvent) => {
      const link = linkOf(event.target)
      if (!link) return
      const to = event.relatedTarget
      if (to instanceof Node && (link.contains(to) || card?.host.contains(to))) return
      if (pending === link) {
        pending = null
        clearTimeout(openTimer)
      }
      if (card?.link === link) scheduleClose()
    }
    // a press in the document (a selection begun, a caret placed) sends it
    const onDown = () => {
      clearTimeout(openTimer)
      pending = null
    }

    view.dom.addEventListener("mouseover", onOver)
    view.dom.addEventListener("mouseout", onOut)
    view.dom.addEventListener("mousedown", onDown)

    const key = new PluginKey("rteLinkClick")
    editor.registerPlugin(
      new Plugin({
        key,
        props: {
          handleClick(v, _pos, event) {
            if (!v.editable || event.button !== 0) return false
            const link = linkOf(event.target)
            const href = link?.getAttribute("href")
            if (!href) return false
            event.preventDefault()
            closeCard()
            window.open(href, "_blank", "noopener,noreferrer")
            return true
          },
        },
      })
    )
    return () => {
      clearTimeout(openTimer)
      closeCard()
      view.dom.removeEventListener("mouseover", onOver)
      view.dom.removeEventListener("mouseout", onOut)
      view.dom.removeEventListener("mousedown", onDown)
      if (!editor.isDestroyed) editor.unregisterPlugin(key)
    }
  }, [editor])
  return null
}

"use client"

// Notion's column bar, ported from the branch's RteColumnResizer. In the
// gap between two columns a bar stands under the pointer — on the hairline
// of a text row, in the middle of a picture row's gutter — and dragging it
// gives one column what it takes from the other; the rest of the row keeps
// its shares. The shares are kept on the row (`widths`, extensions.tsx) so
// a row drawn again, or reloaded, keeps its proportions, and a row
// re-counted starts equal again.
import * as React from "react"
import { createPortal } from "react-dom"
import type { Editor as TiptapEditor } from "@tiptap/core"

import { cn } from "@/lib/utils"

import { SMOOTH_SKIP } from "./extensions"
import { pressHandlers, type PressEvent } from "./press"

/** no column goes under this share of its row */
const MIN_SHARE = 0.1
/** how far either side of the gap the bar still answers */
const REACH = 6
/** how near a resting place the bar has to come to settle on it, in px */
const SNAP = 10
/** the row's even splits a boundary settles on */
const SPLITS = [1 / 4, 1 / 3, 1 / 2, 2 / 3, 3 / 4]
/** how quickly the row catches the boundary up, in ms: a time constant */
const EASE = 40

interface Gap {
  row: HTMLElement
  cells: HTMLElement[]
  /** the gap after this cell */
  index: number
  /** where the bar stands */
  x: number
  /** the span the bar answers in, which the press zone covers */
  from: number
  to: number
}

export function ColumnResizer({ editor }: { editor: TiptapEditor }) {
  const [bar, setBar] = React.useState<{
    left: number
    top: number
    height: number
    /** the press zone: wherever the bar shows, a press takes it */
    from: number
    to: number
  } | null>(null)
  const [dragging, setDragging] = React.useState(false)
  /** the bar rests on one of the row's even splits */
  const [snapped, setSnapped] = React.useState(false)
  const hit = React.useRef<Gap | null>(null)
  const draggingRef = React.useRef(false)
  draggingRef.current = dragging
  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => setMounted(true), [])

  /** the gap under the pointer, in any row of columns */
  const gapAt = React.useCallback(
    (x: number, y: number): Gap | null => {
      if (editor.isDestroyed || !editor.isEditable) return null
      const rows = editor.view.dom.querySelectorAll<HTMLElement>(
        '[data-type="columns"]'
      )
      for (const row of rows) {
        const r = row.getBoundingClientRect()
        if (y < r.top || y >= r.bottom || x < r.left || x > r.right) continue
        const cells = [...row.children].filter(
          (c): c is HTMLElement => c instanceof HTMLElement
        )
        for (let i = 0; i < cells.length - 1; i++) {
          const a = cells[i].getBoundingClientRect()
          const b = cells[i + 1].getBoundingClientRect()
          // stacked, on a narrow page: no gap to take hold of
          if (b.left <= a.right) continue
          if (x < a.right - REACH || x > b.left + REACH) continue
          // the bar stands in the middle of the gap: on a text row's
          // hairline, and where a picture row's would be
          const at = (a.right + b.left) / 2
          return {
            row,
            cells,
            index: i,
            x: at,
            from: a.right - REACH,
            to: b.left + REACH,
          }
        }
      }
      return null
    },
    [editor]
  )

  React.useEffect(() => {
    const onMove = (e: MouseEvent) => {
      if (draggingRef.current) return
      // a picture's own resize pill, a block's grip in the gap, or a
      // picture resize under way, is no column gap: the bar would stand
      // beside the pill or the grip and read as theirs
      const onPill =
        e.target instanceof Element &&
        !!e.target.closest('[aria-label^="Resize media"], .rte-bh-handle')
      if (onPill || document.body.classList.contains("rte-media-resizing")) {
        hit.current = null
        setBar(null)
        return
      }
      const gap = gapAt(e.clientX, e.clientY)
      hit.current = gap
      if (!gap) {
        setBar(null)
        return
      }
      const r = gap.row.getBoundingClientRect()
      setBar({
        left: gap.x,
        top: r.top,
        height: r.height,
        from: gap.from,
        to: gap.to,
      })
    }
    const hide = () => {
      if (!draggingRef.current) setBar(null)
    }
    document.addEventListener("mousemove", onMove, true)
    document.addEventListener("scroll", hide, true)
    document.addEventListener("mouseleave", hide)
    return () => {
      document.removeEventListener("mousemove", onMove, true)
      document.removeEventListener("scroll", hide, true)
      document.removeEventListener("mouseleave", hide)
    }
  }, [gapAt])

  /** the position of the row's node, by the element the view draws it with */
  const posOf = (row: HTMLElement): number | null => {
    if (editor.isDestroyed) return null
    let found: number | null = null
    editor.state.doc.descendants((node, pos) => {
      if (found !== null) return false
      if (node.type.name === "columns" && editor.view.nodeDOM(pos) === row)
        found = pos
      return found === null
    })
    return found
  }

  const onDown = (e: PressEvent<HTMLDivElement>) => {
    const gap = hit.current
    if (!gap || e.button !== 0 || editor.isDestroyed) return
    const pos = posOf(gap.row)
    if (pos === null) return
    e.preventDefault()
    const { index } = gap
    const start = gap.cells.map((c) => c.getBoundingClientRect().width)
    const total = start.reduce((sum, w) => sum + w, 0)
    const pair = start[index] + start[index + 1]
    const floor = total * MIN_SHARE
    const x0 = e.clientX
    const original =
      (editor.state.doc.nodeAt(pos)?.attrs.widths as number[] | null) ?? null
    let shares = start.map((w) => w / total)

    // The places the boundary settles on, as the width of the column before
    // it: the row cut in quarters or thirds, the two columns even, and
    // either one as wide as another column of the row, so a row of three
    // can be put back even by eye.
    const before = start.slice(0, index).reduce((sum, w) => sum + w, 0)
    const rests = [
      ...SPLITS.map((f) => total * f - before),
      pair / 2,
      ...start.flatMap((w, i) =>
        i === index || i === index + 1 ? [] : [w, pair - w]
      ),
    ].filter((w) => w >= floor && w <= pair - floor)
    const settle = (w: number) => {
      let best: number | null = null
      for (const r of rests) {
        const off = Math.abs(r - w)
        if (off <= SNAP && (best === null || off < Math.abs(best - w))) best = r
      }
      return best
    }

    // The shares go through the document, never onto the row's element: an
    // inline style written there is a mutation ProseMirror answers by
    // drawing the node again. On release the row is put back as it began
    // and the drag written as one step, so one undo takes the whole of it.
    const write = (widths: number[] | null, record: boolean) => {
      if (editor.isDestroyed) return
      const node = editor.state.doc.nodeAt(pos)
      if (!node || node.type.name !== "columns") return
      const tr = editor.state.tr.setNodeMarkup(pos, undefined, {
        ...node.attrs,
        widths,
      })
      tr.setMeta(SMOOTH_SKIP, true)
      if (!record) tr.setMeta("addToHistory", false)
      editor.view.dispatch(tr)
    }

    setDragging(true)
    draggingRef.current = true
    document.body.classList.add("rte-col-drag")

    // The pointer sets where the boundary is headed; the row eases there a
    // frame at a time, so a snap, and the text wrapping again with it,
    // glides over instead of jumping. Each frame closes the same part of
    // what is left whatever the frame rate.
    const still = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    let target = start[index]
    let shown = start[index]
    let last = 0
    let frame = 0
    let released = false
    const draw = (a: number) => {
      const next = start.slice()
      next[index] = a
      next[index + 1] = pair - a
      shares = next.map((w) => w / total)
      write(shares, false)
      // the row is drawn anew with each share: the bar follows the
      // boundary the new drawing puts down
      const row = editor.view.nodeDOM(pos)
      if (!(row instanceof HTMLElement)) return
      const cells = [...row.children].filter(
        (c): c is HTMLElement => c instanceof HTMLElement
      )
      const ra = cells[index]?.getBoundingClientRect()
      const rb = cells[index + 1]?.getBoundingClientRect()
      // the text wraps again as the columns change: the bar grows and
      // shrinks with the row, as the hairline does
      const rr = row.getBoundingClientRect()
      if (ra && rb)
        setBar((b) =>
          b
            ? {
                ...b,
                top: rr.top,
                height: rr.height,
                left: (ra.right + rb.left) / 2,
                from: ra.right - REACH,
                to: rb.left + REACH,
              }
            : b
        )
    }
    const step = (now: number) => {
      frame = 0
      const dt = last ? Math.min(now - last, 64) : 16
      last = now
      const left = target - shown
      shown =
        still || Math.abs(left) < 0.3
          ? target
          : shown + left * (1 - Math.exp(-dt / EASE))
      draw(shown)
      if (shown !== target) frame = requestAnimationFrame(step)
      else if (released) finish()
      else last = 0
    }
    const move = (ev: PointerEvent) => {
      const dx = ev.clientX - x0
      const free = Math.min(Math.max(start[index] + dx, floor), pair - floor)
      const rest = settle(free)
      target = rest ?? free
      setSnapped(rest !== null)
      if (!frame) frame = requestAnimationFrame(step)
    }
    const up = () => {
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", up)
      window.removeEventListener("pointercancel", up)
      released = true
      // the row lands where it was headed before the drag is written down
      if (!frame) finish()
    }
    const finish = () => {
      document.body.classList.remove("rte-col-drag")
      setDragging(false)
      setSnapped(false)
      draggingRef.current = false
      write(original, false)
      write(shares, true)
      hit.current = null
      setBar(null)
    }
    // the window follows the pointer: a press WebKit started without a
    // pointerdown can take no capture
    window.addEventListener("pointermove", move)
    window.addEventListener("pointerup", up)
    window.addEventListener("pointercancel", up)
  }

  if (!mounted || (!bar && !dragging)) return null
  // the zone spans the whole reach the bar answers in, so a press wherever
  // the bar is showing takes it; the bar itself stays on its boundary
  const zone = bar
    ? {
        left: Math.min(bar.from, bar.left - 6),
        width: Math.max(bar.to, bar.left + 6) - Math.min(bar.from, bar.left - 6),
      }
    : null
  return createPortal(
    <div
      className={cn("rte-cr", dragging && "is-dragging", snapped && "is-snapped")}
      style={
        bar && zone
          ? {
              left: zone.left,
              width: zone.width,
              marginLeft: 0,
              justifyContent: "flex-start",
              top: bar.top,
              height: bar.height,
            }
          : undefined
      }
      aria-hidden="true"
      {...pressHandlers(onDown)}
    >
      <div
        className="rte-cr-bar"
        style={bar && zone ? { marginLeft: bar.left - zone.left - 1.5 } : undefined}
      />
    </div>,
    document.body
  )
}

/**
 * Shared URL-safety primitives, ported from the branch's
 * extensions/shared/url-safety.ts. Two concerns, kept deliberately small
 * and pure:
 *  1. `isSafeUrl` — does a string parse to an absolute URL with an allowed
 *     scheme?
 *  2. `matchesHostname` — exact-or-dot-boundary host allowlist matching,
 *     never substring (so `youtube.com.evil.com` does not match
 *     `youtube.com`).
 */

export interface SafeUrlOptions {
  /** Schemes allowed (without the trailing colon). Defaults to http/https. */
  allowedSchemes?: string[]
  /**
   * Optional base to resolve relative URLs against (e.g.
   * `window.location.origin`). A server-relative `/files/x.png` resolves to
   * an http(s) URL and passes; `javascript:`/`data:` still parse to their
   * own scheme and fail.
   */
  base?: string
}

const DEFAULT_SCHEMES: readonly string[] = ["http", "https"]

const normalizeScheme = (scheme: string) =>
  scheme.toLowerCase().replace(/:$/, "")

/**
 * True iff `url` parses as an absolute URL whose scheme is allowed.
 * Relative paths, bare slugs, anchors and protocol-relative strings all
 * fail (unless a `base` is given); `javascript:`, `data:` and the rest
 * fail unless explicitly allowed.
 */
export function isSafeUrl(url: string, options?: SafeUrlOptions): boolean {
  if (typeof url !== "string" || url.trim() === "") return false

  const allowedSchemes = (options?.allowedSchemes ?? DEFAULT_SCHEMES).map(
    normalizeScheme
  )

  let parsed: URL
  try {
    parsed = new URL(url, options?.base)
  } catch {
    return false
  }

  return allowedSchemes.includes(normalizeScheme(parsed.protocol))
}

/**
 * Exact host match OR dot-boundary suffix match against an allowlist:
 * `a.youtube.com` matches `youtube.com`; `youtube.com.evil.com` does not.
 * Comparison is case-insensitive.
 */
export function matchesHostname(
  host: string,
  allowlist: readonly string[]
): boolean {
  if (!host) return false
  const normalizedHost = host.toLowerCase()

  return allowlist.some((entry) => {
    const normalizedEntry = entry.toLowerCase().replace(/^\.+/, "")
    if (!normalizedEntry) return false
    return (
      normalizedHost === normalizedEntry ||
      normalizedHost.endsWith("." + normalizedEntry)
    )
  })
}

/**
 * The embed allowlist, validator and URL transforms, ported from the
 * branch's iframe-allowlist.ts and iframe-embed-utils.ts: which hosts an
 * embed may frame, the one validator every way in runs, per-platform
 * sizing, and the rewrites that turn watch/share URLs into their
 * embeddable form (youtu.be + /shorts + playlists, vimeo's unlisted hash,
 * codepen pens, figma design/file/proto/board).
 */
import { isSafeUrl, matchesHostname } from "./url-safety"

/** Hostnames (and their embed sub-hosts) permitted as iframe sources. */
export const IFRAME_ALLOWLIST: readonly string[] = [
  "youtube.com",
  "youtu.be",
  "youtube-nocookie.com",
  "vimeo.com",
  "player.vimeo.com",
  "codepen.io",
  "codesandbox.io",
  "figma.com",
  "embed.figma.com",
  "docs.google.com",
  "drive.google.com",
  "notion.so",
]

/** The one entry that opens an allowlist to every http(s) host. */
export const ANY_HOST = "*"

export interface ValidateIframeUrlOptions {
  /** Override the default allowlist (exact host or dot-boundary suffix). */
  allowlist?: readonly string[]
  /** Hosts to reject outright. */
  blocklist?: readonly string[]
}

/**
 * True iff `url` is an absolute http(s) URL whose hostname is on the
 * allowlist (and not on an optional blocklist). Relative, bare and
 * unknown-scheme inputs are rejected — there is no `startsWith('/')`
 * escape hatch. An allowlist holding {@link ANY_HOST} takes every host
 * the blocklist does not refuse.
 */
export function validateIframeUrl(
  url: string,
  options?: ValidateIframeUrlOptions
): boolean {
  if (!isSafeUrl(url, { allowedSchemes: ["http", "https"] })) return false

  let host: string
  try {
    host = new URL(url).hostname
  } catch {
    return false
  }

  const blocklist = options?.blocklist
  if (blocklist?.length && matchesHostname(host, blocklist)) return false

  const allowlist = options?.allowlist ?? IFRAME_ALLOWLIST
  return allowlist.includes(ANY_HOST) || matchesHostname(host, allowlist)
}

export interface AspectRatioInfo {
  /** height / width, as the branch expresses it */
  ratio: number
  width: number
  height: number
  platform: string
}

interface PlatformConfig {
  name: string
  /** aspect ratio expressed as height / width */
  ratio: number
  defaultWidth: number
  hosts: readonly string[]
}

/** Per-platform sizing + host ownership. */
const PLATFORM_CONFIGS: readonly PlatformConfig[] = [
  {
    name: "YouTube",
    ratio: 9 / 16,
    defaultWidth: 640,
    hosts: ["youtube.com", "youtu.be", "youtube-nocookie.com"],
  },
  {
    name: "Vimeo",
    ratio: 9 / 16,
    defaultWidth: 640,
    hosts: ["vimeo.com", "player.vimeo.com"],
  },
  { name: "CodePen", ratio: 3 / 2, defaultWidth: 500, hosts: ["codepen.io"] },
  {
    name: "CodeSandbox",
    ratio: 3 / 2,
    defaultWidth: 500,
    hosts: ["codesandbox.io"],
  },
  {
    name: "Figma",
    ratio: 9 / 16,
    defaultWidth: 800,
    hosts: ["figma.com", "embed.figma.com"],
  },
  {
    name: "Google Docs",
    ratio: 4 / 3,
    defaultWidth: 600,
    hosts: ["docs.google.com", "drive.google.com"],
  },
  { name: "Notion", ratio: 4 / 3, defaultWidth: 600, hosts: ["notion.so"] },
]

/** Resolve the platform config for a URL, or null when unknown. */
function detectPlatform(url: string): PlatformConfig | null {
  let host: string
  try {
    host = new URL(url).hostname
  } catch {
    return null
  }
  return (
    PLATFORM_CONFIGS.find((config) => matchesHostname(host, config.hosts)) ??
    null
  )
}

/** Compute the natural aspect ratio + default size for a URL's platform. */
export function calculateAspectRatio(url: string): AspectRatioInfo {
  const platform = detectPlatform(url)
  if (platform) {
    return {
      ratio: platform.ratio,
      width: platform.defaultWidth,
      height: Math.round(platform.defaultWidth * platform.ratio),
      platform: platform.name,
    }
  }
  return { ratio: 9 / 16, width: 640, height: 360, platform: "Generic" }
}

/** Rewrite a platform watch/share URL into its embeddable form. */
export function processEmbedUrl(url: string): string {
  const platform = detectPlatform(url)
  switch (platform?.name) {
    case "YouTube":
      return convertYouTube(url)
    case "Vimeo":
      return convertVimeo(url)
    case "CodePen":
      return convertCodePen(url)
    case "Figma":
      return convertFigma(url)
    default:
      return url
  }
}

/** Extract a YouTube video id from any of its URL shapes. */
function youTubeVideoId(parsed: URL): string {
  if (matchesHostname(parsed.hostname, ["youtu.be"])) {
    return parsed.pathname.slice(1).split("/")[0]
  }
  const segments = parsed.pathname.split("/").filter(Boolean)
  if (segments[0] === "shorts" || segments[0] === "live") {
    return segments[1] ?? ""
  }
  if (segments[0] === "embed") return segments[1] ?? ""
  return parsed.searchParams.get("v") ?? ""
}

function convertYouTube(url: string): string {
  let parsed: URL
  try {
    parsed = new URL(url)
  } catch {
    return url
  }

  // already an embed URL — leave untouched
  if (parsed.pathname.startsWith("/embed/")) return url

  const videoId = youTubeVideoId(parsed)
  if (!videoId) return url

  const params = new URLSearchParams({ rel: "0", modestbranding: "1" })
  const list = parsed.searchParams.get("list")
  if (list) params.set("list", list)
  const start =
    parsed.searchParams.get("t") ?? parsed.searchParams.get("start")
  if (start) params.set("start", start.replace(/s$/, ""))

  return `https://www.youtube.com/embed/${videoId}?${params.toString()}`
}

function convertVimeo(url: string): string {
  let parsed: URL
  try {
    parsed = new URL(url)
  } catch {
    return url
  }

  if (matchesHostname(parsed.hostname, ["player.vimeo.com"])) return url

  const segments = parsed.pathname.split("/").filter(Boolean)
  const id = segments.find((seg) => /^\d+$/.test(seg))
  if (!id) return url

  // preserve the unlisted hash (`vimeo.com/<id>/<hash>`) as `?h=<hash>`
  const idIndex = segments.indexOf(id)
  const hash = segments[idIndex + 1]
  const params = new URLSearchParams({
    title: "0",
    byline: "0",
    portrait: "0",
  })
  if (hash && /^[0-9a-f]+$/i.test(hash)) params.set("h", hash)

  return `https://player.vimeo.com/video/${id}?${params.toString()}`
}

function convertCodePen(url: string): string {
  let parsed: URL
  try {
    parsed = new URL(url)
  } catch {
    return url
  }
  if (parsed.pathname.includes("/embed/")) return url

  const match = parsed.pathname.match(/^\/([^/]+)\/pen\/([^/]+)/)
  if (match) {
    return `https://codepen.io/${match[1]}/embed/${match[2]}?default-tab=result`
  }
  return url
}

function convertFigma(url: string): string {
  let parsed: URL
  try {
    parsed = new URL(url)
  } catch {
    return url
  }

  // already an embed host — just ensure embed-host is present
  if (matchesHostname(parsed.hostname, ["embed.figma.com"])) {
    if (!parsed.searchParams.has("embed-host")) {
      parsed.searchParams.set("embed-host", "share")
    }
    return parsed.toString()
  }

  // figma.com/{design,file,proto,board}/... → embed.figma.com/...
  const embeddable = /^\/(design|file|proto|board)\//.test(parsed.pathname)
  if (matchesHostname(parsed.hostname, ["figma.com"]) && embeddable) {
    parsed.hostname = "embed.figma.com"
    parsed.searchParams.set("embed-host", "share")
    return parsed.toString()
  }

  return url
}

/**
 * A file the browser cannot show is turned away at the door with a message
 * naming what would do — ported from the branch's image-engine. HEIC off
 * an iPhone would otherwise stage a preview that never draws.
 */
export function unsupportedImageMessage(file: File): string | null {
  const name = file.name?.toLowerCase() ?? ""
  if (
    /^image\/hei[cf]$/i.test(file.type) ||
    name.endsWith(".heic") ||
    name.endsWith(".heif")
  ) {
    return "Unsupported file. HEIC images cannot be shown here — save it as JPG or PNG first."
  }
  if (!/^image\//i.test(file.type)) {
    return "Unsupported file. Only an image can go here — JPG, PNG, GIF, WEBP or SVG."
  }
  return null
}

import type * as React from "react"

/**
 * Press handlers for the editor's own controls (the column bar, the table
 * grips, the picture pills, the block grip). WebKit loses one pointerdown:
 * the first press after a native drag-and-drop arrives as a mousedown with
 * no pointerdown before it, though the pointer still moves and lifts as
 * usual. A control started on pointerdown alone would ignore that press,
 * so `start` runs from whichever comes, once per press.
 */
let lastPointerDown = Number.NEGATIVE_INFINITY

export type PressEvent<E extends Element = Element> =
  | React.PointerEvent<E>
  | React.MouseEvent<E>

/** the pointer a press belongs to; -1 when it came without one */
export const pressPointerId = (e: PressEvent): number =>
  "pointerId" in e ? e.pointerId : -1

export function pressHandlers<E extends Element>(
  start: (e: PressEvent<E>) => void
) {
  return {
    onPointerDown: (e: React.PointerEvent<E>) => {
      lastPointerDown = e.timeStamp
      start(e)
    },
    onMouseDown: (e: React.MouseEvent<E>) => {
      // the press a pointerdown already started
      if (e.timeStamp - lastPointerDown < 500) return
      start(e)
    },
  }
}

"use client"

// Notion's box selection. A press in the empty page around the document,
// dragged, draws a box; every block it touches is chosen whole and tinted,
// as it is drawn and after. The choice is a run of the document's
// top-level blocks, kept beside the editor's own selection: Backspace or
// Delete takes them all away, copy and cut carry them, Escape, a click or
// a key lets them go.
import * as React from "react"
import { createPortal } from "react-dom"
import { Extension, type Editor as TiptapEditor } from "@tiptap/core"
import {
  Plugin,
  PluginKey,
  TextSelection,
  type EditorState,
} from "@tiptap/pm/state"
import { Decoration, DecorationSet, type EditorView } from "@tiptap/pm/view"

/** the run of sibling blocks chosen, as document positions: the page's own
 * blocks as the box chooses them, or a column's, carried there */
export interface BlockRange {
  from: number
  to: number
}

export const blockSelectKey = new PluginKey<BlockRange | null>(
  "rteBlockSelect"
)

/** the blocks chosen, if any */
export const chosenBlocks = (state: EditorState) =>
  blockSelectKey.getState(state) ?? null

/** a step that chooses `range`, or lets the choice go */
const choose = (view: EditorView, range: BlockRange | null) => {
  const { state } = view
  const tr = state.tr.setMeta(blockSelectKey, range)
  // the caret waits, unseen, at the first block chosen, so the keys and
  // the clipboard come to the document
  if (range) {
    const near = TextSelection.near(state.doc.resolve(range.from))
    tr.setSelection(near)
  }
  view.dispatch(tr)
}

/** each block of the run, with its position */
export function eachChosen(
  doc: EditorState["doc"],
  range: BlockRange,
  f: (node: EditorState["doc"], pos: number) => void
) {
  const $from = doc.resolve(range.from)
  const start = $from.start()
  $from.parent.forEach((node, offset) => {
    const pos = start + offset
    if (pos >= range.from && pos + node.nodeSize <= range.to) f(node, pos)
  })
}

/** the chosen blocks taken away, a line left if they were all there was */
const remove = (view: EditorView, range: BlockRange) => {
  const { state } = view
  const tr = state.tr
  let { from, to } = range
  let $from = state.doc.resolve(from)
  // every item of a list chosen: the list goes, as many levels up as are
  // left empty by it
  while (
    LISTS.has($from.parent.type.name) &&
    from === $from.start() &&
    to === $from.end() &&
    $from.depth > 0
  ) {
    from = $from.before()
    to = $from.after()
    $from = state.doc.resolve(from)
  }
  if (from === $from.start() && to === $from.end())
    tr.replaceWith(from, to, state.schema.nodes.paragraph.create())
  else tr.delete(from, to)
  const at = Math.min(from, tr.doc.content.size)
  tr.setSelection(TextSelection.near(tr.doc.resolve(at), -1))
  tr.setMeta(blockSelectKey, null)
  view.dispatch(tr.scrollIntoView())
}

export const BlockSelect = Extension.create({
  name: "rteBlockSelect",
  addProseMirrorPlugins() {
    return [
      new Plugin<BlockRange | null>({
        key: blockSelectKey,
        state: {
          init: () => null,
          apply(tr, value) {
            const meta = tr.getMeta(blockSelectKey) as
              | BlockRange
              | null
              | undefined
            if (meta !== undefined) return meta
            // a step the editor adds after another (a trailing line set
            // after the last block) carries the chosen blocks along
            if (value && tr.getMeta("appendedTransaction")) {
              const from = tr.mapping.map(value.from, 1)
              const to = tr.mapping.map(value.to, -1)
              return from < to ? { from, to } : null
            }
            // any edit, or the caret moved by a click or a key, lets go
            if (!value || tr.docChanged || tr.selectionSet) return null
            return value
          },
        },
        props: {
          decorations(state) {
            const range = blockSelectKey.getState(state)
            if (!range) return null
            const marks: Decoration[] = []
            eachChosen(state.doc, range, (node, pos) =>
              marks.push(
                Decoration.node(pos, pos + node.nodeSize, {
                  class: "rte-block-chosen",
                })
              )
            )
            return DecorationSet.create(state.doc, marks)
          },
          attributes(state): Record<string, string> {
            return blockSelectKey.getState(state)
              ? { class: "has-chosen-blocks" }
              : {}
          },
          handleKeyDown(view, event) {
            const range = blockSelectKey.getState(view.state)
            if (!range) return false
            if (event.key === "Backspace" || event.key === "Delete") {
              remove(view, range)
              return true
            }
            // Tab stays on the page, the blocks still chosen
            if (event.key === "Tab") return true
            if (event.key === "Escape") {
              choose(view, null)
              return true
            }
            // copy and cut go on to the clipboard's own events; a modifier
            // alone changes nothing
            const mod = event.metaKey || event.ctrlKey
            if (mod && ["c", "x"].includes(event.key.toLowerCase())) return false
            if (["Meta", "Control", "Shift", "Alt"].includes(event.key))
              return false
            // any other key lets the blocks go and does what it does
            choose(view, null)
            return false
          },
          handleDOMEvents: {
            copy: (view, event) => carry(view, event, false),
            cut: (view, event) => carry(view, event, true),
          },
        },
      }),
    ]
  },
})

/** the chosen blocks put on the clipboard, and taken away on a cut */
function carry(view: EditorView, event: ClipboardEvent, cut: boolean) {
  const range = blockSelectKey.getState(view.state)
  if (!range || !event.clipboardData) return false
  event.preventDefault()
  const slice = view.state.doc.slice(range.from, range.to)
  const { dom, text } = view.serializeForClipboard(slice)
  event.clipboardData.clearData()
  event.clipboardData.setData("text/html", dom.innerHTML)
  event.clipboardData.setData("text/plain", text)
  if (cut) remove(view, range)
  return true
}

const LISTS = new Set(["bulletList", "orderedList", "taskList"])
const ITEMS = new Set(["listItem", "taskItem"])

/** how far the pointer goes before a press becomes a box */
const START = 4
/** how near the scroller's edge the box starts scrolling it, in px */
const EDGE = 48

/**
 * The box itself: a press on the page around the document (never on a
 * block, a control or a menu) draws it, and as it grows the blocks it
 * touches are chosen.
 */
export function BlockMarquee({ editor }: { editor: TiptapEditor }) {
  const [box, setBox] = React.useState<{
    left: number
    top: number
    width: number
    height: number
  } | null>(null)

  React.useEffect(() => {
    if (editor.isDestroyed) return
    const view = editor.view
    const dom = view.dom as HTMLElement
    const stage = dom.closest<HTMLElement>('[data-slot="rich-text-editor"]')
    const scroller = dom.closest<HTMLElement>(
      '[data-slot="rich-text-editor-scroll"]'
    )
    if (!stage || !scroller) return

    const onDown = (e: MouseEvent) => {
      if (e.button !== 0 || !editor.isEditable) return
      const target = e.target as Element | null
      // the page around the document only: not a block, nor a control on it
      if (!target || !scroller.contains(target) || dom.contains(target)) return
      if (
        target.closest(
          'button, a, input, textarea, select, [role="menu"], [role="dialog"], .rte-bh-handle, .rte-cr'
        )
      )
        return
      // no text selection of the page, no focus taken from the document
      e.preventDefault()

      // the box is kept in the scroller's own frame, so it stays put on
      // the page as the page scrolls under it
      const frame = () => scroller.getBoundingClientRect()
      const startX = e.clientX - frame().left + scroller.scrollLeft
      const startY = e.clientY - frame().top + scroller.scrollTop
      let x = e.clientX
      let y = e.clientY
      let drawing = false
      let tick = 0

      const update = () => {
        const f = frame()
        const nowX = x - f.left + scroller.scrollLeft
        const nowY = y - f.top + scroller.scrollTop
        const left = Math.min(startX, nowX)
        const top = Math.min(startY, nowY)
        const width = Math.abs(nowX - startX)
        const height = Math.abs(nowY - startY)
        // drawn on the screen, where the portal stands
        const screen = {
          left: left + f.left - scroller.scrollLeft,
          top: top + f.top - scroller.scrollTop,
          width,
          height,
        }
        setBox(screen)
        // the blocks the box touches, as Notion picks them: among the page's
        // blocks, or — when it touches one block only, and only inside it
        // (an open toggle's body, clear of its title; one column of a row)
        // — among that block's own, as deep as that goes
        const touches = (el: Element) => {
          const r = el.getBoundingClientRect()
          return (
            r.right > screen.left &&
            r.left < screen.left + width &&
            r.bottom > screen.top &&
            r.top < screen.top + height
          )
        }
        let holder = view.state.doc
        let base = 0
        let hits: { pos: number; size: number }[] = []
        for (;;) {
          hits = []
          holder.forEach((node, offset) => {
            const pos = base + offset
            const el = view.nodeDOM(pos)
            if (el instanceof HTMLElement && touches(el))
              hits.push({ pos, size: node.nodeSize })
          })
          if (hits.length !== 1) break
          const only = hits[0]
          const node = view.state.doc.nodeAt(only.pos)
          const el = view.nodeDOM(only.pos)
          if (!node || !(el instanceof HTMLElement)) break
          if (node.type.name === "details" && el.classList.contains("is-open")) {
            const summary = el.querySelector(":scope > .rte-details-body > summary")
            if (!summary || touches(summary)) break
            // into the body: past the toggle's start and its title
            holder = node.lastChild!
            base = only.pos + 1 + node.firstChild!.nodeSize + 1
            continue
          }
          // a callout's blocks, clear of its first line (the callout's own)
          if (node.type.name === "callout") {
            const title = view.nodeDOM(only.pos + 1)
            if (!(title instanceof Element) || touches(title)) break
            holder = node
            base = only.pos + 1
            continue
          }
          // a list's items are blocks of their own: into the list, and
          // into an item when the box keeps off the item's own first line
          if (LISTS.has(node.type.name)) {
            holder = node
            base = only.pos + 1
            continue
          }
          if (ITEMS.has(node.type.name)) {
            const line = view.nodeDOM(only.pos + 1)
            if (!(line instanceof Element) || touches(line)) break
            holder = node
            base = only.pos + 1
            continue
          }
          if (node.type.name === "columns" && !node.attrs.media) {
            const cells = [...el.children].filter(touches)
            if (cells.length !== 1) break
            const index = [...el.children].indexOf(cells[0])
            let cellPos = only.pos + 1
            for (let i = 0; i < index; i++) cellPos += node.child(i).nodeSize
            holder = node.child(index)
            base = cellPos + 1
            continue
          }
          break
        }
        const first = hits.length ? hits[0].pos : null
        const last = hits.length
          ? hits[hits.length - 1].pos + hits[hits.length - 1].size
          : null
        const range = first !== null && last !== null ? { from: first, to: last } : null
        const was = blockSelectKey.getState(view.state)
        if (was?.from !== range?.from || was?.to !== range?.to)
          choose(view, range)
      }

      // near the scroller's top or bottom edge the page scrolls along
      const scroll = () => {
        tick = 0
        const f = frame()
        const step =
          y < f.top + EDGE
            ? -Math.ceil((f.top + EDGE - y) / 4)
            : y > f.bottom - EDGE
              ? Math.ceil((y - f.bottom + EDGE) / 4)
              : 0
        if (!step) return
        scroller.scrollTop += step
        update()
        tick = requestAnimationFrame(scroll)
      }

      const move = (ev: MouseEvent) => {
        x = ev.clientX
        y = ev.clientY
        if (!drawing) {
          if (Math.hypot(x - e.clientX, y - e.clientY) < START) return
          drawing = true
          document.body.classList.add("rte-marquee")
          // the blocks chosen before go when a new box starts
          choose(view, null)
        }
        update()
        if (!tick) tick = requestAnimationFrame(scroll)
      }
      const up = () => {
        window.removeEventListener("mousemove", move)
        window.removeEventListener("mouseup", up)
        cancelAnimationFrame(tick)
        document.body.classList.remove("rte-marquee")
        setBox(null)
        if (!drawing) {
          // a plain press on the page lets the chosen blocks go
          if (blockSelectKey.getState(view.state)) choose(view, null)
          return
        }
        // the keys come to the document, the caret unseen in it
        view.focus()
        // the click that ends the box is the box's, not a click on the page
        const swallow = (c: MouseEvent) => {
          c.stopPropagation()
          c.preventDefault()
        }
        window.addEventListener("click", swallow, { capture: true, once: true })
        setTimeout(
          () => window.removeEventListener("click", swallow, { capture: true }),
          0
        )
      }
      window.addEventListener("mousemove", move)
      window.addEventListener("mouseup", up)
    }

    scroller.addEventListener("mousedown", onDown)
    return () => scroller.removeEventListener("mousedown", onDown)
  }, [editor])

  if (!box) return null
  return createPortal(
    <div
      className="rte-marquee-box"
      aria-hidden="true"
      style={{
        left: box.left,
        top: box.top,
        width: box.width,
        height: box.height,
      }}
    />,
    document.body
  )
}
